1	package stratagit
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"maps"
9		"net/http"
10		"net/url"
11		"strings"
12		"sync"
13	
14		"github.com/entirehq/strata/git"
15		"github.com/go-git/go-git/v6/config"
16		"github.com/go-git/go-git/v6/plumbing"
17		"github.com/go-git/go-git/v6/plumbing/client"
18		"github.com/go-git/go-git/v6/plumbing/format/packfile"
19		"github.com/go-git/go-git/v6/plumbing/object"
20		"github.com/go-git/go-git/v6/plumbing/protocol"
21		"github.com/go-git/go-git/v6/plumbing/protocol/capability"
22		"github.com/go-git/go-git/v6/plumbing/protocol/packp"
23		"github.com/go-git/go-git/v6/plumbing/revlist"
24		"github.com/go-git/go-git/v6/plumbing/storer"
25		"github.com/go-git/go-git/v6/plumbing/transport"
26		"github.com/go-git/go-git/v6/storage"
27		"github.com/go-git/go-git/v6/storage/memory"
28	)
29	
30	// Transport is git.Transport over go-git's smart-HTTP client, for this package's
31	// repositories only: git.Repo cannot take in a pack, so fetched objects go
32	// straight into a Repo's storage.
33	type Transport struct {
34		Client *http.Client
35		// Context bounds every round trip, since strata's Transport methods take
36		// none. Nil means context.Background.
37		Context context.Context
38	}
39	
40	var _ git.Transport = Transport{}
41	
42	func (t Transport) ctx() context.Context {
43		if t.Context == nil {
44			return context.Background()
45		}
46		return t.Context
47	}
48	
49	func (Transport) url(repo git.Repo, remote string) (*url.URL, error) {
50		raw, err := repo.ConfigGet(remoteKey(remote, "url"))
51		if err != nil {
52			return nil, err
53		}
54		if raw == "" {
55			return nil, fmt.Errorf("stratagit: remote %s has no url", remote)
56		}
57		return transport.ParseURL(raw)
58	}
59	
60	func (Transport) own(repo git.Repo) (*Repo, error) {
61		r, ok := repo.(*Repo)
62		if !ok {
63			return nil, fmt.Errorf("stratagit: transport needs a stratagit repository, got %T", repo)
64		}
65		return r, nil
66	}
67	
68	func (t Transport) session(repo git.Repo, remote, svc string) (transport.Session, error) {
69		ep, err := t.url(repo, remote)
70		if err != nil {
71			return nil, err
72		}
73		var opts []client.Option
74		if t.Client != nil {
75			opts = append(opts, client.WithHTTPClient(t.Client))
76		}
77		req := &transport.Request{URL: ep, Command: svc}
78		if svc == transport.UploadPackService {
79			// v2, so ref discovery takes prefixes. There is no v2 push.
80			req.Protocol = protocol.V2
81		}
82		return client.New(opts...).Handshake(t.ctx(), req)
83	}
84	
85	// Caps falls back to upload-pack when receive-pack discovery is refused: strata
86	// asks before a fetch too, and entiredb refuses receive-pack to a caller who may
87	// only read. ReportStatus is then reported held, since such a caller can't land
88	// a push; Push checks the real advertisement before it sends anything.
89	func (t Transport) Caps(repo git.Repo, remote string) (git.Caps, error) {
90		sess, err := t.session(repo, remote, transport.ReceivePackService)
91		if errors.Is(err, transport.ErrAuthorizationFailed) || errors.Is(err, transport.ErrAuthenticationRequired) {
92			read, rerr := t.session(repo, remote, transport.UploadPackService)
93			if rerr != nil {
94				return git.Caps{}, rerr
95			}
96			_ = read.Close()
97			return git.Caps{ReportStatus: true}, nil
98		}
99		if err != nil {
100			return git.Caps{}, err
101		}
102		defer func() { _ = sess.Close() }()
103		return capsOf(sess), nil
104	}
105	
106	func capsOf(sess transport.Session) git.Caps {
107		caps := sess.Capabilities()
108		return git.Caps{
109			Atomic:       caps.Supports(capability.Atomic),
110			ReportStatus: caps.Supports(capability.ReportStatus),
111		}
112	}
113	
114	func (t Transport) LsRemote(repo git.Repo, remote, prefix string) (map[string]string, error) {
115		sess, err := t.session(repo, remote, transport.UploadPackService)
116		if err != nil {
117			return nil, err
118		}
119		defer func() { _ = sess.Close() }()
120		prefix = git.Prefix(prefix)
121		// The prefix goes without a trailing slash so an exact ref is included;
122		// under drops the siblings that also lets through.
123		var filter []string
124		if prefix != "" {
125			filter = []string{prefix}
126		}
127		refs, err := t.list(sess, filter)
128		if err != nil {
129			return nil, err
130		}
131		out := map[string]string{}
132		for _, r := range refs {
133			// An unborn HEAD arrives with no object.
134			if r.Hash().IsZero() {
135				continue
136			}
137			if name := r.Name().String(); under(prefix, name) {
138				out[name] = r.Hash().String()
139			}
140		}
141		return out, nil
142	}
143	
144	func (t Transport) Push(repo git.Repo, remote string, publish []string, withdraw []git.Withdrawal) error {
145		if len(publish) == 0 && len(withdraw) == 0 {
146			return nil
147		}
148		ctx := t.ctx()
149		sess, err := t.session(repo, remote, transport.ReceivePackService)
150		if err != nil {
151			return err
152		}
153		defer func() { _ = sess.Close() }()
154		// Again here, as Caps may not have seen this advertisement. Without
155		// report-status go-git reports success unread.
156		if err := capsOf(sess).Require(remote); err != nil {
157			return err
158		}
159	
160		advertised, err := sess.GetRemoteRefs(ctx, nil)
161		if err != nil {
162			return err
163		}
164		old := map[string]plumbing.Hash{}
165		for _, r := range advertised.References {
166			old[r.Name().String()] = r.Hash()
167		}
168		r, err := t.own(repo)
169		if err != nil {
170			return err
171		}
172		st := r.objects()
173	
174		var cmds []*packp.Command
175		var wants, haves []plumbing.Hash
176		var refused []string
177		for _, ref := range publish {
178			oid, err := repo.Ref(ref)
179			if err != nil {
180				return err
181			}
182			if oid == "" {
183				return fmt.Errorf("stratagit: %s does not exist locally", ref)
184			}
185			h := plumbing.NewHash(oid)
186			prev := old[ref]
187			if prev == h {
188				continue
189			}
190			// Old from the advertisement makes the push a compare-and-swap.
191			// receive-pack enforces only that; refusing a non-fast-forward is
192			// send-pack's job, and strata relies on it to arbitrate racing
193			// compactors (its ADR-0010).
194			if !prev.IsZero() && prev != h {
195				ff, err := fastForward(st, prev, h)
196				if err != nil {
197					return fmt.Errorf("stratagit: %s: checking %s is a fast-forward of %s: %w", ref, h, prev, err)
198				}
199				if !ff {
200					refused = append(refused, fmt.Sprintf("%s: %s is not a fast-forward of %s", ref, h, prev))
201					continue
202				}
203			}
204			cmds = append(cmds, &packp.Command{Name: plumbing.ReferenceName(ref), Old: prev, New: h})
205			wants = append(wants, h)
206			// Only the pushed refs' remote tips, as send-pack does: every
207			// advertised ref would cost a walk per held tip.
208			if !prev.IsZero() {
209				haves = append(haves, prev)
210			}
211		}
212		for _, w := range withdraw {
213			// receive-pack checks only its own advertisement, so the lease is checked
214			// here. An absent ref fails it, as with --force-with-lease.
215			if w.Old != "" && old[w.Ref] != plumbing.NewHash(w.Old) {
216				refused = append(refused, fmt.Sprintf("%s: stale info, holds %s and the lease was %s", w.Ref, old[w.Ref], w.Old))
217				continue
218			}
219			// Already gone. A zero-to-zero command would make go-git refuse the
220			// whole push.
221			if old[w.Ref].IsZero() {
222				continue
223			}
224			cmds = append(cmds, &packp.Command{Name: plumbing.ReferenceName(w.Ref), Old: old[w.Ref], New: plumbing.ZeroHash})
225		}
226		if len(cmds) == 0 {
227			return refusal(refused)
228		}
229	
230		req := &transport.PushRequest{Commands: cmds}
231		// finish waits for the pack encoder's goroutine on every path, so it never
232		// reads the store after Push returns; closing the pipe stops it.
233		finish := func() error { return nil }
234		if len(wants) > 0 {
235			hashes, err := revlist.Objects(st, wants, haves)
236			if err != nil {
237				return fmt.Errorf("stratagit: selecting objects to send: %w", err)
238			}
239			rd, wr := io.Pipe()
240			req.Packfile = rd
241			encoded := make(chan error, 1)
242			go func() {
243				enc := packfile.NewEncoder(wr, st, !sess.Capabilities().Supports(capability.OFSDelta))
244				if _, err := enc.Encode(hashes, 10); err != nil {
245					encoded <- wr.CloseWithError(err)
246					return
247				}
248				encoded <- wr.Close()
249			}()
250			finish = func() error {
251				_ = rd.Close()
252				return <-encoded
253			}
254		}
255		err = sess.Push(ctx, st, req)
256		encErr := finish()
257		if err != nil {
258			return classifyPush(err)
259		}
260		if encErr != nil {
261			return encErr
262		}
263		return refusal(refused)
264	}
265	
266	func refusal(refused []string) error {
267		if len(refused) == 0 {
268			return nil
269		}
270		return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, strings.Join(refused, "; "))
271	}
272	
273	// classifyPush maps a refused ref to ErrRejected. A report-status "ng" arrives
274	// typed whatever the server's words; the wording check covers refusals that
275	// don't.
276	func classifyPush(err error) error {
277		var refused packp.CommandStatusErr
278		if errors.As(err, &refused) {
279			return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, err)
280		}
281		msg := strings.ToLower(err.Error())
282		for _, m := range []string{"non-fast-forward", "already exists", "rejected", "failed to update", "cannot lock"} {
283			if strings.Contains(msg, m) {
284				return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, err)
285			}
286		}
287		return fmt.Errorf("stratagit: push: %w", err)
288	}
289	
290	const fetchAttempts = 3
291	
292	// Fetch starts over when an advertised ref is deleted before its want arrives,
293	// as git.Transport requires. A failed attempt leaves nothing behind (see staged).
294	func (t Transport) Fetch(repo git.Repo, remote string, refspecs ...string) error {
295		return retryVanished(func() error { return t.fetch(repo, remote, refspecs...) })
296	}
297	
298	// retryVanished runs try again, up to fetchAttempts in all, while it fails
299	// because a ref vanished between the listing and the fetch.
300	func retryVanished(try func() error) error {
301		for attempt := 1; ; attempt++ {
302			err := try()
303			if err == nil || attempt == fetchAttempts || !vanished(err) {
304				return err
305			}
306		}
307	}
308	
309	// vanished matches git's "not our ref", which entiredb sends verbatim; there is
310	// no typed form.
311	func vanished(err error) bool {
312		return strings.Contains(err.Error(), "not our ref")
313	}
314	
315	// fetch takes every advertised ref, offering the tracking refs already held as
316	// haves.
317	func (t Transport) fetch(repo git.Repo, remote string, refspecs ...string) error {
318		r, err := t.own(repo)
319		if err != nil {
320			return err
321		}
322		r.mu.RLock()
323		partial := r.partial
324		r.mu.RUnlock()
325		if partial {
326			return errors.New("stratagit: a clone fetched for one incremental read cannot be fetched into")
327		}
328		sess, err := t.session(repo, remote, transport.UploadPackService)
329		if err != nil {
330			return err
331		}
332		defer func() { _ = sess.Close() }()
333		specs := parseRefspecs(refspecs)
334		advertised, err := t.list(sess, specs.sources)
335		if err != nil {
336			return err
337		}
338		held, err := specs.held(repo)
339		if err != nil {
340			return err
341		}
342		haves := make([]plumbing.Hash, 0, len(held))
343		for _, oid := range held {
344			haves = append(haves, plumbing.NewHash(oid))
345		}
346		return t.receive(sess, repo, remote, specs, advertised, nil, haves)
347	}
348	
349	// fetchSpecs is a fetch's refspecs, with what each lists and where it lands.
350	type fetchSpecs struct {
351		specs []config.RefSpec
352		// sources become ls-refs prefixes, so a fetch lists only that store's refs.
353		sources, scopes []string
354	}
355	
356	func parseRefspecs(refspecs []string) fetchSpecs {
357		var out fetchSpecs
358		for _, raw := range refspecs {
359			spec := config.RefSpec(strings.TrimPrefix(raw, "+"))
360			out.specs = append(out.specs, spec)
361			src, dst, _ := strings.Cut(string(spec), ":")
362			out.sources = append(out.sources, strings.TrimSuffix(src, "*"))
363			if dst != "" {
364				out.scopes = append(out.scopes, strings.TrimSuffix(dst, "*"))
365			}
366		}
367		return out
368	}
369	
370	// held is the tracking refs the specs land in, as they stand.
371	func (f fetchSpecs) held(repo git.Repo) (map[string]string, error) {
372		out := map[string]string{}
373		for _, scope := range f.scopes {
374			refs, err := repo.Refs(git.Prefix(scope))
375			if err != nil {
376				return nil, err
377			}
378			maps.Copy(out, refs)
379		}
380		return out, nil
381	}
382	
383	// list asks the remote for its refs under prefixes. An empty remote is normal
384	// for a new store, and lists as nothing.
385	func (t Transport) list(sess transport.Session, prefixes []string) ([]*plumbing.Reference, error) {
386		refs, err := sess.GetRemoteRefs(t.ctx(), &transport.GetRemoteRefsOptions{RefPrefixes: prefixes})
387		switch {
388		case err == nil:
389			return refs.References, nil
390		case errors.Is(err, transport.ErrEmptyRemoteRepository):
391			return nil, nil
392		}
393		return nil, err
394	}
395	
396	// receive fetches, from what was advertised, the refs want takes (all of them
397	// when want is nil), offering haves, which the repository need not hold: a
398	// read that stops at them never asks for what lies behind them (strata
399	// ADR-0025). Every advertised ref lands as a tracking ref, fetched or not, and
400	// a tracking ref no longer advertised is pruned. With a want, the repository
401	// is left partial (Repo.partial), and the invariant staged keeps does not hold
402	// for it.
403	func (t Transport) receive(sess transport.Session, repo git.Repo, remote string, specs fetchSpecs,
404		advertised []*plumbing.Reference, want func(ref string) bool, haves []plumbing.Hash) error {
405		r, err := t.own(repo)
406		if err != nil {
407			return err
408		}
409		if want != nil {
410			r.mu.Lock()
411			r.partial = true
412			r.mu.Unlock()
413		}
414		st := r.objects()
415	
416		wanted := map[string]plumbing.Hash{}
417		missing := map[plumbing.Hash]bool{}
418		for _, spec := range specs.specs {
419			for _, r := range advertised {
420				if r.Type() != plumbing.HashReference || !spec.Match(r.Name()) {
421					continue
422				}
423				wanted[spec.Dst(r.Name()).String()] = r.Hash()
424				if want != nil && !want(r.Name().String()) {
425					continue
426				}
427				if !missing[r.Hash()] && st.HasEncodedObject(r.Hash()) != nil {
428					missing[r.Hash()] = true
429				}
430			}
431		}
432	
433		held, err := specs.held(repo)
434		if err != nil {
435			return err
436		}
437		var ops []git.RefOp
438		for name, oid := range held {
439			want, keep := wanted[name]
440			switch {
441			case !keep:
442				ops = append(ops, git.RefOp{Kind: git.RefDelete, Ref: name, Old: oid})
443			case want.String() != oid:
444				ops = append(ops, git.RefOp{Kind: git.RefUpdate, Ref: name, New: want.String(), Old: oid})
445			}
446			delete(wanted, name)
447		}
448		if len(missing) > 0 {
449			wants := make([]plumbing.Hash, 0, len(missing))
450			for h := range missing {
451				wants = append(wants, h)
452			}
453			pending, err := stage(st)
454			if err != nil {
455				return err
456			}
457			err = sess.Fetch(t.ctx(), pending, &transport.FetchRequest{Wants: wants, Haves: haves})
458			if err != nil && !errors.Is(err, transport.ErrNoChange) {
459				return fmt.Errorf("stratagit: fetching from %s: %w", remote, err)
460			}
461			err = pending.commit(&r.mu)
462			if err != nil {
463				return err
464			}
465		}
466		for name, h := range wanted {
467			ops = append(ops, git.RefOp{Kind: git.RefCreate, Ref: name, New: h.String()})
468		}
469		if len(ops) == 0 {
470			return nil
471		}
472		return repo.ApplyRefOps(ops)
473	}
474	
475	// staged holds one fetch's objects until the whole pack has arrived. go-git
476	// stores each object as it parses, so a broken pack would otherwise leave a tip
477	// held without its history, and the next fetch would skip it. Staging keeps
478	// the invariant the skip relies on: a held object has everything it reaches.
479	// A partial clone breaks it by design, which is why one is never fetched into.
480	//
481	// Objects land before refs, as in git. If ApplyRefOps then fails, the objects
482	// are complete but unreferenced, and the next fetch publishes the ref.
483	type staged struct {
484		*memory.Storage // what this fetch has written
485		base            objects
486	}
487	
488	func stage(base objects) (*staged, error) {
489		cfg, err := base.Config()
490		if err != nil {
491			return nil, err
492		}
493		pending := memory.NewStorage()
494		if err := pending.SetObjectFormat(cfg.Extensions.ObjectFormat); err != nil {
495			return nil, fmt.Errorf("stratagit: %w", err)
496		}
497		return &staged{Storage: pending, base: base}, nil
498	}
499	
500	// Reads fall through to the repository: a thin pack's deltas name bases it holds.
501	
502	func (s *staged) HasEncodedObject(h plumbing.Hash) error {
503		if s.Storage.HasEncodedObject(h) == nil {
504			return nil
505		}
506		return s.base.HasEncodedObject(h)
507	}
508	
509	func (s *staged) EncodedObjectSize(h plumbing.Hash) (int64, error) {
510		if n, err := s.Storage.EncodedObjectSize(h); err == nil {
511			return n, nil
512		}
513		return s.base.EncodedObjectSize(h)
514	}
515	
516	func (s *staged) EncodedObject(t plumbing.ObjectType, h plumbing.Hash) (plumbing.EncodedObject, error) {
517		if o, err := s.Storage.EncodedObject(t, h); err == nil {
518			return o, nil
519		}
520		return s.base.EncodedObject(t, h)
521	}
522	
523	func (s *staged) commit(mu *sync.RWMutex) error {
524		iter, err := s.IterEncodedObjects(plumbing.AnyObject)
525		if err != nil {
526			return err
527		}
528		mu.Lock()
529		defer mu.Unlock()
530		return iter.ForEach(func(o plumbing.EncodedObject) error {
531			_, err := s.base.Storage.SetEncodedObject(o)
532			return err
533		})
534	}
535	
536	// objects locks each read of the object store rather than the whole transfer,
537	// so a slow remote doesn't stall writers. That suffices because objects never
538	// change once written.
539	type objects struct {
540		*memory.Storage
541		mu *sync.RWMutex
542	}
543	
544	func (r *Repo) objects() objects { return objects{Storage: r.store, mu: &r.mu} }
545	
546	func (o objects) SetEncodedObject(obj plumbing.EncodedObject) (plumbing.Hash, error) {
547		o.mu.Lock()
548		defer o.mu.Unlock()
549		return o.Storage.SetEncodedObject(obj)
550	}
551	
552	func (o objects) EncodedObject(t plumbing.ObjectType, h plumbing.Hash) (plumbing.EncodedObject, error) {
553		o.mu.RLock()
554		defer o.mu.RUnlock()
555		return o.Storage.EncodedObject(t, h)
556	}
557	
558	func (o objects) HasEncodedObject(h plumbing.Hash) error {
559		o.mu.RLock()
560		defer o.mu.RUnlock()
561		return o.Storage.HasEncodedObject(h)
562	}
563	
564	func (o objects) EncodedObjectSize(h plumbing.Hash) (int64, error) {
565		o.mu.RLock()
566		defer o.mu.RUnlock()
567		return o.Storage.EncodedObjectSize(h)
568	}
569	
570	// IterEncodedObjects is safe to use after unlocking: memory storage returns a
571	// snapshot slice, not a view of its maps.
572	func (o objects) IterEncodedObjects(t plumbing.ObjectType) (storer.EncodedObjectIter, error) {
573		o.mu.RLock()
574		defer o.mu.RUnlock()
575		return o.Storage.IterEncodedObjects(t)
576	}
577	
578	// fastForward is false when old isn't held, as git's "fetch first".
579	func fastForward(st storage.Storer, old, new plumbing.Hash) (bool, error) {
580		newC, err := object.GetCommit(st, new)
581		if err != nil {
582			return false, err
583		}
584		oldC, err := object.GetCommit(st, old)
585		if errors.Is(err, plumbing.ErrObjectNotFound) {
586			return false, nil
587		}
588		if err != nil {
589			return false, err
590		}
591		return oldC.IsAncestor(newC)
592	}
