1	package stratagit
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"net/http"
9	
10		"github.com/entirehq/strata/git"
11		"github.com/entirehq/strata/project"
12		"github.com/entirehq/strata/reflayout"
13		"github.com/entirehq/strata/settings"
14		strata "github.com/entirehq/strata/store"
15		"github.com/go-git/go-git/v6/plumbing"
16		"github.com/go-git/go-git/v6/plumbing/transport"
17	)
18	
19	// Remote is one repository's git endpoint, reached as one caller. Strata reads
20	// and writes both go through it rather than the repo API, whose JSON pages cap a
21	// commit message at 64 KiB: a strata log entry carries its payload there.
22	type Remote struct {
23		URL string
24		// Client carries the caller's credentials (httpapi's contentHTTPClient).
25		Client *http.Client
26	}
27	
28	// Origin is the name a Remote's repository is configured under in a clone.
29	const Origin = "origin"
30	
31	// Open fetches one store into a fresh in-memory clone. The clone holds no
32	// connection or goroutine, so dropping the Store is all the cleanup it needs.
33	func (r Remote) Open(ctx context.Context, store string) (*strata.Store, error) {
34		s, _, err := r.clone(ctx, store)
35		if err != nil {
36			return nil, err
37		}
38		if err := s.Fetch(Origin); err != nil {
39			return nil, fmt.Errorf("stratagit: fetching %s: %w", store, err)
40		}
41		return s, nil
42	}
43	
44	// clone is a fresh in-memory clone of one store with origin configured, and
45	// nothing fetched.
46	func (r Remote) clone(ctx context.Context, store string) (*strata.Store, *Repo, error) {
47		d := NewDriver()
48		const dir = "/strata"
49		repo, err := d.Init(dir, git.InitOptions{})
50		if err != nil {
51			return nil, nil, err
52		}
53		s, err := strata.Open(d, r.transport(ctx), dir, store, settings.Settings{})
54		if err != nil {
55			return nil, nil, fmt.Errorf("stratagit: opening %s: %w", store, err)
56		}
57		if err := s.Configure(Origin, r.URL); err != nil {
58			return nil, nil, err
59		}
60		return s, repo.(*Repo), nil
61	}
62	
63	// Read is how FeedSince reached the store. Zero is no read.
64	type Read uint8
65	
66	const (
67		// ReadUnmoved fetched nothing: the store is where since left it.
68		ReadUnmoved Read = iota + 1
69		ReadIncremental
70		// ReadWhole is a first read, or one after a change strata reads whole: a
71		// new generation, a rotated or deleted log.
72		ReadWhole
73		// ReadWholeAfterRefusal is an incremental read strata refused, read again
74		// whole.
75		ReadWholeAfterRefusal
76	)
77	
78	func (r Read) String() string {
79		switch r {
80		case ReadUnmoved:
81			return "unmoved"
82		case ReadIncremental:
83			return "incremental"
84		case ReadWhole:
85			return "whole"
86		case ReadWholeAfterRefusal:
87			return "whole_after_refusal"
88		}
89		return ""
90	}
91	
92	// FeedSince is strata's FeedSince for a reader that keeps nothing between
93	// reads but since: it fetches into a fresh clone only what reading on needs --
94	// the new entries on the logs that grew, or everything when the store changed
95	// in a way strata reads whole -- and reads it. On ReadUnmoved nothing was
96	// fetched, and the batch and next are empty.
97	//
98	// ErrNotIncremental is answered by reading whole, which is always right. Since
99	// strata plans the fetch and the read from one listing, needing it means the
100	// read did not stand where since says: a fetch that missed an entry, or a
101	// cursor behind since's generation. Either is worth knowing.
102	func (r Remote) FeedSince(ctx context.Context, store string, c project.Cursor, since strata.Since) (project.Batch, strata.Since, Read, error) {
103		b, next, read, err := r.feedSince(ctx, store, c, since)
104		if errors.Is(err, strata.ErrNotIncremental) {
105			slog.WarnContext(ctx, "stratagit: could not read on; reading whole",
106				slog.String("store", store), slog.Any("error", err))
107			b, next, read, err = r.feedSince(ctx, store, c, strata.Since{})
108			if read == ReadWhole {
109				read = ReadWholeAfterRefusal
110			}
111		}
112		return b, next, read, err
113	}
114	
115	func (r Remote) feedSince(ctx context.Context, store string, c project.Cursor, since strata.Since) (project.Batch, strata.Since, Read, error) {
116		var s *strata.Store
117		var read Read
118		err := retryVanished(func() (err error) {
119			s, _, read, err = r.fetchSince(ctx, store, since)
120			return err
121		})
122		if err != nil || read == ReadUnmoved {
123			return project.Batch{}, strata.Since{}, read, err
124		}
125		b, next, err := s.FeedSince(c, since)
126		return b, next, read, err
127	}
128	
129	// fetchSince lists the store and fetches what strata.FetchFor plans from that
130	// listing, over one session. It also returns the clone, for a test to count
131	// what came.
132	func (r Remote) fetchSince(ctx context.Context, store string, since strata.Since) (*strata.Store, *Repo, Read, error) {
133		s, repo, err := r.clone(ctx, store)
134		if err != nil {
135			return nil, nil, 0, err
136		}
137		tp := r.transport(ctx)
138		sess, err := tp.session(repo, Origin, transport.UploadPackService)
139		if err != nil {
140			return nil, nil, 0, err
141		}
142		defer func() { _ = sess.Close() }()
143		specs := parseRefspecs([]string{reflayout.For(store).FetchRefspec(Origin)})
144		advertised, err := tp.list(sess, specs.sources)
145		if err != nil {
146			return nil, nil, 0, fmt.Errorf("stratagit: listing %s: %w", store, err)
147		}
148		listed := make(map[string]string, len(advertised))
149		for _, ref := range advertised {
150			listed[ref.Name().String()] = ref.Hash().String()
151		}
152		plan := strata.FetchFor(store, since, listed)
153		if plan.Incremental && len(plan.Wants) == 0 {
154			return nil, nil, ReadUnmoved, nil
155		}
156		read := ReadWhole
157		if plan.Incremental {
158			read = ReadIncremental
159		}
160		// Haves this clone does not hold, on purpose: the remote leaves out what
161		// they reach, and strata's read stops at them (ADR-0025). Nothing in the
162		// pack can lean on them, since go-git never asks for a thin pack, and a
163		// read that finds an entry missing is ErrNotIncremental, read again whole.
164		haves := make([]plumbing.Hash, len(plan.Haves))
165		for i, oid := range plan.Haves {
166			haves[i] = plumbing.NewHash(oid)
167		}
168		wanted := func(ref string) bool { _, ok := plan.Wants[ref]; return ok }
169		if err := tp.receive(sess, repo, Origin, specs, advertised, wanted, haves); err != nil {
170			return nil, nil, 0, fmt.Errorf("stratagit: fetching %s: %w", store, err)
171		}
172		return s, repo, read, nil
173	}
174	
175	// Refs lists the refs under prefix without fetching any objects.
176	func (r Remote) Refs(ctx context.Context, prefix string) (map[string]string, error) {
177		repo, err := NewDriver().Init("/ls", git.InitOptions{})
178		if err != nil {
179			return nil, err
180		}
181		if err := repo.ConfigSet(remoteKey(Origin, "url"), r.URL); err != nil {
182			return nil, err
183		}
184		return r.transport(ctx).LsRemote(repo, Origin, prefix)
185	}
186	
187	func (r Remote) transport(ctx context.Context) Transport {
188		return Transport{Client: r.Client, Context: ctx}
189	}
