1	// Package stratagit backs a strata store with an in-memory git repository and
2	// reaches entiredb over the smart protocol through go-git.
3	//
4	// It ports strata's internal/gitmem (the driver) and examples/gogit (the
5	// transport), which strata keeps out of its dependency-free library; strata's
6	// conformance suites check both. Nothing touches disk, and GitDir names a
7	// directory that is never created.
8	package stratagit
9	
10	import (
11		"bytes"
12		"errors"
13		"fmt"
14		"io"
15		"sort"
16		"strings"
17		"sync"
18		"time"
19	
20		"github.com/entirehq/strata/git"
21		"github.com/go-git/go-git/v6/plumbing"
22		"github.com/go-git/go-git/v6/plumbing/filemode"
23		"github.com/go-git/go-git/v6/plumbing/format/config"
24		"github.com/go-git/go-git/v6/plumbing/object"
25		"github.com/go-git/go-git/v6/storage/memory"
26	)
27	
28	// Driver holds in-memory repositories by directory, so two Opens of one
29	// directory are two handles on one repository, as they are on disk.
30	type Driver struct {
31		mu    sync.Mutex
32		repos map[string]*Repo
33	}
34	
35	func NewDriver() *Driver { return &Driver{repos: map[string]*Repo{}} }
36	
37	// Open fails with ErrNotFound for a directory nothing has Init'ed, which is
38	// what Store.Open relies on to fall back to Init.
39	func (d *Driver) Open(dir string) (git.Repo, error) {
40		d.mu.Lock()
41		defer d.mu.Unlock()
42		r, ok := d.repos[dir]
43		if !ok {
44			return nil, fmt.Errorf("stratagit: %s: %w", dir, git.ErrNotFound)
45		}
46		return r, nil
47	}
48	
49	// Init ignores Bare and RefFormat, which nothing here can observe.
50	func (d *Driver) Init(dir string, opts git.InitOptions) (git.Repo, error) {
51		d.mu.Lock()
52		defer d.mu.Unlock()
53		if r, ok := d.repos[dir]; ok {
54			return r, nil
55		}
56		store := memory.NewStorage()
57		switch opts.ObjectFormat {
58		case "", "sha1":
59			if err := store.SetObjectFormat(config.SHA1); err != nil {
60				return nil, fmt.Errorf("stratagit: %w", err)
61			}
62		case "sha256":
63			if err := store.SetObjectFormat(config.SHA256); err != nil {
64				return nil, fmt.Errorf("stratagit: %w", err)
65			}
66		default:
67			return nil, fmt.Errorf("stratagit: object format %q is neither sha1 nor sha256",
68				opts.ObjectFormat)
69		}
70		r := &Repo{
71			dir:    dir,
72			store:  store,
73			refs:   map[string]string{},
74			config: map[string]string{},
75			locks:  map[string]*sync.Mutex{},
76			local:  map[string][]byte{},
77		}
78		d.repos[dir] = r
79		return r, nil
80	}
81	
82	// Repo is one in-memory repository. go-git's memory storage has no locking of
83	// its own, so mu covers every operation, and another handle sees each one whole
84	// or not at all, as git's locks give on disk.
85	type Repo struct {
86		mu    sync.RWMutex
87		dir   string
88		store *memory.Storage
89	
90		refs      map[string]string
91		config    map[string]string
92		crashSafe bool
93		// partial is a clone fetched for one incremental read (receive with a
94		// want): it holds the newest entries without what they reach, and tracking
95		// refs to objects it never fetched. Read once and dropped, never fetched
96		// into again, since a fetch would offer those as haves.
97		partial bool
98	
99		// git.LocalState. A lock is held across calls, so each is its own mutex and
100		// mu guards only the map.
101		locks map[string]*sync.Mutex
102		local map[string][]byte
103	}
104	
105	// put writes an object. The caller holds mu.
106	func (r *Repo) put(
107		typ plumbing.ObjectType, write func(o plumbing.EncodedObject) error,
108	) (string, error) {
109		o := r.store.NewEncodedObject()
110		o.SetType(typ)
111		if err := write(o); err != nil {
112			return "", err
113		}
114		h, err := r.store.SetEncodedObject(o)
115		if err != nil {
116			return "", fmt.Errorf("stratagit: %w", err)
117		}
118		return h.String(), nil
119	}
120	
121	func (r *Repo) HashBlobs(payloads [][]byte) ([]string, error) {
122		r.mu.Lock()
123		defer r.mu.Unlock()
124		out := make([]string, len(payloads))
125		for i, p := range payloads {
126			oid, err := r.blob(p)
127			if err != nil {
128				return nil, err
129			}
130			out[i] = oid
131		}
132		return out, nil
133	}
134	
135	func (r *Repo) blob(payload []byte) (string, error) {
136		return r.put(plumbing.BlobObject, func(o plumbing.EncodedObject) error {
137			w, err := o.Writer()
138			if err != nil {
139				return err
140			}
141			if _, err := w.Write(payload); err != nil {
142				return err
143			}
144			return w.Close()
145		})
146	}
147	
148	func (r *Repo) CatBlobs(oids []string) ([][]byte, error) { return r.cat(oids, false) }
149	
150	func (r *Repo) CatOptional(names []string) ([][]byte, error) { return r.cat(names, true) }
151	
152	// cat treats only ErrNotFound as absence. Any other failure is returned, since a
153	// nil for it would read as a record that was never written.
154	func (r *Repo) cat(names []string, optional bool) ([][]byte, error) {
155		r.mu.RLock()
156		defer r.mu.RUnlock()
157		out := make([][]byte, len(names))
158		for i, name := range names {
159			b, err := r.read(name)
160			switch {
161			case err == nil:
162				out[i] = b
163			case optional && errors.Is(err, git.ErrNotFound):
164			default:
165				return nil, err
166			}
167		}
168		return out, nil
169	}
170	
171	// read returns a blob's bytes. The caller holds mu.
172	func (r *Repo) read(name string) ([]byte, error) {
173		h, err := r.resolve(name)
174		if err != nil {
175			return nil, err
176		}
177		o, err := r.store.EncodedObject(plumbing.AnyObject, h)
178		if err != nil {
179			return nil, fmt.Errorf("stratagit: %s: %w", name, git.ErrNotFound)
180		}
181		if o.Type() != plumbing.BlobObject {
182			return nil, fmt.Errorf("stratagit: %s is a %s, not a blob", name, o.Type())
183		}
184		rd, err := o.Reader()
185		if err != nil {
186			return nil, err
187		}
188		defer func() { _ = rd.Close() }()
189		// To the end, not the size the header claims, so a truncated payload fails
190		// instead of reading as a short value.
191		return io.ReadAll(rd)
192	}
193	
194	func (r *Repo) WriteTree(entries []git.TreeEntry) (string, error) {
195		if len(entries) == 0 {
196			return "", errors.New("stratagit: refusing to write an empty tree")
197		}
198		r.mu.Lock()
199		defer r.mu.Unlock()
200		return r.writeTree(entries)
201	}
202	
203	// node is a directory being assembled.
204	type node struct {
205		files map[string]git.TreeEntry
206		dirs  map[string]*node
207	}
208	
209	func newNode() *node {
210		return &node{files: map[string]git.TreeEntry{}, dirs: map[string]*node{}}
211	}
212	
213	func (n *node) add(e git.TreeEntry) {
214		parts := strings.Split(e.Path, "/")
215		cur := n
216		for _, p := range parts[:len(parts)-1] {
217			next, ok := cur.dirs[p]
218			if !ok {
219				next = newNode()
220				cur.dirs[p] = next
221			}
222			cur = next
223		}
224		cur.files[parts[len(parts)-1]] = e
225	}
226	
227	func (r *Repo) writeTree(entries []git.TreeEntry) (string, error) {
228		root := newNode()
229		for _, e := range entries {
230			root.add(e)
231		}
232		return r.encodeNode(root)
233	}
234	
235	// encodeNode writes a directory and its children, deepest first. go-git refuses
236	// entries out of git's order, which TreeEntrySorter gives.
237	func (r *Repo) encodeNode(n *node) (string, error) {
238		var entries []object.TreeEntry
239		for name, e := range n.files {
240			mode := filemode.Regular
241			if e.Mode != "" {
242				m, err := filemode.New(e.Mode)
243				if err != nil {
244					return "", fmt.Errorf("stratagit: file mode %q: %w", e.Mode, err)
245				}
246				mode = m
247			}
248			entries = append(entries, object.TreeEntry{
249				Name: name, Mode: mode, Hash: plumbing.NewHash(e.OID),
250			})
251		}
252		for name, child := range n.dirs {
253			oid, err := r.encodeNode(child)
254			if err != nil {
255				return "", err
256			}
257			entries = append(entries, object.TreeEntry{
258				Name: name, Mode: filemode.Dir, Hash: plumbing.NewHash(oid),
259			})
260		}
261		sort.Sort(object.TreeEntrySorter(entries))
262		return r.put(plumbing.TreeObject, func(o plumbing.EncodedObject) error {
263			return (&object.Tree{Entries: entries}).Encode(o)
264		})
265	}
266	
267	// CommitTree fixes identity and date, so every clone commits the same tree to
268	// the same id; conformance pins the ids.
269	func (r *Repo) CommitTree(tree string, parents []string, message string) (string, error) {
270		r.mu.Lock()
271		defer r.mu.Unlock()
272		return r.commit(tree, parents, message, git.DerivedWhen())
273	}
274	
275	func (r *Repo) CommitTimestamped(
276		tree string, parents []string, message string,
277	) (string, error) {
278		r.mu.Lock()
279		defer r.mu.Unlock()
280		return r.commit(tree, parents, message, time.Now())
281	}
282	
283	func (r *Repo) commit(
284		tree string, parents []string, message string, when time.Time,
285	) (string, error) {
286		sig := object.Signature{Name: git.DerivedName, Email: git.DerivedEmail, When: when}
287		c := &object.Commit{
288			Author: sig, Committer: sig,
289			Message:  message,
290			TreeHash: plumbing.NewHash(tree),
291		}
292		for _, p := range parents {
293			c.ParentHashes = append(c.ParentHashes, plumbing.NewHash(p))
294		}
295		return r.put(plumbing.CommitObject, func(o plumbing.EncodedObject) error {
296			return c.Encode(o)
297		})
298	}
299	
300	func (r *Repo) EmptyTree() (string, error) {
301		r.mu.Lock()
302		defer r.mu.Unlock()
303		return r.encodeNode(newNode())
304	}
305	
306	// ParentlessCommit is assembled from the same primitives as CommitTree, which
307	// strata's ADR-0020 allows; there is no pack to stream into here.
308	func (r *Repo) ParentlessCommit(message string, files []git.ImportFile) (string, error) {
309		r.mu.Lock()
310		defer r.mu.Unlock()
311		entries := make([]git.TreeEntry, 0, len(files))
312		for _, f := range files {
313			oid, err := r.blob(f.Bytes)
314			if err != nil {
315				return "", err
316			}
317			entries = append(entries, git.TreeEntry{Mode: f.Mode, OID: oid, Path: f.Path})
318		}
319		tree, err := r.writeTree(entries)
320		if err != nil {
321			return "", err
322		}
323		return r.commit(tree, nil, message, git.DerivedWhen())
324	}
325	
326	var _ git.LocalState = (*Repo)(nil)
327	
328	func (r *Repo) GitDir() (string, error) { return r.dir, nil }
329	
330	func (r *Repo) Lock(name string) (func(), error) {
331		r.mu.Lock()
332		l, ok := r.locks[name]
333		if !ok {
334			l = &sync.Mutex{}
335			r.locks[name] = l
336		}
337		r.mu.Unlock()
338		l.Lock()
339		return l.Unlock, nil
340	}
341	
342	func (r *Repo) ReadLocal(name string) ([]byte, error) {
343		r.mu.RLock()
344		defer r.mu.RUnlock()
345		// Capped rather than copied, so an append by the caller reallocates instead
346		// of writing into ours.
347		v := r.local[name]
348		return v[:len(v):len(v)], nil
349	}
350	
351	func (r *Repo) WriteLocal(name string, data []byte) error {
352		r.mu.Lock()
353		defer r.mu.Unlock()
354		if len(data) == 0 {
355			delete(r.local, name)
356			return nil
357		}
358		r.local[name] = bytes.Clone(data)
359		return nil
360	}
361	
362	// MakeCrashSafe holds vacuously: nothing here outlives the process, so no caller
363	// can see an object lost to a crash.
364	func (r *Repo) MakeCrashSafe() error {
365		r.mu.Lock()
366		defer r.mu.Unlock()
367		r.crashSafe = true
368		return nil
369	}
370	
371	func (r *Repo) CrashSafe() (bool, error) {
372		r.mu.RLock()
373		defer r.mu.RUnlock()
374		return r.crashSafe, nil
375	}
376	
377	func (r *Repo) ConfigGet(key string) (string, error) {
378		r.mu.RLock()
379		defer r.mu.RUnlock()
380		return r.config[key], nil
381	}
382	
383	func (r *Repo) ConfigSet(key, value string) error {
384		r.mu.Lock()
385		defer r.mu.Unlock()
386		r.config[key] = value
387		return nil
388	}
389	
390	func (r *Repo) AddRemote(name, url string) error {
391		return r.ConfigSet(remoteKey(name, "url"), url)
392	}
393	
394	// AddFetchRefspec only records the refspec; fetches name theirs explicitly.
395	func (r *Repo) AddFetchRefspec(remote, refspec string) error {
396		r.mu.Lock()
397		defer r.mu.Unlock()
398		key := remoteKey(remote, "fetch")
399		for line := range strings.SplitSeq(r.config[key], "\n") {
400			if line == refspec {
401				return nil
402			}
403		}
404		if have := r.config[key]; have != "" {
405			refspec = have + "\n" + refspec
406		}
407		r.config[key] = refspec
408		return nil
409	}
410	
411	func (r *Repo) FetchRefspecs(remote string) ([]string, error) {
412		r.mu.RLock()
413		defer r.mu.RUnlock()
414		have := r.config[remoteKey(remote, "fetch")]
415		if have == "" {
416			return nil, nil
417		}
418		return strings.Split(have, "\n"), nil
419	}
420	
421	func (r *Repo) Remotes() ([]string, error) {
422		r.mu.RLock()
423		defer r.mu.RUnlock()
424		var out []string
425		for key := range r.config {
426			if name, ok := remoteName(key, "url"); ok {
427				out = append(out, name)
428			}
429		}
430		sort.Strings(out)
431		return out, nil
432	}
433	
434	func remoteKey(name, field string) string { return "remote." + name + "." + field }
435	
436	func remoteName(key, field string) (string, bool) {
437		rest, ok := strings.CutPrefix(key, "remote.")
438		if !ok {
439			return "", false
440		}
441		name, ok := strings.CutSuffix(rest, "."+field)
442		return name, ok
443	}
