// Package stratagit backs a strata store with an in-memory git repository and
// reaches entiredb over the smart protocol through go-git.
//
// It ports strata's internal/gitmem (the driver) and examples/gogit (the
// transport), which strata keeps out of its dependency-free library; strata's
// conformance suites check both. Nothing touches disk, and GitDir names a
// directory that is never created.
package stratagit

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/entirehq/strata/git"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

// Driver holds in-memory repositories by directory, so two Opens of one
// directory are two handles on one repository, as they are on disk.
type Driver struct {
	mu    sync.Mutex
	repos map[string]*Repo
}

func NewDriver() *Driver { return &Driver{repos: map[string]*Repo{}} }

// Open fails with ErrNotFound for a directory nothing has Init'ed, which is
// what Store.Open relies on to fall back to Init.
func (d *Driver) Open(dir string) (git.Repo, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	r, ok := d.repos[dir]
	if !ok {
		return nil, fmt.Errorf("stratagit: %s: %w", dir, git.ErrNotFound)
	}
	return r, nil
}

// Init ignores Bare and RefFormat, which nothing here can observe.
func (d *Driver) Init(dir string, opts git.InitOptions) (git.Repo, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if r, ok := d.repos[dir]; ok {
		return r, nil
	}
	store := memory.NewStorage()
	switch opts.ObjectFormat {
	case "", "sha1":
		if err := store.SetObjectFormat(config.SHA1); err != nil {
			return nil, fmt.Errorf("stratagit: %w", err)
		}
	case "sha256":
		if err := store.SetObjectFormat(config.SHA256); err != nil {
			return nil, fmt.Errorf("stratagit: %w", err)
		}
	default:
		return nil, fmt.Errorf("stratagit: object format %q is neither sha1 nor sha256",
			opts.ObjectFormat)
	}
	r := &Repo{
		dir:    dir,
		store:  store,
		refs:   map[string]string{},
		config: map[string]string{},
		locks:  map[string]*sync.Mutex{},
		local:  map[string][]byte{},
	}
	d.repos[dir] = r
	return r, nil
}

// Repo is one in-memory repository. go-git's memory storage has no locking of
// its own, so mu covers every operation, and another handle sees each one whole
// or not at all, as git's locks give on disk.
type Repo struct {
	mu    sync.RWMutex
	dir   string
	store *memory.Storage

	refs      map[string]string
	config    map[string]string
	crashSafe bool
	// partial is a clone fetched for one incremental read (receive with a
	// want): it holds the newest entries without what they reach, and tracking
	// refs to objects it never fetched. Read once and dropped, never fetched
	// into again, since a fetch would offer those as haves.
	partial bool

	// git.LocalState. A lock is held across calls, so each is its own mutex and
	// mu guards only the map.
	locks map[string]*sync.Mutex
	local map[string][]byte
}

// put writes an object. The caller holds mu.
func (r *Repo) put(
	typ plumbing.ObjectType, write func(o plumbing.EncodedObject) error,
) (string, error) {
	o := r.store.NewEncodedObject()
	o.SetType(typ)
	if err := write(o); err != nil {
		return "", err
	}
	h, err := r.store.SetEncodedObject(o)
	if err != nil {
		return "", fmt.Errorf("stratagit: %w", err)
	}
	return h.String(), nil
}

func (r *Repo) HashBlobs(payloads [][]byte) ([]string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]string, len(payloads))
	for i, p := range payloads {
		oid, err := r.blob(p)
		if err != nil {
			return nil, err
		}
		out[i] = oid
	}
	return out, nil
}

func (r *Repo) blob(payload []byte) (string, error) {
	return r.put(plumbing.BlobObject, func(o plumbing.EncodedObject) error {
		w, err := o.Writer()
		if err != nil {
			return err
		}
		if _, err := w.Write(payload); err != nil {
			return err
		}
		return w.Close()
	})
}

func (r *Repo) CatBlobs(oids []string) ([][]byte, error) { return r.cat(oids, false) }

func (r *Repo) CatOptional(names []string) ([][]byte, error) { return r.cat(names, true) }

// cat treats only ErrNotFound as absence. Any other failure is returned, since a
// nil for it would read as a record that was never written.
func (r *Repo) cat(names []string, optional bool) ([][]byte, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([][]byte, len(names))
	for i, name := range names {
		b, err := r.read(name)
		switch {
		case err == nil:
			out[i] = b
		case optional && errors.Is(err, git.ErrNotFound):
		default:
			return nil, err
		}
	}
	return out, nil
}

// read returns a blob's bytes. The caller holds mu.
func (r *Repo) read(name string) ([]byte, error) {
	h, err := r.resolve(name)
	if err != nil {
		return nil, err
	}
	o, err := r.store.EncodedObject(plumbing.AnyObject, h)
	if err != nil {
		return nil, fmt.Errorf("stratagit: %s: %w", name, git.ErrNotFound)
	}
	if o.Type() != plumbing.BlobObject {
		return nil, fmt.Errorf("stratagit: %s is a %s, not a blob", name, o.Type())
	}
	rd, err := o.Reader()
	if err != nil {
		return nil, err
	}
	defer func() { _ = rd.Close() }()
	// To the end, not the size the header claims, so a truncated payload fails
	// instead of reading as a short value.
	return io.ReadAll(rd)
}

func (r *Repo) WriteTree(entries []git.TreeEntry) (string, error) {
	if len(entries) == 0 {
		return "", errors.New("stratagit: refusing to write an empty tree")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.writeTree(entries)
}

// node is a directory being assembled.
type node struct {
	files map[string]git.TreeEntry
	dirs  map[string]*node
}

func newNode() *node {
	return &node{files: map[string]git.TreeEntry{}, dirs: map[string]*node{}}
}

func (n *node) add(e git.TreeEntry) {
	parts := strings.Split(e.Path, "/")
	cur := n
	for _, p := range parts[:len(parts)-1] {
		next, ok := cur.dirs[p]
		if !ok {
			next = newNode()
			cur.dirs[p] = next
		}
		cur = next
	}
	cur.files[parts[len(parts)-1]] = e
}

func (r *Repo) writeTree(entries []git.TreeEntry) (string, error) {
	root := newNode()
	for _, e := range entries {
		root.add(e)
	}
	return r.encodeNode(root)
}

// encodeNode writes a directory and its children, deepest first. go-git refuses
// entries out of git's order, which TreeEntrySorter gives.
func (r *Repo) encodeNode(n *node) (string, error) {
	var entries []object.TreeEntry
	for name, e := range n.files {
		mode := filemode.Regular
		if e.Mode != "" {
			m, err := filemode.New(e.Mode)
			if err != nil {
				return "", fmt.Errorf("stratagit: file mode %q: %w", e.Mode, err)
			}
			mode = m
		}
		entries = append(entries, object.TreeEntry{
			Name: name, Mode: mode, Hash: plumbing.NewHash(e.OID),
		})
	}
	for name, child := range n.dirs {
		oid, err := r.encodeNode(child)
		if err != nil {
			return "", err
		}
		entries = append(entries, object.TreeEntry{
			Name: name, Mode: filemode.Dir, Hash: plumbing.NewHash(oid),
		})
	}
	sort.Sort(object.TreeEntrySorter(entries))
	return r.put(plumbing.TreeObject, func(o plumbing.EncodedObject) error {
		return (&object.Tree{Entries: entries}).Encode(o)
	})
}

// CommitTree fixes identity and date, so every clone commits the same tree to
// the same id; conformance pins the ids.
func (r *Repo) CommitTree(tree string, parents []string, message string) (string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.commit(tree, parents, message, git.DerivedWhen())
}

func (r *Repo) CommitTimestamped(
	tree string, parents []string, message string,
) (string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.commit(tree, parents, message, time.Now())
}

func (r *Repo) commit(
	tree string, parents []string, message string, when time.Time,
) (string, error) {
	sig := object.Signature{Name: git.DerivedName, Email: git.DerivedEmail, When: when}
	c := &object.Commit{
		Author: sig, Committer: sig,
		Message:  message,
		TreeHash: plumbing.NewHash(tree),
	}
	for _, p := range parents {
		c.ParentHashes = append(c.ParentHashes, plumbing.NewHash(p))
	}
	return r.put(plumbing.CommitObject, func(o plumbing.EncodedObject) error {
		return c.Encode(o)
	})
}

func (r *Repo) EmptyTree() (string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.encodeNode(newNode())
}

// ParentlessCommit is assembled from the same primitives as CommitTree, which
// strata's ADR-0020 allows; there is no pack to stream into here.
func (r *Repo) ParentlessCommit(message string, files []git.ImportFile) (string, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	entries := make([]git.TreeEntry, 0, len(files))
	for _, f := range files {
		oid, err := r.blob(f.Bytes)
		if err != nil {
			return "", err
		}
		entries = append(entries, git.TreeEntry{Mode: f.Mode, OID: oid, Path: f.Path})
	}
	tree, err := r.writeTree(entries)
	if err != nil {
		return "", err
	}
	return r.commit(tree, nil, message, git.DerivedWhen())
}

var _ git.LocalState = (*Repo)(nil)

func (r *Repo) GitDir() (string, error) { return r.dir, nil }

func (r *Repo) Lock(name string) (func(), error) {
	r.mu.Lock()
	l, ok := r.locks[name]
	if !ok {
		l = &sync.Mutex{}
		r.locks[name] = l
	}
	r.mu.Unlock()
	l.Lock()
	return l.Unlock, nil
}

func (r *Repo) ReadLocal(name string) ([]byte, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	// Capped rather than copied, so an append by the caller reallocates instead
	// of writing into ours.
	v := r.local[name]
	return v[:len(v):len(v)], nil
}

func (r *Repo) WriteLocal(name string, data []byte) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if len(data) == 0 {
		delete(r.local, name)
		return nil
	}
	r.local[name] = bytes.Clone(data)
	return nil
}

// MakeCrashSafe holds vacuously: nothing here outlives the process, so no caller
// can see an object lost to a crash.
func (r *Repo) MakeCrashSafe() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.crashSafe = true
	return nil
}

func (r *Repo) CrashSafe() (bool, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.crashSafe, nil
}

func (r *Repo) ConfigGet(key string) (string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.config[key], nil
}

func (r *Repo) ConfigSet(key, value string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.config[key] = value
	return nil
}

func (r *Repo) AddRemote(name, url string) error {
	return r.ConfigSet(remoteKey(name, "url"), url)
}

// AddFetchRefspec only records the refspec; fetches name theirs explicitly.
func (r *Repo) AddFetchRefspec(remote, refspec string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	key := remoteKey(remote, "fetch")
	for line := range strings.SplitSeq(r.config[key], "\n") {
		if line == refspec {
			return nil
		}
	}
	if have := r.config[key]; have != "" {
		refspec = have + "\n" + refspec
	}
	r.config[key] = refspec
	return nil
}

func (r *Repo) FetchRefspecs(remote string) ([]string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	have := r.config[remoteKey(remote, "fetch")]
	if have == "" {
		return nil, nil
	}
	return strings.Split(have, "\n"), nil
}

func (r *Repo) Remotes() ([]string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	var out []string
	for key := range r.config {
		if name, ok := remoteName(key, "url"); ok {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out, nil
}

func remoteKey(name, field string) string { return "remote." + name + "." + field }

func remoteName(key, field string) (string, bool) {
	rest, ok := strings.CutPrefix(key, "remote.")
	if !ok {
		return "", false
	}
	name, ok := strings.CutSuffix(rest, "."+field)
	return name, ok
}

