package stratagit

import (
	"fmt"
	"strings"

	"github.com/entirehq/strata/git"
	"github.com/go-git/go-git/v6/plumbing"
)

// Refs are a map under Repo.mu rather than go-git's reference store, which
// strata's ADR-0001 rejected for lacking create-if-absent and atomic multi-ref
// updates.

func (r *Repo) Ref(ref string) (string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.refs[ref], nil
}

func (r *Repo) Refs(prefix string) (map[string]string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	p := git.Prefix(prefix)
	out := map[string]string{}
	for name, oid := range r.refs {
		if under(p, name) {
			out[name] = oid
		}
	}
	return out, nil
}

// under matches at a path component, so "refs/a" holds "refs/a/b" but not
// "refs/ab". Refs and LsRemote share it so they agree.
func under(prefix, ref string) bool {
	return prefix == "" || ref == prefix || strings.HasPrefix(ref, prefix+"/")
}

func (r *Repo) SetRef(ref, newOID, oldOID string) error {
	return r.ApplyRefOps([]git.RefOp{{
		Kind: kindFor(newOID, oldOID), Ref: ref, New: newOID, Old: oldOID,
	}})
}

func kindFor(newOID, oldOID string) git.RefKind {
	switch {
	case newOID == "":
		return git.RefDelete
	case oldOID == "":
		return git.RefCreate
	default:
		return git.RefUpdate
	}
}

// ApplyRefOps checks every op against the refs as they were on entry, then
// writes them all, so a batch lands whole or not at all. The write pass must not
// re-check: it could then fail with the batch half applied.
func (r *Repo) ApplyRefOps(ops []git.RefOp) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	for _, op := range ops {
		if err := r.check(op); err != nil {
			return err
		}
	}
	for _, op := range ops {
		if op.Kind == git.RefDelete {
			delete(r.refs, op.Ref)
			continue
		}
		r.refs[op.Ref] = op.New
	}
	return nil
}

// check: the caller holds mu.
func (r *Repo) check(op git.RefOp) error {
	have, exists := r.refs[op.Ref]
	switch op.Kind {
	case git.RefCreate:
		if exists {
			return fmt.Errorf("stratagit: %s exists: %w", op.Ref, git.ErrRefChanged)
		}
	case git.RefUpdate:
		if !exists {
			return fmt.Errorf("stratagit: %s does not exist: %w", op.Ref, git.ErrRefChanged)
		}
		if have != op.Old {
			return fmt.Errorf("stratagit: %s holds %q, not %q: %w",
				op.Ref, have, op.Old, git.ErrRefChanged)
		}
	case git.RefDelete:
		// An empty Old deletes whatever is there, as update-ref does.
		if op.Old != "" && !exists {
			return fmt.Errorf("stratagit: %s does not exist: %w", op.Ref, git.ErrRefChanged)
		}
		if op.Old != "" && have != op.Old {
			return fmt.Errorf("stratagit: %s holds %q, not %q: %w",
				op.Ref, have, op.Old, git.ErrRefChanged)
		}
	default:
		return fmt.Errorf("stratagit: %s has no ref operation kind", op.Ref)
	}
	return nil
}

func (r *Repo) CheckRefFormat(ref string) error {
	if err := plumbing.ReferenceName(ref).Validate(); err != nil {
		return fmt.Errorf("stratagit: %q: %w", ref, git.ErrBadRefName)
	}
	return nil
}

