package stratagit

import (
	"fmt"
	"path"
	"sort"
	"strings"

	"github.com/entirehq/strata/git"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/utils/merkletrie"
)

// resolve understands the two expressions strata writes, an id and
// <committish>:<path>, and refuses the rest. The caller holds mu.
func (r *Repo) resolve(name string) (plumbing.Hash, error) {
	base, rest, hasPath := strings.Cut(name, ":")
	h := plumbing.NewHash(base)
	if h.IsZero() && base != "" {
		return plumbing.ZeroHash,
			fmt.Errorf("stratagit: %q is not an object id: %w", base, git.ErrNotFound)
	}
	if !hasPath {
		return h, nil
	}
	tree, err := r.treeOf(h)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	return r.walk(tree, rest)
}

func (r *Repo) treeOf(h plumbing.Hash) (*object.Tree, error) {
	o, err := r.store.EncodedObject(plumbing.AnyObject, h)
	if err != nil {
		return nil, fmt.Errorf("stratagit: %s: %w", h, git.ErrNotFound)
	}
	switch o.Type() {
	case plumbing.CommitObject:
		c := &object.Commit{}
		if err := c.Decode(o); err != nil {
			return nil, err
		}
		return r.tree(c.TreeHash)
	case plumbing.TreeObject:
		return r.tree(h)
	}
	return nil, fmt.Errorf("stratagit: %s is a %s, not a commit or tree", h, o.Type())
}

// tree uses GetTree rather than Decode so the tree keeps its storer, which
// go-git's diff needs to descend into subtrees.
func (r *Repo) tree(h plumbing.Hash) (*object.Tree, error) {
	t, err := object.GetTree(r.store, h)
	if err != nil {
		return nil, fmt.Errorf("stratagit: tree %s: %w", h, git.ErrNotFound)
	}
	return t, nil
}

func (r *Repo) walk(t *object.Tree, p string) (plumbing.Hash, error) {
	if p == "" {
		return plumbing.ZeroHash, fmt.Errorf("stratagit: empty path: %w", git.ErrNotFound)
	}
	parts := strings.Split(p, "/")
	cur := t
	for i, part := range parts {
		var found *object.TreeEntry
		for j := range cur.Entries {
			if cur.Entries[j].Name == part {
				found = &cur.Entries[j]
				break
			}
		}
		if found == nil {
			return plumbing.ZeroHash, fmt.Errorf("stratagit: %q: %w", p, git.ErrNotFound)
		}
		if i == len(parts)-1 {
			return found.Hash, nil
		}
		next, err := r.tree(found.Hash)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		cur = next
	}
	return plumbing.ZeroHash, fmt.Errorf("stratagit: %q: %w", p, git.ErrNotFound)
}

func (r *Repo) LsTreeRecursive(treeish string) ([]git.TreeEntry, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	h, err := r.resolve(treeish)
	if err != nil {
		return nil, err
	}
	t, err := r.treeOf(h)
	if err != nil {
		return nil, err
	}
	var out []git.TreeEntry
	if err := r.collect(t, "", &out); err != nil {
		return nil, err
	}
	// Already sorted by path: git's tree order expands to it. strata's ordered
	// reads rely on that order.
	return out, nil
}

func (r *Repo) collect(t *object.Tree, prefix string, out *[]git.TreeEntry) error {
	for _, e := range t.Entries {
		p := path.Join(prefix, e.Name)
		if e.Mode == filemode.Dir {
			sub, err := r.tree(e.Hash)
			if err != nil {
				return err
			}
			if err := r.collect(sub, p, out); err != nil {
				return err
			}
			continue
		}
		*out = append(*out, git.TreeEntry{Mode: e.Mode.String(), OID: e.Hash.String(), Path: p})
	}
	return nil
}

// Log walks first parents: strata's logs are single-parent chains, and their
// commits share one fixed date, so walk order is the only order.
func (r *Repo) Log(tip string) ([]git.Commit, error) {
	if tip == "" {
		return nil, nil
	}
	start := plumbing.NewHash(tip)
	if start.IsZero() {
		return nil, fmt.Errorf("stratagit: %q is not an object id: %w", tip, git.ErrNotFound)
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	var out []git.Commit
	seen := map[plumbing.Hash]bool{}
	for h := start; ; {
		if seen[h] {
			break
		}
		seen[h] = true
		c, err := r.commitAt(h)
		if err != nil {
			return nil, err
		}
		out = append(out, git.Commit{OID: h.String(), Message: c.Message, When: c.Committer.When, Parents: parents(c)})
		if len(c.ParentHashes) == 0 {
			break
		}
		h = c.ParentHashes[0]
	}
	return out, nil
}

func parents(c *object.Commit) []string {
	if len(c.ParentHashes) == 0 {
		return nil
	}
	out := make([]string, len(c.ParentHashes))
	for i, h := range c.ParentHashes {
		out[i] = h.String()
	}
	return out
}

func (r *Repo) commitAt(h plumbing.Hash) (*object.Commit, error) {
	o, err := r.store.EncodedObject(plumbing.CommitObject, h)
	if err != nil {
		return nil, fmt.Errorf("stratagit: commit %s: %w", h, git.ErrNotFound)
	}
	c := &object.Commit{}
	if err := c.Decode(o); err != nil {
		return nil, err
	}
	return c, nil
}

func (r *Repo) Commit(oid string) (git.Commit, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	c, err := r.commitAt(plumbing.NewHash(oid))
	if err != nil {
		return git.Commit{}, err
	}
	return git.Commit{OID: oid, Message: c.Message, When: c.Committer.When, Parents: parents(c)}, nil
}

// DiffTree uses go-git's diff, which skips equal subtrees: the interface requires
// cost proportional to what differs.
func (r *Repo) DiffTree(from, to string, paths ...string) ([]git.DiffEntry, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	roots := paths
	if len(roots) == 0 {
		roots = []string{""}
	}
	var out []git.DiffEntry
	for _, p := range roots {
		before, err := r.treeUnder(from, p)
		if err != nil {
			return nil, err
		}
		after, err := r.treeUnder(to, p)
		if err != nil {
			return nil, err
		}
		if err := r.appendChanges(&out, before, after, p); err != nil {
			return nil, err
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	return out, nil
}

// treeUnder is nil where the path names nothing: an empty side of the diff, not
// a failure.
func (r *Repo) treeUnder(treeish, p string) (*object.Tree, error) {
	h, err := r.resolve(treeish)
	if err != nil {
		return nil, err
	}
	t, err := r.treeOf(h)
	if err != nil {
		return nil, err
	}
	if p == "" {
		return t, nil
	}
	sub, err := r.walk(t, p)
	if err != nil {
		return nil, nil
	}
	under, err := r.tree(sub)
	if err != nil {
		return nil, nil
	}
	return under, nil
}

func (r *Repo) appendChanges(out *[]git.DiffEntry, before, after *object.Tree, prefix string) error {
	changes, err := object.DiffTree(before, after)
	if err != nil {
		return fmt.Errorf("stratagit: diffing trees: %w", err)
	}
	for _, c := range changes {
		action, err := c.Action()
		if err != nil {
			return fmt.Errorf("stratagit: %w", err)
		}
		e := git.DiffEntry{OID: c.To.TreeEntry.Hash.String(), Path: path.Join(prefix, c.To.Name)}
		switch action {
		case merkletrie.Insert:
			e.Status = 'A'
		case merkletrie.Modify:
			e.Status = 'M'
		case merkletrie.Delete:
			e.Status, e.Path = 'D', path.Join(prefix, c.From.Name)
			e.OID = plumbing.ZeroHash.String()
		}
		*out = append(*out, e)
	}
	return nil
}

func (r *Repo) Reachable(oid string) (present, missing []string, err error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	seen := map[plumbing.Hash]bool{}
	var visit func(h plumbing.Hash)
	visit = func(h plumbing.Hash) {
		if h.IsZero() || seen[h] {
			return
		}
		seen[h] = true
		o, e := r.store.EncodedObject(plumbing.AnyObject, h)
		if e != nil {
			missing = append(missing, h.String())
			return
		}
		present = append(present, h.String())
		switch o.Type() {
		case plumbing.CommitObject:
			c := &object.Commit{}
			if c.Decode(o) != nil {
				return
			}
			visit(c.TreeHash)
			for _, p := range c.ParentHashes {
				visit(p)
			}
		case plumbing.TreeObject:
			t := &object.Tree{}
			if t.Decode(o) != nil {
				return
			}
			for _, e := range t.Entries {
				visit(e.Hash)
			}
		}
	}
	visit(plumbing.NewHash(oid))
	return present, missing, nil
}

