1	package stratagit
2	
3	import (
4		"fmt"
5		"path"
6		"sort"
7		"strings"
8	
9		"github.com/entirehq/strata/git"
10		"github.com/go-git/go-git/v6/plumbing"
11		"github.com/go-git/go-git/v6/plumbing/filemode"
12		"github.com/go-git/go-git/v6/plumbing/object"
13		"github.com/go-git/go-git/v6/utils/merkletrie"
14	)
15	
16	// resolve understands the two expressions strata writes, an id and
17	// <committish>:<path>, and refuses the rest. The caller holds mu.
18	func (r *Repo) resolve(name string) (plumbing.Hash, error) {
19		base, rest, hasPath := strings.Cut(name, ":")
20		h := plumbing.NewHash(base)
21		if h.IsZero() && base != "" {
22			return plumbing.ZeroHash,
23				fmt.Errorf("stratagit: %q is not an object id: %w", base, git.ErrNotFound)
24		}
25		if !hasPath {
26			return h, nil
27		}
28		tree, err := r.treeOf(h)
29		if err != nil {
30			return plumbing.ZeroHash, err
31		}
32		return r.walk(tree, rest)
33	}
34	
35	func (r *Repo) treeOf(h plumbing.Hash) (*object.Tree, error) {
36		o, err := r.store.EncodedObject(plumbing.AnyObject, h)
37		if err != nil {
38			return nil, fmt.Errorf("stratagit: %s: %w", h, git.ErrNotFound)
39		}
40		switch o.Type() {
41		case plumbing.CommitObject:
42			c := &object.Commit{}
43			if err := c.Decode(o); err != nil {
44				return nil, err
45			}
46			return r.tree(c.TreeHash)
47		case plumbing.TreeObject:
48			return r.tree(h)
49		}
50		return nil, fmt.Errorf("stratagit: %s is a %s, not a commit or tree", h, o.Type())
51	}
52	
53	// tree uses GetTree rather than Decode so the tree keeps its storer, which
54	// go-git's diff needs to descend into subtrees.
55	func (r *Repo) tree(h plumbing.Hash) (*object.Tree, error) {
56		t, err := object.GetTree(r.store, h)
57		if err != nil {
58			return nil, fmt.Errorf("stratagit: tree %s: %w", h, git.ErrNotFound)
59		}
60		return t, nil
61	}
62	
63	func (r *Repo) walk(t *object.Tree, p string) (plumbing.Hash, error) {
64		if p == "" {
65			return plumbing.ZeroHash, fmt.Errorf("stratagit: empty path: %w", git.ErrNotFound)
66		}
67		parts := strings.Split(p, "/")
68		cur := t
69		for i, part := range parts {
70			var found *object.TreeEntry
71			for j := range cur.Entries {
72				if cur.Entries[j].Name == part {
73					found = &cur.Entries[j]
74					break
75				}
76			}
77			if found == nil {
78				return plumbing.ZeroHash, fmt.Errorf("stratagit: %q: %w", p, git.ErrNotFound)
79			}
80			if i == len(parts)-1 {
81				return found.Hash, nil
82			}
83			next, err := r.tree(found.Hash)
84			if err != nil {
85				return plumbing.ZeroHash, err
86			}
87			cur = next
88		}
89		return plumbing.ZeroHash, fmt.Errorf("stratagit: %q: %w", p, git.ErrNotFound)
90	}
91	
92	func (r *Repo) LsTreeRecursive(treeish string) ([]git.TreeEntry, error) {
93		r.mu.RLock()
94		defer r.mu.RUnlock()
95	
96		h, err := r.resolve(treeish)
97		if err != nil {
98			return nil, err
99		}
100		t, err := r.treeOf(h)
101		if err != nil {
102			return nil, err
103		}
104		var out []git.TreeEntry
105		if err := r.collect(t, "", &out); err != nil {
106			return nil, err
107		}
108		// Already sorted by path: git's tree order expands to it. strata's ordered
109		// reads rely on that order.
110		return out, nil
111	}
112	
113	func (r *Repo) collect(t *object.Tree, prefix string, out *[]git.TreeEntry) error {
114		for _, e := range t.Entries {
115			p := path.Join(prefix, e.Name)
116			if e.Mode == filemode.Dir {
117				sub, err := r.tree(e.Hash)
118				if err != nil {
119					return err
120				}
121				if err := r.collect(sub, p, out); err != nil {
122					return err
123				}
124				continue
125			}
126			*out = append(*out, git.TreeEntry{Mode: e.Mode.String(), OID: e.Hash.String(), Path: p})
127		}
128		return nil
129	}
130	
131	// Log walks first parents: strata's logs are single-parent chains, and their
132	// commits share one fixed date, so walk order is the only order.
133	func (r *Repo) Log(tip string) ([]git.Commit, error) {
134		if tip == "" {
135			return nil, nil
136		}
137		start := plumbing.NewHash(tip)
138		if start.IsZero() {
139			return nil, fmt.Errorf("stratagit: %q is not an object id: %w", tip, git.ErrNotFound)
140		}
141		r.mu.RLock()
142		defer r.mu.RUnlock()
143		var out []git.Commit
144		seen := map[plumbing.Hash]bool{}
145		for h := start; ; {
146			if seen[h] {
147				break
148			}
149			seen[h] = true
150			c, err := r.commitAt(h)
151			if err != nil {
152				return nil, err
153			}
154			out = append(out, git.Commit{OID: h.String(), Message: c.Message, When: c.Committer.When, Parents: parents(c)})
155			if len(c.ParentHashes) == 0 {
156				break
157			}
158			h = c.ParentHashes[0]
159		}
160		return out, nil
161	}
162	
163	func parents(c *object.Commit) []string {
164		if len(c.ParentHashes) == 0 {
165			return nil
166		}
167		out := make([]string, len(c.ParentHashes))
168		for i, h := range c.ParentHashes {
169			out[i] = h.String()
170		}
171		return out
172	}
173	
174	func (r *Repo) commitAt(h plumbing.Hash) (*object.Commit, error) {
175		o, err := r.store.EncodedObject(plumbing.CommitObject, h)
176		if err != nil {
177			return nil, fmt.Errorf("stratagit: commit %s: %w", h, git.ErrNotFound)
178		}
179		c := &object.Commit{}
180		if err := c.Decode(o); err != nil {
181			return nil, err
182		}
183		return c, nil
184	}
185	
186	func (r *Repo) Commit(oid string) (git.Commit, error) {
187		r.mu.RLock()
188		defer r.mu.RUnlock()
189		c, err := r.commitAt(plumbing.NewHash(oid))
190		if err != nil {
191			return git.Commit{}, err
192		}
193		return git.Commit{OID: oid, Message: c.Message, When: c.Committer.When, Parents: parents(c)}, nil
194	}
195	
196	// DiffTree uses go-git's diff, which skips equal subtrees: the interface requires
197	// cost proportional to what differs.
198	func (r *Repo) DiffTree(from, to string, paths ...string) ([]git.DiffEntry, error) {
199		r.mu.RLock()
200		defer r.mu.RUnlock()
201	
202		roots := paths
203		if len(roots) == 0 {
204			roots = []string{""}
205		}
206		var out []git.DiffEntry
207		for _, p := range roots {
208			before, err := r.treeUnder(from, p)
209			if err != nil {
210				return nil, err
211			}
212			after, err := r.treeUnder(to, p)
213			if err != nil {
214				return nil, err
215			}
216			if err := r.appendChanges(&out, before, after, p); err != nil {
217				return nil, err
218			}
219		}
220		sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
221		return out, nil
222	}
223	
224	// treeUnder is nil where the path names nothing: an empty side of the diff, not
225	// a failure.
226	func (r *Repo) treeUnder(treeish, p string) (*object.Tree, error) {
227		h, err := r.resolve(treeish)
228		if err != nil {
229			return nil, err
230		}
231		t, err := r.treeOf(h)
232		if err != nil {
233			return nil, err
234		}
235		if p == "" {
236			return t, nil
237		}
238		sub, err := r.walk(t, p)
239		if err != nil {
240			return nil, nil
241		}
242		under, err := r.tree(sub)
243		if err != nil {
244			return nil, nil
245		}
246		return under, nil
247	}
248	
249	func (r *Repo) appendChanges(out *[]git.DiffEntry, before, after *object.Tree, prefix string) error {
250		changes, err := object.DiffTree(before, after)
251		if err != nil {
252			return fmt.Errorf("stratagit: diffing trees: %w", err)
253		}
254		for _, c := range changes {
255			action, err := c.Action()
256			if err != nil {
257				return fmt.Errorf("stratagit: %w", err)
258			}
259			e := git.DiffEntry{OID: c.To.TreeEntry.Hash.String(), Path: path.Join(prefix, c.To.Name)}
260			switch action {
261			case merkletrie.Insert:
262				e.Status = 'A'
263			case merkletrie.Modify:
264				e.Status = 'M'
265			case merkletrie.Delete:
266				e.Status, e.Path = 'D', path.Join(prefix, c.From.Name)
267				e.OID = plumbing.ZeroHash.String()
268			}
269			*out = append(*out, e)
270		}
271		return nil
272	}
273	
274	func (r *Repo) Reachable(oid string) (present, missing []string, err error) {
275		r.mu.RLock()
276		defer r.mu.RUnlock()
277	
278		seen := map[plumbing.Hash]bool{}
279		var visit func(h plumbing.Hash)
280		visit = func(h plumbing.Hash) {
281			if h.IsZero() || seen[h] {
282				return
283			}
284			seen[h] = true
285			o, e := r.store.EncodedObject(plumbing.AnyObject, h)
286			if e != nil {
287				missing = append(missing, h.String())
288				return
289			}
290			present = append(present, h.String())
291			switch o.Type() {
292			case plumbing.CommitObject:
293				c := &object.Commit{}
294				if c.Decode(o) != nil {
295					return
296				}
297				visit(c.TreeHash)
298				for _, p := range c.ParentHashes {
299					visit(p)
300				}
301			case plumbing.TreeObject:
302				t := &object.Tree{}
303				if t.Decode(o) != nil {
304					return
305				}
306				for _, e := range t.Entries {
307					visit(e.Hash)
308				}
309			}
310		}
311		visit(plumbing.NewHash(oid))
312		return present, missing, nil
313	}
