package stratawrite

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"
	"time"

	"github.com/entirehq/entire-records/recordapi"
	recstore "github.com/entirehq/entire-records/store"
	strata "github.com/entirehq/strata/store"
)

// ErrFenced is a write to a writer that could not keep its lease alive.
var ErrFenced = errors.New("stratawrite: writer is fenced")

// Leases is where durable writers record that they are alive (*store.RepoStore).
type Leases interface {
	AcquireStrataLease(ctx context.Context, repoID, storeName, writer, replica string) error
	RenewStrataLease(ctx context.Context, repoID, storeName, writer string) (bool, error)
	ReleaseStrataLeases(ctx context.Context, repoID, storeName string, writers []string) error
	LapsedStrataWriters(ctx context.Context, repoID, storeName string, after time.Duration) ([]string, error)
	HasStrataLease(ctx context.Context, repoID, storeName, writer string) (bool, error)
}

// DefaultEvictAfter is how stale a lease must be before another session evicts
// its writer. A writer fences itself at half of it, before anyone could.
const DefaultEvictAfter = 60 * time.Second

// StaleBlockerAfter evicts a writer with no lease that holds the barrier without
// writing. Nothing here lapses such a writer (a local clone, a CLI), and one that
// walked away would otherwise stop compaction for good.
const StaleBlockerAfter = 24 * time.Hour

// retainGenerations is the depth maintenance keeps, in generation numbers.
// Numbers skip, so this is often the newest generation alone, which is all
// correctness needs.
const retainGenerations = 2

// Writer is one durable strata writer, held for as long as its holder lives.
// One goroutine owns it and calls Tick about every DefaultEvictAfter/4, so an
// idle writer doesn't hold the store's folds back; only Fenced and Abort may be
// used from elsewhere.
type Writer struct {
	s            *strata.Store
	rs           *recordapi.Records
	leases       Leases
	repoID       string
	store        string
	evict        time.Duration
	staleBlocker time.Duration

	fenced    chan struct{}
	stopRenew context.CancelFunc
	close     context.CancelFunc
	done      chan struct{}
}

// Start opens a durable writer on an existing store. Its lease is taken before
// it announces itself.
func Start(ctx context.Context, r Remote, leases Leases, repoID, storeName, replica, author string, evictAfter time.Duration) (w *Writer, err error) {
	// The writer outlives ctx, so its transport gets a context of its own, tied to
	// ctx only while Start runs.
	life, closeLife := context.WithCancel(context.WithoutCancel(ctx))
	unhook := context.AfterFunc(ctx, closeLife)
	defer func() {
		unhook()
		if err != nil {
			closeLife()
		}
	}()
	s, err := r.open(life, storeName)
	if err != nil {
		return nil, err
	}
	s.SetRetention(retainGenerations)
	e := recstore.OpenStore(s, recstore.SchemaRef{Name: storeName}, author, false)
	// Checked before announcing, so no refs land in a store nobody created.
	if err := requireSchema(e, storeName); err != nil {
		return nil, err
	}
	w = &Writer{
		s: s, rs: recordapi.New(e), leases: leases,
		repoID: repoID, store: storeName, evict: evictAfter, staleBlocker: StaleBlockerAfter,
		fenced: make(chan struct{}),
		close:  closeLife,
		done:   make(chan struct{}),
	}
	if err := leases.AcquireStrataLease(ctx, repoID, storeName, w.ID(), replica); err != nil {
		return nil, err
	}
	// No failure from here releases the lease: the writer may already be
	// announced, and its lease is what lets a later session evict it. It is
	// renewed from now on, since starting can outlast the eviction window.
	renewCtx, stopRenew := context.WithCancel(life)
	w.stopRenew = stopRenew
	go w.renew(renewCtx)
	renewed := w.done
	defer func() {
		if err != nil {
			stopRenew()
			<-renewed
		}
	}()
	if err := s.Announce(origin); err != nil {
		return nil, fmt.Errorf("stratawrite: announcing in %s: %w", storeName, err)
	}
	if err := w.maintain(ctx); err != nil {
		slog.WarnContext(ctx, "stratawrite: store maintenance at start",
			slog.String("store", storeName), slog.Any("error", err))
	}
	// Not handed out if the caller gave up (its transport is gone) or the lease
	// was lost meanwhile.
	if !unhook() {
		return nil, fmt.Errorf("stratawrite: starting on %s: %w", storeName, context.Cause(ctx))
	}
	select {
	case <-w.fenced:
		return nil, fmt.Errorf("stratawrite: starting on %s: %w", storeName, ErrFenced)
	default:
	}
	return w, nil
}

func (w *Writer) ID() string { return w.s.Writer() }

// Fenced closes when the writer stops accepting writes; its holder should end it.
func (w *Writer) Fenced() <-chan struct{} { return w.fenced }

func (w *Writer) Apply(ctx context.Context, b recordapi.Batch) ([]recordapi.RecordRef, error) {
	if err := w.live(); err != nil {
		return nil, err
	}
	return w.rs.ApplyBatch(ctx, b, "")
}

func (w *Writer) Reorder(ctx context.Context, typeName string, req recordapi.ReorderRequest) error {
	if err := w.live(); err != nil {
		return err
	}
	return w.rs.Reorder(ctx, typeName, req)
}

func (w *Writer) Push(ctx context.Context, typeName, id, field, value string) error {
	if err := w.live(); err != nil {
		return err
	}
	_, err := w.rs.PushListEntry(ctx, typeName, id, field, value)
	return err
}

func (w *Writer) Fold(ctx context.Context, typeName, id, field string, remove []string, value string) error {
	if err := w.live(); err != nil {
		return err
	}
	_, err := w.rs.FoldListEntries(ctx, typeName, id, field, remove, value)
	return err
}

func (w *Writer) live() error {
	select {
	case <-w.fenced:
		return ErrFenced
	default:
		return nil
	}
}

// Publish pushes what Apply, Reorder, Push and Fold committed, which they leave
// local so a burst shares one push. A failed push is logged rather than returned:
// strata keeps the commits queued for the next push, and an error would invite
// the caller to write twice.
func (w *Writer) Publish(ctx context.Context) {
	if err := w.s.Push(origin); err != nil {
		slog.WarnContext(ctx, "stratawrite: publishing deferred to the next push",
			slog.String("store", w.store), slog.String("writer", w.ID()), slog.Any("error", err))
	}
}

// Tick catches up with other writers, lifts this writer's low-water mark if it
// holds the barrier, then runs the same maintenance as Start.
func (w *Writer) Tick(ctx context.Context) error {
	if err := w.live(); err != nil {
		return err
	}
	if err := w.s.Fetch(origin); err != nil {
		return fmt.Errorf("stratawrite: fetching %s: %w", w.store, err)
	}
	if _, err := w.s.Lift(); err != nil {
		return fmt.Errorf("stratawrite: lifting %s: %w", w.ID(), err)
	}
	return w.maintain(ctx)
}

// End evicts this writer, publishes, then releases its lease. Only a leased
// writer can be evicted by another session, so the lease goes last.
func (w *Writer) End(ctx context.Context) error {
	// The transport doesn't use ctx, so ctx ending cuts it instead.
	stop := context.AfterFunc(ctx, w.close)
	defer stop()
	w.stopRenew()
	<-w.done
	defer w.close()
	// An eviction another session already published is adopted on push.
	if err := w.s.Evict(w.ID()); err != nil {
		return fmt.Errorf("evicting self: %w", err)
	}
	if err := w.s.Push(origin); err != nil {
		return fmt.Errorf("publishing: %w", err)
	}
	return w.release(ctx, w.ID())
}

// Abort cuts the writer's transport for good, End included, so its lease lapses.
// Unlike the rest of Writer, any goroutine may call it, more than once, and
// while End runs.
func (w *Writer) Abort() { w.close() }

// maintain evicts writers whose leases lapsed, folds, then retires the evicted
// writers the fold covers, best-effort. A writer the fold doesn't cover yet
// (ErrNotFolded) is left for a later session. Evicted writers' leases go only
// once the evictions are published, as in End.
func (w *Writer) maintain(ctx context.Context) error {
	var errs []error
	evicted, err := w.evictLapsed(ctx)
	if err != nil {
		errs = append(errs, err)
	}
	if err := w.evictStaleBlocker(ctx); err != nil {
		errs = append(errs, err)
	}
	if _, err := w.s.Compact(); err != nil {
		errs = append(errs, fmt.Errorf("compacting: %w", err))
	}
	if err := w.retireEvicted(); err != nil {
		errs = append(errs, err)
	}
	if _, err := w.s.RetainGenerations(); err != nil {
		errs = append(errs, fmt.Errorf("retaining generations: %w", err))
	}
	if err := w.s.Push(origin); err != nil {
		errs = append(errs, fmt.Errorf("publishing: %w", err))
	} else if len(evicted) > 0 {
		errs = append(errs, w.release(ctx, evicted...))
	}
	return errors.Join(errs...)
}

func (w *Writer) evictLapsed(ctx context.Context) ([]string, error) {
	lapsed, err := w.leases.LapsedStrataWriters(ctx, w.repoID, w.store, w.evict)
	if err != nil {
		return nil, err
	}
	if len(lapsed) == 0 {
		return nil, nil
	}
	// A lapsed writer may already be evicted, by an End that published and then
	// failed to release. Evicting it again would queue an eviction the remote
	// refuses, failing every later push.
	already, err := w.s.EvictedWriters()
	if err != nil {
		return nil, err
	}
	var evicted []string
	var errs []error
	for _, other := range lapsed {
		if other == w.ID() {
			continue
		}
		if slices.Contains(already, other) {
			evicted = append(evicted, other)
			continue
		}
		if err := w.s.Evict(other); err != nil {
			errs = append(errs, fmt.Errorf("evicting lapsed %s: %w", other, err))
			continue
		}
		evicted = append(evicted, other)
	}
	return evicted, errors.Join(errs...)
}

// evictStaleBlocker leaves a writer that never wrote: it has no age to judge.
func (w *Writer) evictStaleBlocker(ctx context.Context) error {
	r, err := w.s.Status()
	if err != nil {
		return fmt.Errorf("surveying %s: %w", w.store, err)
	}
	if r.Blocking == "" || r.Blocking == w.ID() || r.BlockingSince.IsZero() ||
		time.Since(r.BlockingSince) < w.staleBlocker {
		return nil
	}
	leased, err := w.leases.HasStrataLease(ctx, w.repoID, w.store, r.Blocking)
	if err != nil || leased {
		return err
	}
	slog.WarnContext(ctx, "stratawrite: evicting a writer with no lease that has held the barrier since it last wrote",
		slog.String("store", w.store), slog.String("writer", r.Blocking),
		slog.Time("last_wrote", r.BlockingSince), slog.Uint64("barrier", r.Barrier))
	// Blocking is drawn only from writers not yet evicted, so this never
	// repeats an eviction the remote would refuse.
	if err := w.s.Evict(r.Blocking); err != nil {
		return fmt.Errorf("evicting stale %s: %w", r.Blocking, err)
	}
	return nil
}

func (w *Writer) retireEvicted() error {
	evicted, err := w.s.EvictedWriters()
	if err != nil {
		return err
	}
	for _, other := range evicted {
		if other == w.ID() {
			continue
		}
		if _, err := w.s.Retire(other); err != nil && !errors.Is(err, strata.ErrNotFolded) {
			return fmt.Errorf("retiring %s: %w", other, err)
		}
	}
	return nil
}

func (w *Writer) release(ctx context.Context, writers ...string) error {
	return w.leases.ReleaseStrataLeases(ctx, w.repoID, w.store, writers)
}

// renew fences the writer once the lease is gone or renewing has failed for
// half the eviction window.
func (w *Writer) renew(ctx context.Context) {
	defer close(w.done)
	t := time.NewTicker(w.evict / 4)
	defer t.Stop()
	lastOK := time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
		}
		// Bounded so a renewal stuck on the database can't outlast the fence.
		rctx, cancel := context.WithDeadline(ctx, lastOK.Add(w.evict/2))
		ok, err := w.leases.RenewStrataLease(rctx, w.repoID, w.store, w.ID())
		cancel()
		if ctx.Err() != nil {
			return
		}
		why := ""
		switch {
		case err == nil && ok:
			lastOK = time.Now()
		case err == nil:
			why = "lease is gone"
		case time.Since(lastOK) >= w.evict/2:
			why = err.Error()
		}
		if why != "" {
			slog.WarnContext(ctx, "stratawrite: writer fenced",
				slog.String("store", w.store), slog.String("writer", w.ID()), slog.String("why", why))
			close(w.fenced)
			return
		}
	}
}

