// Package stratawritetest stands local bare repositories in for entiredb.
package stratawritetest

import (
	"errors"
	"io"
	"net/http"
	"net/http/cgi"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/entirehq/entire-records/schema"
	"github.com/entirehq/strata/git"
	"github.com/entirehq/strata/gitbin"
)

// BareRepo creates an empty bare repository; its path works as a Remote's URL.
func BareRepo(t testing.TB) string {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "remote.git")
	if _, err := gitbin.Init(dir, git.InitOptions{Bare: true}); err != nil {
		t.Fatalf("bare remote: %v", err)
	}
	return dir
}

// HTTPRemote serves the bare repository at dir over git http-backend. stall
// makes every later request hang until its client gives up; pushes counts the
// pushes it has received.
func HTTPRemote(t testing.TB, dir string) (url string, stall func(), pushes func() int64) {
	t.Helper()
	git, err := exec.LookPath("git")
	if err != nil {
		t.Skipf("git http-backend: %v", err)
	}
	backend := &cgi.Handler{
		Path: git, Args: []string{"http-backend"},
		// REMOTE_USER is what lets http-backend take a push.
		Env:        []string{"GIT_PROJECT_ROOT=" + filepath.Dir(dir), "GIT_HTTP_EXPORT_ALL=1", "REMOTE_USER=test"},
		InheritEnv: []string{"PATH", "HOME"},
	}
	var stalled atomic.Bool
	var received atomic.Int64
	// Closed before the server, whose Close waits for every request: one
	// still hanging when the test ends lets go then.
	released := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if stalled.Load() {
			select {
			case <-r.Context().Done():
			case <-released:
			}
			return
		}
		if isPush(r) {
			received.Add(1)
		}
		backend.ServeHTTP(w, r)
	}))
	t.Cleanup(srv.Close)
	t.Cleanup(func() { close(released) })
	return srv.URL + "/" + filepath.Base(dir), func() { stalled.Store(true) }, received.Load
}

func Planning() schema.Schema {
	return schema.Schema{Name: "planning", Types: []schema.TypeDef{
		{Name: "plan", Ordered: true, Fields: []schema.FieldDef{
			{Key: "title", Type: schema.FieldString},
			{Key: "edits", Type: schema.FieldList},
		}},
	}}
}

// HTTPRepo serves a BareRepo over git http-backend, as entiredb serves one,
// and returns both its URL and its path.
func HTTPRepo(t testing.TB) (url, dir string) {
	t.Helper()
	dir = BareRepo(t)
	backend, err := exec.Command("git", "--exec-path").Output()
	if err != nil {
		t.Skipf("no git exec path: %v", err)
	}
	srv := httptest.NewServer(&cgi.Handler{
		Path: filepath.Join(strings.TrimSpace(string(backend)), "git-http-backend"),
		Env: []string{
			"GIT_PROJECT_ROOT=" + filepath.Dir(dir),
			"GIT_HTTP_EXPORT_ALL=1",
			// receive-pack is off for anonymous callers unless asked for.
			"REMOTE_USER=test",
		},
	})
	t.Cleanup(srv.Close)
	return srv.URL + "/" + filepath.Base(dir), dir
}

// RefusePushes makes the repository at dir decline every push from now on.
func RefusePushes(t testing.TB, dir string) {
	t.Helper()
	hook := filepath.Join(dir, "hooks", "pre-receive")
	if err := os.MkdirAll(filepath.Dir(hook), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(hook, []byte("#!/bin/sh\nexit 1\n"), 0o755); err != nil {
		t.Fatal(err)
	}
}

// FailsFirstPush fails the first push before it reaches the server.
type FailsFirstPush struct{ failed bool }

func (f *FailsFirstPush) RoundTrip(req *http.Request) (*http.Response, error) {
	if !f.failed && isPush(req) {
		f.failed = true
		return nil, errors.New("connection reset before the push was sent")
	}
	return http.DefaultTransport.RoundTrip(req)
}

// LosesPushResponse lets the first push land, then reports it failed. With Down
// set, every later request fails too.
type LosesPushResponse struct {
	Down bool
	lost bool
}

func (l *LosesPushResponse) RoundTrip(req *http.Request) (*http.Response, error) {
	if l.lost && l.Down {
		return nil, errors.New("connection refused")
	}
	resp, err := http.DefaultTransport.RoundTrip(req)
	if err != nil || l.lost || !isPush(req) {
		return resp, err
	}
	l.lost = true
	// Read to the end, so the server has finished updating refs before the
	// caller hears it failed.
	_, _ = io.Copy(io.Discard, resp.Body)
	_ = resp.Body.Close()
	return nil, errors.New("connection reset after the push landed")
}

func isPush(r *http.Request) bool {
	return r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/git-receive-pack")
}

