1	// Package stratawritetest stands local bare repositories in for entiredb.
2	package stratawritetest
3	
4	import (
5		"errors"
6		"io"
7		"net/http"
8		"net/http/cgi"
9		"net/http/httptest"
10		"os"
11		"os/exec"
12		"path/filepath"
13		"strings"
14		"sync/atomic"
15		"testing"
16	
17		"github.com/entirehq/entire-records/schema"
18		"github.com/entirehq/strata/git"
19		"github.com/entirehq/strata/gitbin"
20	)
21	
22	// BareRepo creates an empty bare repository; its path works as a Remote's URL.
23	func BareRepo(t testing.TB) string {
24		t.Helper()
25		dir := filepath.Join(t.TempDir(), "remote.git")
26		if _, err := gitbin.Init(dir, git.InitOptions{Bare: true}); err != nil {
27			t.Fatalf("bare remote: %v", err)
28		}
29		return dir
30	}
31	
32	// HTTPRemote serves the bare repository at dir over git http-backend. stall
33	// makes every later request hang until its client gives up; pushes counts the
34	// pushes it has received.
35	func HTTPRemote(t testing.TB, dir string) (url string, stall func(), pushes func() int64) {
36		t.Helper()
37		git, err := exec.LookPath("git")
38		if err != nil {
39			t.Skipf("git http-backend: %v", err)
40		}
41		backend := &cgi.Handler{
42			Path: git, Args: []string{"http-backend"},
43			// REMOTE_USER is what lets http-backend take a push.
44			Env:        []string{"GIT_PROJECT_ROOT=" + filepath.Dir(dir), "GIT_HTTP_EXPORT_ALL=1", "REMOTE_USER=test"},
45			InheritEnv: []string{"PATH", "HOME"},
46		}
47		var stalled atomic.Bool
48		var received atomic.Int64
49		// Closed before the server, whose Close waits for every request: one
50		// still hanging when the test ends lets go then.
51		released := make(chan struct{})
52		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
53			if stalled.Load() {
54				select {
55				case <-r.Context().Done():
56				case <-released:
57				}
58				return
59			}
60			if isPush(r) {
61				received.Add(1)
62			}
63			backend.ServeHTTP(w, r)
64		}))
65		t.Cleanup(srv.Close)
66		t.Cleanup(func() { close(released) })
67		return srv.URL + "/" + filepath.Base(dir), func() { stalled.Store(true) }, received.Load
68	}
69	
70	func Planning() schema.Schema {
71		return schema.Schema{Name: "planning", Types: []schema.TypeDef{
72			{Name: "plan", Ordered: true, Fields: []schema.FieldDef{
73				{Key: "title", Type: schema.FieldString},
74				{Key: "edits", Type: schema.FieldList},
75			}},
76		}}
77	}
78	
79	// HTTPRepo serves a BareRepo over git http-backend, as entiredb serves one,
80	// and returns both its URL and its path.
81	func HTTPRepo(t testing.TB) (url, dir string) {
82		t.Helper()
83		dir = BareRepo(t)
84		backend, err := exec.Command("git", "--exec-path").Output()
85		if err != nil {
86			t.Skipf("no git exec path: %v", err)
87		}
88		srv := httptest.NewServer(&cgi.Handler{
89			Path: filepath.Join(strings.TrimSpace(string(backend)), "git-http-backend"),
90			Env: []string{
91				"GIT_PROJECT_ROOT=" + filepath.Dir(dir),
92				"GIT_HTTP_EXPORT_ALL=1",
93				// receive-pack is off for anonymous callers unless asked for.
94				"REMOTE_USER=test",
95			},
96		})
97		t.Cleanup(srv.Close)
98		return srv.URL + "/" + filepath.Base(dir), dir
99	}
100	
101	// RefusePushes makes the repository at dir decline every push from now on.
102	func RefusePushes(t testing.TB, dir string) {
103		t.Helper()
104		hook := filepath.Join(dir, "hooks", "pre-receive")
105		if err := os.MkdirAll(filepath.Dir(hook), 0o755); err != nil {
106			t.Fatal(err)
107		}
108		if err := os.WriteFile(hook, []byte("#!/bin/sh\nexit 1\n"), 0o755); err != nil {
109			t.Fatal(err)
110		}
111	}
112	
113	// FailsFirstPush fails the first push before it reaches the server.
114	type FailsFirstPush struct{ failed bool }
115	
116	func (f *FailsFirstPush) RoundTrip(req *http.Request) (*http.Response, error) {
117		if !f.failed && isPush(req) {
118			f.failed = true
119			return nil, errors.New("connection reset before the push was sent")
120		}
121		return http.DefaultTransport.RoundTrip(req)
122	}
123	
124	// LosesPushResponse lets the first push land, then reports it failed. With Down
125	// set, every later request fails too.
126	type LosesPushResponse struct {
127		Down bool
128		lost bool
129	}
130	
131	func (l *LosesPushResponse) RoundTrip(req *http.Request) (*http.Response, error) {
132		if l.lost && l.Down {
133			return nil, errors.New("connection refused")
134		}
135		resp, err := http.DefaultTransport.RoundTrip(req)
136		if err != nil || l.lost || !isPush(req) {
137			return resp, err
138		}
139		l.lost = true
140		// Read to the end, so the server has finished updating refs before the
141		// caller hears it failed.
142		_, _ = io.Copy(io.Discard, resp.Body)
143		_ = resp.Body.Close()
144		return nil, errors.New("connection reset after the push landed")
145	}
146	
147	func isPush(r *http.Request) bool {
148		return r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/git-receive-pack")
149	}
