1	// Package records serves a repo's entire-records stores from this cell's
2	// Postgres projection of them.
3	//
4	// The decode is entire-records', imported over its store.Projection seam and
5	// never reimplemented here. Every read first catches the projection up, so a
6	// landed write is visible to the next read.
7	package records
8	
9	import (
10		"context"
11		"fmt"
12	
13		"github.com/entirehq/entire-records/recordapi"
14		recschema "github.com/entirehq/entire-records/schema"
15		recstore "github.com/entirehq/entire-records/store"
16	
17		"github.com/entirehq/entire-api/internal/recordchange"
18	)
19	
20	// Source is where a read finds a store (recordprojection.Reads).
21	type Source interface {
22		// Open catches one store's projection up and returns a view of that state
23		// alone, so everything one request decodes agrees with its tip. The caller
24		// must call Release; on error there is nothing to release.
25		Open(ctx context.Context, repoID, store string) (Opened, error)
26		// Stores names every strata store in the repo, records or not: sorted,
27		// each once.
28		Stores(ctx context.Context, repoID string) ([]string, error)
29	}
30	
31	// Opened is one state of a store, held until Release.
32	type Opened struct {
33		Projection   recstore.Projection
34		At           State
35		ChangedSince func(tick uint64) ([]recordchange.Record, error)
36		Release      func()
37	}
38	
39	// State says where a store stands. Tip is equal for equal states; Generation
40	// and Tick place it for a changes read. Removals digests the expiry and erasure
41	// sets, which delete rows rather than write them, so no tick can tell them.
42	type State struct {
43		Tip        string
44		Generation uint64
45		Tick       uint64
46		Removals   string
47	}
48	
49	// Reader answers records reads for a repo's stores.
50	type Reader struct{ src Source }
51	
52	// New builds a Reader over a source of projections.
53	func New(src Source) *Reader { return &Reader{src: src} }
54	
55	type SchemaResult struct {
56		Tip     string
57		Version int
58		Schema  recordapi.SchemaDTO
59	}
60	
61	type recordDTO = recordapi.RecordDTO
62	
63	// CollectionsResult is one page of records, all from one state of the store.
64	// Flat rather than keyed by type, so that it can be paged.
65	type CollectionsResult struct {
66		Tip          string
67		ChangesToken string
68		Records      []recordDTO
69		NextToken    string
70	}
71	
72	type CollectionResult struct {
73		Tip       string
74		Type      string
75		Records   []recordDTO
76		NextToken string
77	}
78	
79	type RecordResult struct {
80		Tip    string
81		Record recordapi.RecordDetailDTO
82	}
83	
84	func (r *Reader) Schema(ctx context.Context, repoID, address string) (SchemaResult, error) {
85		o, err := r.open(ctx, repoID, address)
86		if err != nil {
87			return SchemaResult{}, err
88		}
89		defer o.Release()
90		return SchemaResult{Tip: o.At.Tip, Version: o.schema.Version, Schema: recordapi.ShapeSchema(o.schema)}, nil
91	}
92	
93	// Collections reads several types' records from one state of the store, so they
94	// agree about what exists. No types means every declared type, nested included.
95	func (r *Reader) Collections(ctx context.Context, repoID, address string, types []string, page Page) (CollectionsResult, error) {
96		var cursor recordsCursor
97		if page.Token != "" {
98			var err error
99			if cursor, err = decodeRecordsCursor(page.Token, types); err != nil {
100				return CollectionsResult{}, err
101			}
102		}
103		o, err := r.open(ctx, repoID, address)
104		if err != nil {
105			return CollectionsResult{}, err
106		}
107		defer o.Release()
108		if page.Token != "" {
109			if err := o.resumes(cursor); err != nil {
110				return CollectionsResult{}, err
111			}
112		} else {
113			if len(types) == 0 {
114				types = declaredTypes(o.schema)
115			}
116			cursor = recordsCursor{Tip: o.At.Tip, Types: types}
117		}
118		if cursor.Types, err = distinctDeclaredTypes(o.schema, cursor.Types); err != nil {
119			return CollectionsResult{}, err
120		}
121		return o.page(cursor, page)
122	}
123	
124	func (o opened) page(cursor recordsCursor, page Page) (CollectionsResult, error) {
125		records, next, err := pageOf(cursor, page.size(), func(typeName string) ([]recordDTO, error) {
126			return readType(o.store, o.schema, typeName)
127		})
128		if err != nil {
129			return CollectionsResult{}, err
130		}
131		return CollectionsResult{Tip: o.At.Tip, ChangesToken: o.changesToken(), Records: records, NextToken: next}, nil
132	}
133	
134	func distinctDeclaredTypes(s recschema.Schema, types []string) ([]string, error) {
135		out := dedupe(types)
136		for _, typeName := range out {
137			if _, ok := s.Type(typeName); !ok {
138				return nil, &unknownTypeError{schema: s.Name, typeName: typeName}
139			}
140		}
141		return out, nil
142	}
143	
144	func (r *Reader) Collection(ctx context.Context, repoID, address, typeName string, page Page) (CollectionResult, error) {
145		res, err := r.Collections(ctx, repoID, address, []string{typeName}, page)
146		if err != nil {
147			return CollectionResult{}, err
148		}
149		return CollectionResult{Tip: res.Tip, Type: typeName, Records: res.Records, NextToken: res.NextToken}, nil
150	}
151	
152	// Record reads one record with its children and nested records, reported apart:
153	// a child can be reparented and opened at its own address, a nested record
154	// cannot.
155	func (r *Reader) Record(ctx context.Context, repoID, address, typeName, id string) (RecordResult, error) {
156		if len(id) > maxRecordIDLen {
157			return RecordResult{}, fmt.Errorf("%w: record id is %d bytes, limit %d",
158				recstore.ErrInvalid, len(id), maxRecordIDLen)
159		}
160		o, err := r.open(ctx, repoID, address)
161		if err != nil {
162			return RecordResult{}, err
163		}
164		defer o.Release()
165		rt, ok := o.schema.Type(typeName)
166		if !ok {
167			return RecordResult{}, &unknownTypeError{schema: o.schema.Name, typeName: typeName}
168		}
169		detail, err := recordapi.ShapeRecordDetail(o.store, rt, id)
170		if err != nil {
171			return RecordResult{}, err
172		}
173		return RecordResult{Tip: o.At.Tip, Record: detail}, nil
174	}
175	
176	// readType lists one type's records. ShapeRecords also rank-sorts an ordered
177	// type, which a hand-rolled loop would miss.
178	func readType(v *recstore.Snapshot, s recschema.Schema, typeName string) ([]recordapi.RecordDTO, error) {
179		rt, ok := s.Type(typeName)
180		if !ok {
181			return nil, &unknownTypeError{schema: s.Name, typeName: typeName}
182		}
183		records, err := v.ListRecordsByType(rt)
184		if err != nil {
185			return nil, err
186		}
187		return recordapi.ShapeRecords(rt, records), nil
188	}
189	
190	func declaredTypes(s recschema.Schema) []string {
191		names := make([]string, 0, len(s.Types))
192		for _, t := range s.Types {
