// Package records serves a repo's entire-records stores from this cell's
// Postgres projection of them.
//
// The decode is entire-records', imported over its store.Projection seam and
// never reimplemented here. Every read first catches the projection up, so a
// landed write is visible to the next read.
package records

import (
	"context"
	"fmt"

	"github.com/entirehq/entire-records/recordapi"
	recschema "github.com/entirehq/entire-records/schema"
	recstore "github.com/entirehq/entire-records/store"

	"github.com/entirehq/entire-api/internal/recordchange"
)

// Source is where a read finds a store (recordprojection.Reads).
type Source interface {
	// Open catches one store's projection up and returns a view of that state
	// alone, so everything one request decodes agrees with its tip. The caller
	// must call Release; on error there is nothing to release.
	Open(ctx context.Context, repoID, store string) (Opened, error)
	// Stores names every strata store in the repo, records or not: sorted,
	// each once.
	Stores(ctx context.Context, repoID string) ([]string, error)
}

// Opened is one state of a store, held until Release.
type Opened struct {
	Projection   recstore.Projection
	At           State
	ChangedSince func(tick uint64) ([]recordchange.Record, error)
	Release      func()
}

// State says where a store stands. Tip is equal for equal states; Generation
// and Tick place it for a changes read. Removals digests the expiry and erasure
// sets, which delete rows rather than write them, so no tick can tell them.
type State struct {
	Tip        string
	Generation uint64
	Tick       uint64
	Removals   string
}

// Reader answers records reads for a repo's stores.
type Reader struct{ src Source }

// New builds a Reader over a source of projections.
func New(src Source) *Reader { return &Reader{src: src} }

type SchemaResult struct {
	Tip     string
	Version int
	Schema  recordapi.SchemaDTO
}

type recordDTO = recordapi.RecordDTO

// CollectionsResult is one page of records, all from one state of the store.
// Flat rather than keyed by type, so that it can be paged.
type CollectionsResult struct {
	Tip          string
	ChangesToken string
	Records      []recordDTO
	NextToken    string
}

type CollectionResult struct {
	Tip       string
	Type      string
	Records   []recordDTO
	NextToken string
}

type RecordResult struct {
	Tip    string
	Record recordapi.RecordDetailDTO
}

func (r *Reader) Schema(ctx context.Context, repoID, address string) (SchemaResult, error) {
	o, err := r.open(ctx, repoID, address)
	if err != nil {
		return SchemaResult{}, err
	}
	defer o.Release()
	return SchemaResult{Tip: o.At.Tip, Version: o.schema.Version, Schema: recordapi.ShapeSchema(o.schema)}, nil
}

// Collections reads several types' records from one state of the store, so they
// agree about what exists. No types means every declared type, nested included.
func (r *Reader) Collections(ctx context.Context, repoID, address string, types []string, page Page) (CollectionsResult, error) {
	var cursor recordsCursor
	if page.Token != "" {
		var err error
		if cursor, err = decodeRecordsCursor(page.Token, types); err != nil {
			return CollectionsResult{}, err
		}
	}
	o, err := r.open(ctx, repoID, address)
	if err != nil {
		return CollectionsResult{}, err
	}
	defer o.Release()
	if page.Token != "" {
		if err := o.resumes(cursor); err != nil {
			return CollectionsResult{}, err
		}
	} else {
		if len(types) == 0 {
			types = declaredTypes(o.schema)
		}
		cursor = recordsCursor{Tip: o.At.Tip, Types: types}
	}
	if cursor.Types, err = distinctDeclaredTypes(o.schema, cursor.Types); err != nil {
		return CollectionsResult{}, err
	}
	return o.page(cursor, page)
}

func (o opened) page(cursor recordsCursor, page Page) (CollectionsResult, error) {
	records, next, err := pageOf(cursor, page.size(), func(typeName string) ([]recordDTO, error) {
		return readType(o.store, o.schema, typeName)
	})
	if err != nil {
		return CollectionsResult{}, err
	}
	return CollectionsResult{Tip: o.At.Tip, ChangesToken: o.changesToken(), Records: records, NextToken: next}, nil
}

func distinctDeclaredTypes(s recschema.Schema, types []string) ([]string, error) {
	out := dedupe(types)
	for _, typeName := range out {
		if _, ok := s.Type(typeName); !ok {
			return nil, &unknownTypeError{schema: s.Name, typeName: typeName}
		}
	}
	return out, nil
}

func (r *Reader) Collection(ctx context.Context, repoID, address, typeName string, page Page) (CollectionResult, error) {
	res, err := r.Collections(ctx, repoID, address, []string{typeName}, page)
	if err != nil {
		return CollectionResult{}, err
	}
	return CollectionResult{Tip: res.Tip, Type: typeName, Records: res.Records, NextToken: res.NextToken}, nil
}

// Record reads one record with its children and nested records, reported apart:
// a child can be reparented and opened at its own address, a nested record
// cannot.
func (r *Reader) Record(ctx context.Context, repoID, address, typeName, id string) (RecordResult, error) {
	if len(id) > maxRecordIDLen {
		return RecordResult{}, fmt.Errorf("%w: record id is %d bytes, limit %d",
			recstore.ErrInvalid, len(id), maxRecordIDLen)
	}
	o, err := r.open(ctx, repoID, address)
	if err != nil {
		return RecordResult{}, err
	}
	defer o.Release()
	rt, ok := o.schema.Type(typeName)
	if !ok {
		return RecordResult{}, &unknownTypeError{schema: o.schema.Name, typeName: typeName}
	}
	detail, err := recordapi.ShapeRecordDetail(o.store, rt, id)
	if err != nil {
		return RecordResult{}, err
	}
	return RecordResult{Tip: o.At.Tip, Record: detail}, nil
}

// readType lists one type's records. ShapeRecords also rank-sorts an ordered
// type, which a hand-rolled loop would miss.
func readType(v *recstore.Snapshot, s recschema.Schema, typeName string) ([]recordapi.RecordDTO, error) {
	rt, ok := s.Type(typeName)
	if !ok {
		return nil, &unknownTypeError{schema: s.Name, typeName: typeName}
	}
	records, err := v.ListRecordsByType(rt)
	if err != nil {
		return nil, err
	}
	return recordapi.ShapeRecords(rt, records), nil
}

func declaredTypes(s recschema.Schema) []string {
	names := make([]string, 0, len(s.Types))
	for _, t := range s.Types {
		names = append(names, t.Name)
	}
	return names
}

// opened is one state of a store with its schema read. Every opened is
// released.
type opened struct {
	Opened
	store  *recstore.Snapshot
	schema recschema.Schema
	// key names the store this state is of, for a changes token to carry.
	key string
}

// resumes refuses a token from another state: its offsets count into that one.
func (o opened) resumes(c recordsCursor) error {
	if c.Tip != o.At.Tip {
		return fmt.Errorf("%w: the token was issued at %s, the store is now at %s", ErrStoreMoved, c.Tip, o.At.Tip)
	}
	return nil
}

// open catches the store up and reads its schema. A store whose schema declares
// no type is no records store.
func (r *Reader) open(ctx context.Context, repoID, address string) (opened, error) {
	ref, err := parseSchemaAddress(address)
	if err != nil {
		return opened{}, err
	}
	src, err := r.src.Open(ctx, repoID, ref.Name)
	if err != nil {
		return opened{}, err
	}
	store := recstore.NewSnapshot(ref.Name, recstore.NewProjectionReader(src.Projection))
	schema, err := store.LoadSchema()
	if err == nil && len(schema.Types) == 0 {
		err = &noSchemaError{address: ref.String()}
	}
	if err != nil {
		src.Release()
		return opened{}, err
	}
	return opened{Opened: src, store: store, schema: schema, key: changesKey(repoID, ref)}, nil
}

