package records

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"slices"

	recstore "github.com/entirehq/entire-records/store"
)

// Page bounds one page of a list read: how many records to return, and where to
// resume. An empty Token starts at the beginning; Size <= 0 takes the default.
type Page struct {
	Size  int
	Token string
}

// Page size bounds (API standard PAGE-002).
const (
	defaultPageSize = 50
	maxPageSize     = 100
)

// errInvalidPageToken means a page token is not one this service issued, or
// contradicts the read it claims to continue. A caller mistake, so it wraps
// store.ErrInvalid and maps to 400 with every other bad request.
var errInvalidPageToken = REDACTED invalid pageToken", recstore.ErrInvalid)

// size clamps a caller's page size into the declared bounds.
func (p Page) size() int {
	switch {
	case p.Size <= 0:
		return defaultPageSize
	case p.Size > maxPageSize:
		return maxPageSize
	}
	return p.Size
}

// recordsCursor is where a paged records read resumes.
//
// It carries the tip it started at, which is what makes the offset below
// meaningful: one state of the store yields the same records in the same order
// every time, so "the 12th record of the 3rd type" names the same record on page
// 2 as it did on page 1. A continuation against a state the store has left is
// refused (ErrStoreMoved) rather than answered from shifted positions.
//
// The position is a type index plus an offset within that type, not a single
// offset across the whole read. That is what lets a continuation skip the types
// it has already returned instead of re-reading them to count past them — the
// difference between paging that costs one store read per page and paging that
// costs a whole store read per page.
type recordsCursor struct {
	Tip   string   `json:"tip"`
	Types []string `json:"types"`
	// TypeIndex indexes Types; Offset counts records already returned from that
	// type.
	TypeIndex int `json:"typeIndex"`
	Offset    int `json:"offset"`
}

func (c recordsCursor) encode() string { return encodeToken(c) }

// decodeRecordsCursor reads a token back, and refuses one that contradicts the
// read it is being used to continue.
//
// An omitted parameter inherits the token's value, which is the common case: a
// client that pages by following nextPageToken alone sends nothing else. A
// different non-empty value is a caller bug, and saying so beats answering a
// different question under the same cursor.
func decodeRecordsCursor(token string, types []string) (recordsCursor, error) {
	c, err := decodeToken[recordsCursor](token)
	if err != nil {
		return recordsCursor{}, err
	}
	if c.Tip == "" || c.TypeIndex < 0 || c.Offset < 0 {
		return recordsCursor{}, fmt.Errorf("%w: token names no position", errInvalidPageToken)
	}
	// Compared as the set it is — deduplicated and order-insensitive — because
	// the token holds a set and the walk does not read this list at all. A
	// continuation is driven entirely by the token's own Types, whose order the
	// TypeIndex is relative to, so a client that lists the same types in a
	// different order (out of a map, say) is asking the identical question and
	// gets the identical answer. Accepting it costs nothing; refusing it fails a
	// request that is genuinely consistent.
	if len(types) > 0 && !sameTypeSet(types, c.Types) {
		return recordsCursor{}, fmt.Errorf("%w: token covers types %v, request asks for %v", errInvalidPageToken, c.Types, types)
	}
	return c, nil
}

// pageOf walks the requested types from where the cursor left off and collects
// at most size records, reporting where the next page resumes.
//
// read is called once per type actually needed, so a continuation deep in the
// last type does not read the types before it.
func pageOf(cursor recordsCursor, size int, read func(typeName string) ([]recordDTO, error)) ([]recordDTO, string, error) {
	out := make([]recordDTO, 0, size)
	for i := cursor.TypeIndex; i < len(cursor.Types); i++ {
		records, err := read(cursor.Types[i])
		if err != nil {
			return nil, "", err
		}
		offset := 0
		if i == cursor.TypeIndex {
			offset = cursor.Offset
		}
		if offset > len(records) {
			// Only reachable from a hand-edited token: one state of the store
			// yields the same count every time.
			return nil, "", fmt.Errorf("%w: token resumes past the end of %q", errInvalidPageToken, cursor.Types[i])
		}
		for ; offset < len(records); offset++ {
			if len(out) == size {
				next := recordsCursor{Tip: cursor.Tip, Types: cursor.Types, TypeIndex: i, Offset: offset}
				return out, next.encode(), nil
			}
			out = append(out, records[offset])
		}
	}
	return out, "", nil
}

// schemasCursor is where a paged schema listing resumes.
//
// The last name rather than an offset: the listing spans every store, and a
// store can appear between pages. An offset would then skip or repeat one;
// resuming after a name cannot.
type schemasCursor struct {
	LastName string `json:"lastName"`
}

func (c schemasCursor) encode() string { return encodeToken(c) }

func decodeSchemasCursor(token string) (schemasCursor, error) {
	c, err := decodeToken[schemasCursor](token)
	if err == nil && c.LastName == "" {
		err = fmt.Errorf("%w: not a token this service issued", errInvalidPageToken)
	}
	return c, err
}

// encodeToken and decodeToken are a page token's wire form: JSON, base64url.
func encodeToken[T any](c T) string {
	raw, err := json.Marshal(c)
	if err != nil {
		// The cursors are a few strings and ints; a failure here is not
		// reachable, and an empty token would silently end the scan.
		panic("records: encoding a page cursor: " + err.Error())
	}
	return base64.RawURLEncoding.EncodeToString(raw)
}

func decodeToken[T any](token string) (T, error) {
	var c T
	raw, err := base64.RawURLEncoding.DecodeString(token)
	if err == nil {
		err = json.Unmarshal(raw, &c)
	}
	if err != nil {
		return c, fmt.Errorf("%w: not a token this service issued", errInvalidPageToken)
	}
	return c, nil
}

// sameTypeSet reports whether two type lists name the same set, ignoring order
// and repeats.
func sameTypeSet(a, b []string) bool {
	return slices.Equal(slices.Compact(slices.Sorted(slices.Values(a))), slices.Compact(slices.Sorted(slices.Values(b))))
}

// dedupe keeps the first occurrence of each name, in the order given. A type
// list is a set; this is the one place that fact is applied to a raw request.
func dedupe(types []string) []string {
	out := make([]string, 0, len(types))
	seen := make(map[string]bool, len(types))
	for _, name := range types {
		if seen[name] {
			continue
		}
		seen[name] = true
		out = append(out, name)
	}
	return out
}

package records

import (
	"errors"
	"fmt"

	recstore "github.com/entirehq/entire-records/store"
)

// noSchemaError names the schema a repo does not hold. Wraps ErrNoSchema so a
// caller can test for the case, and carries the address so the message can name
// what was asked for — a typo'd schema name is the likeliest way to arrive here,
// and "no such schema" without the name does not help anyone find the typo.
type noSchemaError struct{ address string }

func (e *noSchemaError) Error() string {
	return fmt.Sprintf("no records schema %q in this repository", e.address)
}
func (e *noSchemaError) Unwrap() error { return ErrNoSchema }

// unknownTypeError names a type the schema does not declare, and the schema it
// looked in — which is the fact that turns the error into an action, since the
// caller can read that schema's types from the same surface.
//
// Wraps store.ErrInvalid rather than a not-found: this is entire-records' own
// verdict on the same question, and answering it differently here would mean one
// question with two answers depending on which surface you asked.
type unknownTypeError struct{ schema, typeName string }

func (e *unknownTypeError) Error() string {
	return fmt.Sprintf("no type %q in schema %q", e.typeName, e.schema)
}
func (e *unknownTypeError) Unwrap() error { return recstore.ErrInvalid }

// ErrStoreMoved refuses a page token issued against a state the store has since
// left. Not a caller mistake — the store changed under the read — so the caller
// restarts from the first page.
var ErrStoreMoved = errors.New("records: the store moved since this read began")

