16	)
17	
18	// ChangesResult is what a store did after the state a changes token names.
19	// Patches are for records the caller holds; Records are the rest, whole.
20	type ChangesResult struct {
21		Tip     string
22		Token   string
23		Patches []RecordPatch
24		Records []recordDTO
25		Deleted []recordapi.RecordRef
26		// Reload: the change can't be told as records (new generation, schema
27		// version, expiry or erasure). The caller reads the store whole again.
28		Reload bool
29	}
30	
31	func (c ChangesResult) Empty() bool {
32		return !c.Reload && len(c.Patches)+len(c.Records)+len(c.Deleted) == 0
33	}
34	
35	// ChangesOptions narrow a changes read. No Types means every type. Records only
36	// the writer named by Except touched are left out.
37	type ChangesOptions struct {
38		Types  []string
39		Except string
40	}
41	
42	// RecordPatch is what changed in a record the caller holds. Set holds whole
43	// field values; Append holds entries pushed at a list's end, with the list's new
44	// length for the caller to check its own against. Label, ParentID and Rank are
45	// always restated.
46	type RecordPatch struct {
47		Type     string                `json:"type"`
48		ID       string                `json:"id"`
49		Label    string                `json:"label"`
50		ParentID string                `json:"parentId,omitempty"`
51		Rank     string                `json:"rank,omitempty"`
52		Set      map[string]any        `json:"set,omitempty"`
53		Append   map[string]ListAppend `json:"append,omitempty"`
54	}
55	
56	type ListAppend struct {
57		Values []string `json:"values"`
58		Length int      `json:"length"`
59	}
60	
61	// Changes reads what a store did after the state token names, as the records
62	// now stand.
63	func (r *Reader) Changes(ctx context.Context, repoID, address, token string, opts ChangesOptions) (ChangesResult, error) {
64		since, err := parseChangesTokenFor(token, repoID, address)
65		if err != nil {
66			return ChangesResult{}, err
67		}
68		o, err := r.open(ctx, repoID, address)
69		if err != nil {
70			return ChangesResult{}, err
71		}
72		defer o.Release()
73		types, err := distinctDeclaredTypes(o.schema, opts.Types)
74		if err != nil {
75			return ChangesResult{}, err
76		}
77		out := ChangesResult{Tip: o.At.Tip, Token: o.changesToken()}
78		now := o.position()
79		// Rows can only tell changes within one generation, schema version and
80		// removal set; a tick behind the token means the projection was rebuilt.
81		at := now
82		at.Tick = since.Tick
83		if at != since || since.Tick > now.Tick {
84			out.Reload = true
85			return out, nil
86		}
87		if since.Tick == now.Tick {
88			return out, nil
89		}
90		changed, err := o.ChangedSince(since.Tick)
91		if err != nil {
92			return ChangesResult{}, err
93		}
94		for _, t := range touched(changed, types, opts.Except) {
95			if err := o.report(&out, t); err != nil {
96				return ChangesResult{}, err
97			}
98		}
99		return out, nil
100	}
101	
102	type touchedRecord struct {
103		ref     recordapi.RecordRef
104		changed recordchange.Record
105	}
106	
107	// touched leaves out rows no record owns (schema storage, bookkeeping): a schema
108	// change reaches the caller as a reload instead.
109	func touched(changed []recordchange.Record, types []string, except string) []touchedRecord {
110		var out []touchedRecord
111		for _, c := range changed {
112			typeName, addr, _, ok := recstore.RecordOfOp(c.Key.Type, c.Key.ID, "")
113			if !ok || (len(types) > 0 && !slices.Contains(types, typeName)) || (except != "" && onlyBy(c, except)) {
114				continue
115			}
116			out = append(out, touchedRecord{ref: recordapi.RecordRef{Type: typeName, ID: addr.String()}, changed: c})
117		}
118		slices.SortFunc(out, func(a, b touchedRecord) int {
119			if c := strings.Compare(a.ref.Type, b.ref.Type); c != 0 {
120				return c
121			}
122			return strings.Compare(a.ref.ID, b.ref.ID)
123		})
124		return out
125	}
126	
127	func onlyBy(c recordchange.Record, writer string) bool {
128		if c.FloorWriter != "" && c.FloorWriter != writer {
129			return false
130		}
131		for _, f := range c.Fields {
132			if f.Writer != writer {
133				return false
134			}
135		}
136		return true
137	}
138	
139	// report adds a record as gone, whole, or patched. One the caller may not have
140	// held -- no visible field predates the token, or its floor rose -- goes whole.
141	func (o opened) report(out *ChangesResult, t touchedRecord) error {
142		rt, ok := o.schema.Type(t.ref.Type)
143		if !ok {
144			out.Deleted = append(out.Deleted, t.ref)
145			return nil
146		}
147		addr, err := recstore.ParseAddress(t.ref.ID)
148		if err != nil {
149			out.Deleted = append(out.Deleted, t.ref)
150			return nil
151		}
152		if t.changed.FloorWriter != "" || !t.changed.Held {
153			rec, err := o.store.GetRecord(rt, addr)
154			if errors.Is(err, recstore.ErrNotFound) {
155				out.Deleted = append(out.Deleted, t.ref)
156				return nil
157			}
158			if err != nil {
159				return err
160			}
161			out.Records = append(out.Records, recordapi.ShapeRecords(rt, []*recstore.Record{rec})[0])
162			return nil
163		}
164		fields := make([]recstore.FieldChange, len(t.changed.Fields))
165		for i, f := range t.changed.Fields {
166			fields[i] = recstore.FieldChange{Field: f.Field, Value: f.Value, Unbound: f.Deleted}
167		}
168		change, err := o.store.GetRecordChange(rt, addr, fields)
169		if errors.Is(err, recstore.ErrNotFound) {
170			out.Deleted = append(out.Deleted, t.ref)
171			return nil
172		}
173		if err != nil {
174			return err
175		}
176		out.Patches = append(out.Patches, patchOf(recordapi.ShapeRecords(rt, []*recstore.Record{change.Record})[0], change))
177		return nil
178	}
179	
180	func patchOf(dto recordDTO, change recstore.RecordChange) RecordPatch {
181		p := RecordPatch{Type: dto.Type, ID: dto.ID, Label: dto.Label, ParentID: dto.ParentID, Rank: dto.Rank}
182		for _, key := range change.Changed {
183			if values, ok := change.Appended[key]; ok {
184				if p.Append == nil {
185					p.Append = map[string]ListAppend{}
186				}
187				p.Append[key] = ListAppend{Values: values, Length: len(recordapi.MultiValueField(dto, key))}
188				continue
189			}
190			if p.Set == nil {
191				p.Set = map[string]any{}
192			}
193			p.Set[key] = dto.Fields[key]
194		}
195		return p
196	}
197	
198	// StoreOf names the strata store a schema address reads.
199	func StoreOf(address string) (string, error) {
200		ref, err := parseSchemaAddress(address)
201		if err != nil {
202			return "", err
203		}
204		return ref.Name, nil
205	}
206	
207	// changesPosition is a changes token's content. Short keys: it travels in
208	// Last-Event-ID.
209	type changesPosition struct {
210		Key        string `json:"k"`
211		Generation uint64 `json:"g"`
212		Tick       uint64 `json:"t"`
213		Schema     int    `json:"s"`
214		Removals   string `json:"r"`
215	}
216	
217	func (o opened) position() changesPosition {
218		return changesPosition{Key: o.key, Generation: o.At.Generation, Tick: o.At.Tick, Schema: o.schema.Version,
219			Removals: o.At.Removals}
220	}
221	
222	// changesKey ties a token to its store: another store's numbers could line up
223	// with this one's by chance. It guards against a mix-up, not a forgery.
224	func changesKey(repoID string, ref recstore.SchemaRef) string {
225		sum := sha256.Sum256([]byte(repoID + "\x00" + ref.String()))
226		return hex.EncodeToString(sum[:])[:10]
227	}
228	
229	func (o opened) changesToken() string { return encodeToken(o.position()) }
230	
231	const maxChangesTokenLen = 256
232	
233	// ValidChangesToken refuses a token not issued for this store.
234	func ValidChangesToken(token, repoID, address string) error {
235		_, err := parseChangesTokenFor(token, repoID, address)
236		return err
237	}
238	
239	func parseChangesTokenFor(token, repoID, address string) (changesPosition, error) {
240		p, err := parseChangesToken(token)
241		if err != nil {
242			return changesPosition{}, err
243		}
244		ref, err := parseSchemaAddress(address)
245		if err != nil {
246			return changesPosition{}, err
247		}
248		if p.Key != changesKey(repoID, ref) {
249			return changesPosition{}, fmt.Errorf("%w: changes token: issued for another repository or store", recstore.ErrInvalid)
250		}
251		return p, nil
252	}
253	
254	func parseChangesToken(token string) (changesPosition, error) {
255		if token == "" || len(token) > maxChangesTokenLen {
256			return changesPosition{}, fmt.Errorf("%w: changes token: missing or too long", recstore.ErrInvalid)
257		}
258		p, err := decodeToken[changesPosition](token)
259		if err != nil {
260			return changesPosition{}, fmt.Errorf("%w: changes token: not one this service issued", recstore.ErrInvalid)
261		}
262		return p, nil
263	}
