1	package records
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"slices"
8	
9		recstore "github.com/entirehq/entire-records/store"
10	)
11	
12	// Page bounds one page of a list read: how many records to return, and where to
13	// resume. An empty Token starts at the beginning; Size <= 0 takes the default.
14	type Page struct {
15		Size  int
16		Token string
17	}
18	
19	// Page size bounds (API standard PAGE-002).
20	const (
21		defaultPageSize = 50
22		maxPageSize     = 100
23	)
24	
25	// errInvalidPageToken means a page token is not one this service issued, or
26	// contradicts the read it claims to continue. A caller mistake, so it wraps
27	// store.ErrInvalid and maps to 400 with every other bad request.
28	var errInvalidPageToken = REDACTED invalid pageToken", recstore.ErrInvalid)
29	
30	// size clamps a caller's page size into the declared bounds.
31	func (p Page) size() int {
32		switch {
33		case p.Size <= 0:
34			return defaultPageSize
35		case p.Size > maxPageSize:
36			return maxPageSize
37		}
38		return p.Size
39	}
40	
41	// recordsCursor is where a paged records read resumes.
42	//
43	// It carries the tip it started at, which is what makes the offset below
44	// meaningful: one state of the store yields the same records in the same order
45	// every time, so "the 12th record of the 3rd type" names the same record on page
46	// 2 as it did on page 1. A continuation against a state the store has left is
47	// refused (ErrStoreMoved) rather than answered from shifted positions.
48	//
49	// The position is a type index plus an offset within that type, not a single
50	// offset across the whole read. That is what lets a continuation skip the types
51	// it has already returned instead of re-reading them to count past them — the
52	// difference between paging that costs one store read per page and paging that
53	// costs a whole store read per page.
54	type recordsCursor struct {
55		Tip   string   `json:"tip"`
56		Types []string `json:"types"`
57		// TypeIndex indexes Types; Offset counts records already returned from that
58		// type.
59		TypeIndex int `json:"typeIndex"`
60		Offset    int `json:"offset"`
61	}
62	
63	func (c recordsCursor) encode() string { return encodeToken(c) }
64	
65	// decodeRecordsCursor reads a token back, and refuses one that contradicts the
66	// read it is being used to continue.
67	//
68	// An omitted parameter inherits the token's value, which is the common case: a
69	// client that pages by following nextPageToken alone sends nothing else. A
70	// different non-empty value is a caller bug, and saying so beats answering a
71	// different question under the same cursor.
72	func decodeRecordsCursor(token string, types []string) (recordsCursor, error) {
73		c, err := decodeToken[recordsCursor](token)
74		if err != nil {
75			return recordsCursor{}, err
76		}
77		if c.Tip == "" || c.TypeIndex < 0 || c.Offset < 0 {
78			return recordsCursor{}, fmt.Errorf("%w: token names no position", errInvalidPageToken)
79		}
80		// Compared as the set it is — deduplicated and order-insensitive — because
81		// the token holds a set and the walk does not read this list at all. A
82		// continuation is driven entirely by the token's own Types, whose order the
83		// TypeIndex is relative to, so a client that lists the same types in a
84		// different order (out of a map, say) is asking the identical question and
85		// gets the identical answer. Accepting it costs nothing; refusing it fails a
86		// request that is genuinely consistent.
87		if len(types) > 0 && !sameTypeSet(types, c.Types) {
88			return recordsCursor{}, fmt.Errorf("%w: token covers types %v, request asks for %v", errInvalidPageToken, c.Types, types)
89		}
90		return c, nil
91	}
92	
93	// pageOf walks the requested types from where the cursor left off and collects
94	// at most size records, reporting where the next page resumes.
95	//
96	// read is called once per type actually needed, so a continuation deep in the
97	// last type does not read the types before it.
98	func pageOf(cursor recordsCursor, size int, read func(typeName string) ([]recordDTO, error)) ([]recordDTO, string, error) {
99		out := make([]recordDTO, 0, size)
100		for i := cursor.TypeIndex; i < len(cursor.Types); i++ {
101			records, err := read(cursor.Types[i])
102			if err != nil {
103				return nil, "", err
104			}
105			offset := 0
106			if i == cursor.TypeIndex {
107				offset = cursor.Offset
108			}
109			if offset > len(records) {
110				// Only reachable from a hand-edited token: one state of the store
111				// yields the same count every time.
112				return nil, "", fmt.Errorf("%w: token resumes past the end of %q", errInvalidPageToken, cursor.Types[i])
113			}
114			for ; offset < len(records); offset++ {
115				if len(out) == size {
116					next := recordsCursor{Tip: cursor.Tip, Types: cursor.Types, TypeIndex: i, Offset: offset}
117					return out, next.encode(), nil
118				}
119				out = append(out, records[offset])
120			}
121		}
122		return out, "", nil
123	}
124	
125	// schemasCursor is where a paged schema listing resumes.
126	//
127	// The last name rather than an offset: the listing spans every store, and a
128	// store can appear between pages. An offset would then skip or repeat one;
129	// resuming after a name cannot.
130	type schemasCursor struct {
131		LastName string `json:"lastName"`
132	}
133	
134	func (c schemasCursor) encode() string { return encodeToken(c) }
135	
136	func decodeSchemasCursor(token string) (schemasCursor, error) {
137		c, err := decodeToken[schemasCursor](token)
138		if err == nil && c.LastName == "" {
139			err = fmt.Errorf("%w: not a token this service issued", errInvalidPageToken)
140		}
141		return c, err
142	}
143	
144	// encodeToken and decodeToken are a page token's wire form: JSON, base64url.
145	func encodeToken[T any](c T) string {
146		raw, err := json.Marshal(c)
147		if err != nil {
148			// The cursors are a few strings and ints; a failure here is not
149			// reachable, and an empty token would silently end the scan.
150			panic("records: encoding a page cursor: " + err.Error())
151		}
152		return base64.RawURLEncoding.EncodeToString(raw)
153	}
154	
155	func decodeToken[T any](token string) (T, error) {
156		var c T
157		raw, err := base64.RawURLEncoding.DecodeString(token)
158		if err == nil {
159			err = json.Unmarshal(raw, &c)
160		}
161		if err != nil {
162			return c, fmt.Errorf("%w: not a token this service issued", errInvalidPageToken)
163		}
164		return c, nil
165	}
166	
167	// sameTypeSet reports whether two type lists name the same set, ignoring order
168	// and repeats.
169	func sameTypeSet(a, b []string) bool {
170		return slices.Equal(slices.Compact(slices.Sorted(slices.Values(a))), slices.Compact(slices.Sorted(slices.Values(b))))
171	}
172	
173	// dedupe keeps the first occurrence of each name, in the order given. A type
174	// list is a set; this is the one place that fact is applied to a raw request.
175	func dedupe(types []string) []string {
176		out := make([]string, 0, len(types))
177		seen := make(map[string]bool, len(types))
178		for _, name := range types {
179			if seen[name] {
180				continue
181			}
182			seen[name] = true
183			out = append(out, name)
184		}
185		return out
186	}
187

