package store

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
)

// The strata writer lease table follows trail-watch presence: a row per live
// holder, touched while it lives, judged stale by the database's clock. replica
// is there for the same reason presence keeps one — to say, after a crash, which
// process held a writer that lapsed.

// AcquireStrataLease records that replica holds writer.
func (s *RepoStore) AcquireStrataLease(ctx context.Context, repoID, store, writer, replica string) error {
	repo, err := ulidBytes(repoID)
	if err != nil {
		return err
	}
	if _, err := s.pool.Exec(ctx, `
		INSERT INTO strata_writer_leases (repo_id, store, writer, replica)
		VALUES ($1, $2, $3, $4)`, repo, store, writer, replica); err != nil {
		return fmt.Errorf("store: acquire strata lease: %w", err)
	}
	return nil
}

// RenewStrataLease moves the lease's renewal to now. False means the row is
// gone — another session judged the writer dead and evicted it.
func (s *RepoStore) RenewStrataLease(ctx context.Context, repoID, store, writer string) (bool, error) {
	repo, err := ulidBytes(repoID)
	if err != nil {
		return false, err
	}
	tag, err := s.pool.Exec(ctx, `
		UPDATE strata_writer_leases SET renewed_at = now()
		WHERE repo_id = $1 AND store = $2 AND writer = $3`, repo, store, writer)
	if err != nil {
		return false, fmt.Errorf("store: renew strata lease: %w", err)
	}
	return tag.RowsAffected() == 1, nil
}

// ReleaseStrataLeases deletes leases, for writers that ended or were evicted.
func (s *RepoStore) ReleaseStrataLeases(ctx context.Context, repoID, store string, writers []string) error {
	if len(writers) == 0 {
		return nil
	}
	repo, err := ulidBytes(repoID)
	if err != nil {
		return err
	}
	if _, err := s.pool.Exec(ctx, `
		DELETE FROM strata_writer_leases
		WHERE repo_id = $1 AND store = $2 AND writer = ANY($3)`, repo, store, writers); err != nil {
		return fmt.Errorf("store: release strata leases: %w", err)
	}
	return nil
}

// HasStrataLease reports whether writer holds a lease, lapsed or not.
func (s *RepoStore) HasStrataLease(ctx context.Context, repoID, store, writer string) (bool, error) {
	repo, err := ulidBytes(repoID)
	if err != nil {
		return false, err
	}
	var held bool
	if err := s.pool.QueryRow(ctx, `
		SELECT EXISTS (SELECT 1 FROM strata_writer_leases
		               WHERE repo_id = $1 AND store = $2 AND writer = $3)`,
		repo, store, writer).Scan(&held); err != nil {
		return false, fmt.Errorf("store: strata lease of %s: %w", writer, err)
	}
	return held, nil
}

// LapsedStrataWriters returns the store's writers whose lease has gone at least
// after without renewal.
func (s *RepoStore) LapsedStrataWriters(ctx context.Context, repoID, store string, after time.Duration) ([]string, error) {
	repo, err := ulidBytes(repoID)
	if err != nil {
		return nil, err
	}
	rows, err := s.pool.Query(ctx, `
		SELECT writer FROM strata_writer_leases
		WHERE repo_id = $1 AND store = $2
		  AND renewed_at < now() - make_interval(secs => $3)
		ORDER BY writer`, repo, store, after.Seconds())
	if err != nil {
		return nil, fmt.Errorf("store: lapsed strata writers: %w", err)
	}
	writers, err := pgx.CollectRows(rows, pgx.RowTo[string])
	if err != nil {
		return nil, fmt.Errorf("store: lapsed strata writers: %w", err)
	}
	return writers, nil
}

