20	
21	// EnableStrataWrite must be called after the content transports are set.
22	func (deps *RepoActivityDeps) EnableStrataWrite() error {
23		if deps.RepoAPIBase == "" {
24			return nil
25		}
26		origin, err := deps.gitOrigin()
27		if err != nil {
28			return fmt.Errorf("strata write: %w", err)
29		}
30		deps.StrataRepoURL = func(repoID string) string { return origin + "/git/repo/" + url.PathEscape(repoID) }
31		deps.EnableStrataSockets()
32		return nil
33	}
34	
35	// EnableStrataSockets is for a harness that sets StrataRepoURL itself.
36	func (deps *RepoActivityDeps) EnableStrataSockets() {
37		if deps.StrataSockets == nil {
38			deps.StrataSockets = newStrataSockets()
39		}
40	}
41	
42	// DrainStrataSockets ends every socket on this replica: http.Server.Shutdown
43	// doesn't wait for hijacked connections.
44	func (deps *RepoActivityDeps) DrainStrataSockets(ctx context.Context) error {
45		if deps.StrataSockets == nil {
46			return nil
47		}
48		return deps.StrataSockets.Shutdown(ctx)
49	}
