85	func registerRepoStrata(api huma.API, deps *RepoActivityDeps) {
86		// Any cell: a strata write is a git push to the repo, which may enter at any
87		// placement that holds it.
88		createGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoManageSettings(api, deps))
89		writeGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
