23	)
24	
25	// Application close codes. A client reconnects on all but closeNoStore.
26	const (
27		// closeFenced: the writer could not keep its lease. Reconnect as a new one.
28		closeFenced websocket.StatusCode = 4000
29		// closeCredential: the bearer is about to lapse. Reconnect with a fresh one.
30		closeCredential websocket.StatusCode = 4001
31		// closeSuperseded: the caller opened too many sockets; the oldest gave way.
32		closeSuperseded websocket.StatusCode = 4003
33		// closeNoStore: nobody created this store. Not worth reconnecting.
34		closeNoStore websocket.StatusCode = 4004
35	)
36	
37	const (
38		maxSocketsPerCaller = 5
39		defaultMaxSockets   = 500
40		// credentialMargin is how long before the bearer lapses the socket ends: End
41		// publishes the writer's eviction with that bearer.
42		credentialMargin = 2 * time.Minute
43		// socketUpstreamTimeout is generous: a push is answered only once entiredb
44		// has taken the whole pack.
45		socketUpstreamTimeout = time.Minute
46		// socketReadLimit matches entire-records' HTTP body limit. A fold's frame
47		// carries removed entries too, which the library's 32 KiB default refuses.
48		socketReadLimit    = 4 << 20
49		socketEndTimeout   = 15 * time.Second
50		socketWriteTimeout = 10 * time.Second
51		socketRetryAfter   = "5"
52		// maxSocketLife ends a socket's writer well before StaleBlockerAfter, so no
53		// live writer looks stale to a cell that cannot see its lease.
54		maxSocketLife = stratawrite.StaleBlockerAfter / 2
55	)
56	
57	// changesRetry is how long a socket whose changes read failed waits before
58	// reading again, doubling to changesRetryCeiling. socketReauthorize is how often
59	// an open socket re-checks its credential and push access; the credential check
60	// reads a liveness answer up to a minute old, so a revoked session can keep
61	// writing for up to two minutes plus one Core lookup.
62	const (
63		changesRetry        = time.Second
64		changesRetryCeiling = 30 * time.Second
65		socketReauthorize   = time.Minute
66	)
67	
68	type closeError struct {
69		code   websocket.StatusCode
70		reason string
71	}
72	
73	var (
74		errClosedNormally    = &closeError{code: websocket.StatusNormalClosure}
75		errGoneAway          = &closeError{code: websocket.StatusGoingAway}
76		errFenced            = &closeError{code: closeFenced, reason: "lease lost; reconnect"}
77		errCredential        = &closeError{code: closeCredential, reason: "credential no longer valid"}
78		errExpiring          = &closeError{code: closeCredential, reason: "credential expiring; reconnect with a fresh one"}
79		errMaxLife           = &closeError{code: closeCredential, reason: "socket reached its maximum life; reconnect"}
80		errRevoked           = &closeError{code: websocket.StatusPolicyViolation, reason: "push access revoked"}
81		errUnconfirmedAccess = &closeError{code: websocket.StatusTryAgainLater, reason: "push access could not be confirmed; reconnect"}
82	)
83	
84	// strataSockets is this replica's live sockets, for the limits and for shutdown:
85	// http.Server.Shutdown does not wait for a hijacked connection.
86	type strataSockets struct {
87		replica         string
88		max             int
89		endTimeout      time.Duration
90		upstreamTimeout time.Duration
91		// Per registry, not package vars, so a test can shrink them without racing
92		// a socket loop that outlives the test's own cleanup.
93		changesRetry        time.Duration
94		changesRetryCeiling time.Duration
95		socketReauthorize   time.Duration
96	
97		mu       sync.Mutex
98		sessions map[socketKey][]*socketSession
99		total    int
100		stopping bool
101		live     sync.WaitGroup
102	}
103	
104	type socketKey struct{ caller, repo, store string }
105	
106	type socketSession struct {
107		key        socketKey
108		stop       chan websocket.StatusCode // buffered(1): the first reason to end wins
109		ending     chan struct{}
110		once       sync.Once
111		superseded bool
112	}
113	
114	func (s *socketSession) end(code websocket.StatusCode) {
115		s.once.Do(func() {
116			s.stop <- code
117			close(s.ending)
118		})
119	}
120	
121	func newStrataSockets() *strataSockets {
122		replica, _ := os.Hostname()
123		return &strataSockets{replica: replica, max: defaultMaxSockets, endTimeout: socketEndTimeout, upstreamTimeout: socketUpstreamTimeout,
124			changesRetry: changesRetry, changesRetryCeiling: changesRetryCeiling, socketReauthorize: socketReauthorize, sessions: map[socketKey][]*socketSession{}}
125	}
126	
127	// admit counts a socket in, asking the caller's oldest to give way past the
128	// per-caller limit.
129	func (r *strataSockets) admit(key socketKey) (*socketSession, error) {
130		r.mu.Lock()
131		defer r.mu.Unlock()
132		if r.stopping || r.total >= r.max {
133			return nil, socketUnavailable("this replica is not taking write sockets; retry")
134		}
135		s := &socketSession{key: key, stop: make(chan websocket.StatusCode, 1), ending: make(chan struct{})}
136		r.sessions[key] = append(r.sessions[key], s)
137		r.total++
138		r.live.Add(1)
139		staying := 0
140		for _, other := range r.sessions[key] {
141			if !other.superseded {
142				staying++
143			}
144		}
145		for _, other := range r.sessions[key] {
146			if staying <= maxSocketsPerCaller {
147				break
148			}
149			if !other.superseded {
150				other.superseded = true
151				other.end(closeSuperseded)
152				staying--
153			}
154		}
155		return s, nil
156	}
157	
158	func (r *strataSockets) release(s *socketSession) {
159		r.mu.Lock()
160		defer r.mu.Unlock()
161		mine := r.sessions[s.key]
162		for i, other := range mine {
163			if other == s {
164				r.sessions[s.key] = append(mine[:i], mine[i+1:]...)
165				r.total--
166				break
167			}
168		}
169		if len(r.sessions[s.key]) == 0 {
170			delete(r.sessions, s.key)
171		}
172		r.live.Done()
173	}
174	
175	func (r *strataSockets) Shutdown(ctx context.Context) error {
176		r.mu.Lock()
177		r.stopping = true
178		for _, mine := range r.sessions {
179			for _, s := range mine {
180				s.end(websocket.StatusServiceRestart)
181			}
182		}
183		r.mu.Unlock()
184		done := make(chan struct{})
185		go func() { r.live.Wait(); close(done) }()
186		select {
187		case <-done:
188			return nil
189		case <-ctx.Done():
190			return ctx.Err()
191		}
192	}
193	
194	func socketUnavailable(msg string) error {
195		return huma.ErrorWithHeaders(huma.Error503ServiceUnavailable(msg), http.Header{"Retry-After": {socketRetryAfter}})
196	}
197	
198	type RepoStrataSocketInput struct {
199		RepoID       string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
200		Store        string `path:"store" doc:"Store (schema) name"`
201		ChangesToken string `query:"changes_token" doc:"The changesToken of the records read the editor's page made: the socket tells it what other writers change after that state. Without it the socket reports no changes."`
202	}
203	
204	type socketFrame struct {
205		Op     string           `json:"op"`
206		Seq    int64            `json:"seq"`
207		Batch  *recordapi.Batch `json:"batch,omitempty"`
208		Type   string           `json:"type,omitempty"`
209		ID     string           `json:"id,omitempty"`
210		Field  string           `json:"field,omitempty"`
211		Value  string           `json:"value,omitempty"`
212		Remove []string         `json:"remove,omitempty"`
213		recordapi.ReorderRequest
214	}
215	
216	type socketMessage struct {
217		Type    string                `json:"type"`
218		Writer  string                `json:"writer,omitempty"`
219		Seq     *int64                `json:"seq,omitempty"`
220		Written []recordapi.RecordRef `json:"written,omitempty"`
221		Error   string                `json:"error,omitempty"`
222		Status  int                   `json:"status,omitempty"`
223		Patches []records.RecordPatch `json:"patches,omitempty"`
224		Records []recordapi.RecordDTO `json:"records,omitempty"`
225		Deleted []recordapi.RecordRef `json:"deleted,omitempty"`
226	}
227	
228	func registerStrataSocket(api huma.API, deps *RepoActivityDeps) {
229		gate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
230		op := teamOp(api, "repoStrataSocket", http.MethodGet, "/repos/{repo_id}/strata/{store}/sockets",
231			"Hold a write socket on a strata record store", "strata", gate)
232		op.Errors = withExtraErrors(op.Errors, http.StatusNotFound, http.StatusServiceUnavailable)
233		huma.Register(api, op, func(ctx context.Context, in *RepoStrataSocketInput) (*huma.StreamResponse, error) {
234			if deps.StrataRepoURL == nil || deps.StrataSockets == nil {
235				return nil, huma.Error404NotFound("strata writes need an entiredb upstream")
236			}
237			if deps.RefEventsNATS == nil {
238				return nil, huma.Error503ServiceUnavailable("live ref events are not configured")
239			}
240			// Catches a session logged out since its JWT was minted.
241			if err := deps.StreamCredentials.Check(ctx); err != nil {
242				return nil, huma.Error401Unauthorized("the bearer is no longer valid")
243			}
244			id := auth.FromContext(ctx)
245			deadline := id.BearerExpiry()
246			if time.Until(deadline) < 2*credentialMargin {
247				return nil, huma.Error401Unauthorized("the bearer expires too soon to hold a write socket; refresh it and reconnect")
248			}
249			caller, ok := id.Subject.AccountID()
250			if !ok {
251				caller = id.Subject.String()
252			}
253			if in.ChangesToken != "" {
254				if _, err := recordsReader(deps); err != nil {
255					return nil, err
256				}
257				if err := records.ValidChangesToken(in.ChangesToken, in.RepoID, in.Store); err != nil {
258					return nil, recordsHTTPError(err)
259				}
260			}
261			session, err := deps.StrataSockets.admit(socketKey{caller: caller, repo: in.RepoID, store: in.Store})
262			if err != nil {
263				return nil, err
264			}
265			return &huma.StreamResponse{Body: func(hctx huma.Context) {
266				defer deps.StrataSockets.release(session)
267				w, ok := hctx.BodyWriter().(http.ResponseWriter)
268				if !ok {
269					hctx.SetStatus(http.StatusInternalServerError)
270					return
271				}
272				// Origin is not checked: the bearer on the upgrade authorizes the
273				// socket, never an ambient cookie a cross-origin page could borrow.
274				conn, err := websocket.Accept(w, upgradeRequest(hctx), &websocket.AcceptOptions{InsecureSkipVerify: true})
275				if err != nil {
276					slog.WarnContext(hctx.Context(), "strata socket: accepting the upgrade failed", slog.Any("error", err))
277					return
278				}
279				conn.SetReadLimit(socketReadLimit)
280				serveStrataSocket(context.WithoutCancel(hctx.Context()), deps, conn, session, deadline, in.RepoID, in.Store, in.ChangesToken)
281			}}, nil
282		})
283	}
284	
285	func serveStrataSocket(ctx context.Context, deps *RepoActivityDeps, conn *websocket.Conn, session *socketSession, deadline time.Time, repoID, store, changesToken string) {
286		ctx, cancel := context.WithCancel(ctx)
287		defer cancel()
288		remote := stratawrite.Remote{
289			URL: deps.StrataRepoURL(repoID),
290			// Only the wait for headers is bounded: a pack download grows with the
291			// store.
292			Client: &http.Client{Transport: headerTimeoutTransport{timeout: deps.StrataSockets.upstreamTimeout, base: contentRoundTripper(ctx, deps)}},
293		}
294		writer, err := stratawrite.Start(ctx, remote, deps.Store, repoID, store, deps.StrataSockets.replica,
295			strataAuthor(ctx), stratawrite.DefaultEvictAfter)
296		if errors.Is(err, recstore.ErrNoSchema) {
297			_ = conn.Close(closeNoStore, "no such store")
298			return
299		}
300		if err != nil {
301			slog.WarnContext(ctx, "strata socket: starting a writer", slog.String("store", store), slog.Any("error", err))
302			_ = conn.Close(websocket.StatusInternalError, "could not start a writer")
303			return
304		}
305		s := &socketLoop{ctx: ctx, conn: conn, writer: writer, deps: deps, repoID: repoID, store: store, token: changesToken}
306		closing := s.run(session, deadline)
307		endCtx, stop := context.WithTimeout(context.WithoutCancel(ctx), deps.StrataSockets.endTimeout)
308		defer stop()
309		if err := writer.End(endCtx); err != nil {
310			slog.WarnContext(ctx, "strata socket: ending a writer", slog.String("writer", writer.ID()), slog.Any("error", err))
311		}
312		_ = conn.Close(closing.code, closing.reason)
313	}
314	
315	type socketLoop struct {
316		ctx    context.Context
317		conn   *websocket.Conn
318		writer *stratawrite.Writer
319		deps   *RepoActivityDeps
320		repoID string
321		store  string
322		// token is empty when the page passed no changes_token: the socket then reports no changes.
323		token string
324		// held are answers to frames applied but not yet pushed: they follow the push that covers them.
325		held []socketMessage
326	}
327	
328	func (s *socketLoop) send(m socketMessage) error {
329		ctx, cancel := context.WithTimeout(s.ctx, socketWriteTimeout)
330		defer cancel()
331		return wsjson.Write(ctx, s.conn, m)
332	}
333	
334	// run is the connection's loop, and the one goroutine that calls the writer
335	// (cutWhenStuck's Abort aside). It returns how to close.
336	func (s *socketLoop) run(session *socketSession, deadline time.Time) *closeError {
337		deps := s.deps
338		// Subscribed before ready, so no later write by another writer is missed.
339		hubs := deps.refEventHubs()
340		hub, err := hubs.acquire(s.repoID)
341		if err != nil {
342			slog.WarnContext(s.ctx, "strata socket: ref events", slog.Any("error", err))
343			return &closeError{code: websocket.StatusTryAgainLater, reason: "live ref events unavailable"}
344		}
345		defer hubs.release(hub)
346		doorbell := hub.addDoorbell([]string{reflayout.For(s.store).Root().Prefix() + "/"})
347		defer hub.remove(doorbell)
348	
349		if err := s.send(socketMessage{Type: "ready", Writer: s.writer.ID()}); err != nil {
350			return errGoneAway
351		}
352		// Tell what landed since the page's read at once, not on the next ring.
353		if s.token != "" {
354			doorbell.signal()
355		}
356	
357		frames := make(chan socketFrame, 64)
358		gone := make(chan struct{}) // the client is: its connection no longer reads
359		go func() {
360			defer close(frames)
361			defer close(gone)
362			for {
363				var f socketFrame
364				if err := wsjson.Read(s.ctx, s.conn, &f); err != nil {
365					return
366				}
367				select {
368				case frames <- f:
369				case <-s.ctx.Done():
370					return
371				}
372			}
373		}()
374	
375		tick := time.NewTicker(stratawrite.DefaultEvictAfter / 4)
376		defer tick.Stop()
377		backoff := s.deps.StrataSockets.changesRetry
378		var retry *time.Timer
379		defer func() {
380			if retry != nil {
381				retry.Stop()
382			}
383		}()
384		reauthorize := time.NewTicker(s.deps.StrataSockets.socketReauthorize)
385		defer reauthorize.Stop()
386		expiring := time.NewTimer(time.Until(deadline) - credentialMargin)
387		defer expiring.Stop()
388		lifetime := time.NewTimer(maxSocketLife)
389		defer lifetime.Stop()
390		looping := make(chan struct{})
391		defer close(looping)
392		go s.cutWhenStuck(s.writer.ID(), session.ending, gone, time.Until(deadline)-credentialMargin, deps.StrataSockets.endTimeout, looping)
393	
394		for {
395			select {
396			case f, ok := <-frames:
397				if !ok {
398					return errClosedNormally
399				}
400				if closing := s.handle(f, frames); closing != nil {
401					return closing
402				}
403			case <-doorbell.wake:
404				rang := doorbell.drain()
405				if s.token == "" || onlyOwnLog(rang, s.writer.ID()) {
406					continue
407				}
408				if err := s.changes(rang); err != nil {
409					slog.WarnContext(s.ctx, "strata socket: reading changes", slog.Any("error", err))
410					// The token did not move, so nothing is lost; but nothing else may ring.
411					if retry != nil {
412						retry.Stop()
413					}
414					retry = time.AfterFunc(backoff, doorbell.signal)
415					backoff = min(backoff*2, s.deps.StrataSockets.changesRetryCeiling)
416					continue
417				}
418				backoff = s.deps.StrataSockets.changesRetry
419			case <-tick.C:
420				if err := s.writer.Tick(s.ctx); errors.Is(err, stratawrite.ErrFenced) {
421					return errFenced
422				} else if err != nil {
423					slog.WarnContext(s.ctx, "strata socket: tick", slog.Any("error", err))
424				}
425			case <-reauthorize.C:
426				if err := deps.StreamCredentials.Check(s.ctx); err != nil {
427					return errCredential
428				}
429				ok, err := repoPermissionAllowed(s.ctx, deps, s.repoID, permRepoWrite)
430				if err != nil {
431					return errUnconfirmedAccess
432				}
433				if !ok {
434					return errRevoked
435				}
436			case <-expiring.C:
437				return errExpiring
438			case <-lifetime.C:
439				return errMaxLife
440			case <-s.writer.Fenced():
441				return errFenced
442			case code := <-session.stop:
443				return &closeError{code: code, reason: "closing"}
444			}
445		}
446	}
447	
448	// cutWhenStuck cuts the writer's transport when the socket has had to end for
449	// grace and its loop hasn't: an operation stalled mid-body on git would hold it
450	// past shutdown, a disconnect or the bearer lapsing. End can then publish
451	// nothing, so the lease lapses and the next session evicts the writer.
452	func (s *socketLoop) cutWhenStuck(writer string, ending, gone <-chan struct{}, expiring, grace time.Duration, looping <-chan struct{}) {
453		expired := time.NewTimer(expiring)
454		defer expired.Stop()
455		select {
456		case <-ending:
457		case <-gone:
458		case <-expired.C:
459		case <-looping:
460			return
461		}
462		cut := time.NewTimer(grace)
463		defer cut.Stop()
464		select {
465		case <-cut.C:
466			select {
467			case <-looping:
468				return
469			default:
470			}
471			slog.WarnContext(s.ctx, "strata socket: the writer outlived its socket; cutting its transport",
472				slog.String("writer", writer))
473			s.writer.Abort()
474		case <-looping:
475		}
476	}
477	
478	// onlyOwnLog: a ring that moved only this writer's log is its own write coming
479	// back. A ring naming no refs (the hub's NATS reconnect) is not.
480	func onlyOwnLog(rang map[string]ingest.RefEvent, writer string) bool {
481		if len(rang) == 0 {
482			return false
483		}
484		for name := range rang {
485			r := reflayout.Parse(name)
486			if r.Kind != reflayout.LogRotation || r.Writer != writer {
487				return false
488			}
489		}
490		return true
491	}
492	
493	// changes reports other writers' changes, as the records changes stream does.
494	func (s *socketLoop) changes(rang map[string]ingest.RefEvent) error {
495		res, err := s.deps.RecordsReader.Changes(s.ctx, s.repoID, s.store, s.token, records.ChangesOptions{Except: s.writer.ID()})
496		if err != nil {
497			return err
498		}
499		recordRingLag(s.ctx, "socket", rang, res)
500		s.token = REDACTED
501		switch {
502		case res.Reload:
503			return s.send(socketMessage{Type: "reload"})
504		case !res.Empty():
505			return s.send(socketMessage{Type: "changed", Patches: res.Patches, Records: res.Records, Deleted: res.Deleted})
506		}
507		return nil
508	}
509	
510	// maxFramesPerPush bounds how long a burst can hold back its acks.
511	const maxFramesPerPush = 64
512	
513	// handle applies a frame and the frames already queued behind it, then
514	// publishes them in one push: each push is a round trip to the store's remote.
515	func (s *socketLoop) handle(f socketFrame, queued <-chan socketFrame) *closeError {
516		frames := []socketFrame{f}
517	drain:
518		for len(frames) < maxFramesPerPush {
519			select {
520			case next, ok := <-queued:
521				if !ok {
522					break drain
523				}
524				frames = append(frames, next)
525			default:
526				break drain
527			}
528		}
529		for len(frames) > 0 {
530			n := 1
531			var closing *closeError
532			if frames[0].Op == "write" {
533				for n < len(frames) && frames[n].Op == "write" {
534					n++
535				}
536				closing = s.applyWrites(frames[:n])
537			} else {
538				closing = s.apply(frames[0])
539			}
540			if closing != nil {
541				return closing
542			}
543			frames = frames[n:]
544		}
545		s.writer.Publish(s.ctx)
546		for _, m := range s.held {
547			if err := s.send(m); err != nil {
548				return errGoneAway
549			}
550		}
551		clear(s.held)
552		s.held = s.held[:0]
553		return nil
554	}
555	
556	func (s *socketLoop) apply(f socketFrame) *closeError {
557		var err error
558		switch f.Op {
559		case "reorder":
560			err = s.writer.Reorder(s.ctx, f.Type, f.ReorderRequest)
561		case "push":
562			err = s.writer.Push(s.ctx, f.Type, f.ID, f.Field, f.Value)
563		case "fold":
564			err = s.writer.Fold(s.ctx, f.Type, f.ID, f.Field, f.Remove, f.Value)
565		default:
566			err = huma.Error400BadRequest("unknown op " + f.Op)
567		}
568		return s.answer(f.Seq, nil, err)
569	}
570	
571	// applyWrites lands write frames in as few commits as their order allows. A
572	// commit lands deletes after all its writes, so frames combine only up to and
573	// including one that deletes.
574	func (s *socketLoop) applyWrites(writes []socketFrame) *closeError {
575		valid := writes[:0:0]
576		for _, f := range writes {
577			if f.Batch == nil {
578				s.hold(f.Seq, nil, huma.Error400BadRequest("write without a batch"))
579				continue
580			}
581			valid = append(valid, f)
582		}
583		for len(valid) > 0 {
584			n := 1
585			for n < len(valid) && len(valid[n-1].Batch.Deletes) == 0 {
586				n++
587			}
588			if closing := s.applyCombined(valid[:n]); closing != nil {
589				return closing
590			}
591			valid = valid[n:]
592		}
593		return nil
594	}
595	
596	// applyCombined lands frames as one commit, or each alone if that is refused.
597	func (s *socketLoop) applyCombined(valid []socketFrame) *closeError {
598		if len(valid) > 1 {
599			var combined recordapi.Batch
600			for _, f := range valid {
601				combined.Writes = append(combined.Writes, f.Batch.Writes...)
602				combined.Deletes = append(combined.Deletes, f.Batch.Deletes...)
603			}
604			written, err := s.writer.Apply(s.ctx, combined)
605			if errors.Is(err, stratawrite.ErrFenced) {
606				return errFenced
607			}
608			if err == nil && len(written) != len(combined.Writes) {
609				// Committed, but which refs belong to which frame is lost, so the
610				// client re-reads.
611				slog.WarnContext(s.ctx, "strata socket: a combined write answered with an unexpected number of refs",
612					slog.Int("writes", len(combined.Writes)), slog.Int("written", len(written)))
613				for _, f := range valid {
614					s.hold(f.Seq, nil, nil)
615				}
616				s.held = append(s.held, socketMessage{Type: "reload"})
617				return nil
618			}
619			if err == nil {
620				for _, f := range valid {
621					n := len(f.Batch.Writes)
622					s.hold(f.Seq, written[:n], nil)
623					written = written[n:]
624				}
625				return nil
626			}
627		}
628		for _, f := range valid {
629			written, err := s.writer.Apply(s.ctx, *f.Batch)
630			if closing := s.answer(f.Seq, written, err); closing != nil {
631				return closing
632			}
633		}
634		return nil
635	}
636	
637	func (s *socketLoop) answer(seq int64, written []recordapi.RecordRef, err error) *closeError {
638		if errors.Is(err, stratawrite.ErrFenced) {
639			return errFenced
640		}
641		s.hold(seq, written, err)
642		return nil
643	}
644	
645	func (s *socketLoop) hold(seq int64, written []recordapi.RecordRef, err error) {
646		m := socketMessage{Type: "ack", Seq: &seq, Written: written}
647		if err != nil {
648			m = s.reject(seq, err)
649		}
650		s.held = append(s.held, m)
651	}
652	
653	// reject names a server-side failure only by its status, as the HTTP routes
654	// redact one, and logs it.
655	func (s *socketLoop) reject(seq int64, err error) socketMessage {
656		status := socketStatus(err)
657		msg := err.Error()
658		if status >= http.StatusInternalServerError {
659			slog.ErrorContext(s.ctx, "strata socket: frame failed", slog.Int("status", status), slog.Any("error", err))
660			msg = http.StatusText(status)
661		}
662		return socketMessage{Type: "reject", Seq: &seq, Error: msg, Status: status}
663	}
664	
665	func socketStatus(err error) int {
666		var se huma.StatusError
667		if !errors.As(err, &se) {
668			errors.As(recordsVerdict(err, "strata write failed"), &se)
669		}
670		return se.GetStatus()
671	}
672	
673	// upgradeRequest rebuilds the method, host and headers a WebSocket upgrade
674	// reads, since this huma version doesn't expose the *http.Request.
675	func upgradeRequest(hctx huma.Context) *http.Request {
676		r := &http.Request{Method: hctx.Method(), Host: hctx.Host(), Header: http.Header{}, ProtoMajor: 1, ProtoMinor: 1}
677		hctx.EachHeader(func(name, value string) { r.Header.Add(name, value) })
678		u := hctx.URL()
679		r.URL = &u
680		return r.WithContext(hctx.Context())
681	}
682

