package httpapi

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/coder/websocket"
	"github.com/coder/websocket/wsjson"
	"github.com/danielgtaylor/huma/v2"
	"github.com/entirehq/entire-records/recordapi"
	recstore "github.com/entirehq/entire-records/store"
	"github.com/entirehq/strata/reflayout"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/ingest"
	"github.com/entirehq/entire-api/internal/records"
	"github.com/entirehq/entire-api/internal/stratawrite"
)

// Application close codes. A client reconnects on all but closeNoStore.
const (
	// closeFenced: the writer could not keep its lease. Reconnect as a new one.
	closeFenced websocket.StatusCode = 4000
	// closeCredential: the bearer is about to lapse. Reconnect with a fresh one.
	closeCredential websocket.StatusCode = 4001
	// closeSuperseded: the caller opened too many sockets; the oldest gave way.
	closeSuperseded websocket.StatusCode = 4003
	// closeNoStore: nobody created this store. Not worth reconnecting.
	closeNoStore websocket.StatusCode = 4004
)

const (
	maxSocketsPerCaller = 5
	defaultMaxSockets   = 500
	// credentialMargin is how long before the bearer lapses the socket ends: End
	// publishes the writer's eviction with that bearer.
	credentialMargin = 2 * time.Minute
	// socketUpstreamTimeout is generous: a push is answered only once entiredb
	// has taken the whole pack.
	socketUpstreamTimeout = time.Minute
	// socketReadLimit matches entire-records' HTTP body limit. A fold's frame
	// carries removed entries too, which the library's 32 KiB default refuses.
	socketReadLimit    = 4 << 20
	socketEndTimeout   = 15 * time.Second
	socketWriteTimeout = 10 * time.Second
	socketRetryAfter   = "5"
	// maxSocketLife ends a socket's writer well before StaleBlockerAfter, so no
	// live writer looks stale to a cell that cannot see its lease.
	maxSocketLife = stratawrite.StaleBlockerAfter / 2
)

// changesRetry is how long a socket whose changes read failed waits before
// reading again, doubling to changesRetryCeiling. socketReauthorize is how often
// an open socket re-checks its credential and push access; the credential check
// reads a liveness answer up to a minute old, so a revoked session can keep
// writing for up to two minutes plus one Core lookup.
const (
	changesRetry        = time.Second
	changesRetryCeiling = 30 * time.Second
	socketReauthorize   = time.Minute
)

type closeError struct {
	code   websocket.StatusCode
	reason string
}

var (
	errClosedNormally    = &closeError{code: websocket.StatusNormalClosure}
	errGoneAway          = &closeError{code: websocket.StatusGoingAway}
	errFenced            = &closeError{code: closeFenced, reason: "lease lost; reconnect"}
	errCredential        = &closeError{code: closeCredential, reason: "credential no longer valid"}
	errExpiring          = &closeError{code: closeCredential, reason: "credential expiring; reconnect with a fresh one"}
	errMaxLife           = &closeError{code: closeCredential, reason: "socket reached its maximum life; reconnect"}
	errRevoked           = &closeError{code: websocket.StatusPolicyViolation, reason: "push access revoked"}
	errUnconfirmedAccess = &closeError{code: websocket.StatusTryAgainLater, reason: "push access could not be confirmed; reconnect"}
)

// strataSockets is this replica's live sockets, for the limits and for shutdown:
// http.Server.Shutdown does not wait for a hijacked connection.
type strataSockets struct {
	replica         string
	max             int
	endTimeout      time.Duration
	upstreamTimeout time.Duration
	// Per registry, not package vars, so a test can shrink them without racing
	// a socket loop that outlives the test's own cleanup.
	changesRetry        time.Duration
	changesRetryCeiling time.Duration
	socketReauthorize   time.Duration

	mu       sync.Mutex
	sessions map[socketKey][]*socketSession
	total    int
	stopping bool
	live     sync.WaitGroup
}

type socketKey struct{ caller, repo, store string }

type socketSession struct {
	key        socketKey
	stop       chan websocket.StatusCode // buffered(1): the first reason to end wins
	ending     chan struct{}
	once       sync.Once
	superseded bool
}

func (s *socketSession) end(code websocket.StatusCode) {
	s.once.Do(func() {
		s.stop <- code
		close(s.ending)
	})
}

func newStrataSockets() *strataSockets {
	replica, _ := os.Hostname()
	return &strataSockets{replica: replica, max: defaultMaxSockets, endTimeout: socketEndTimeout, upstreamTimeout: socketUpstreamTimeout,
		changesRetry: changesRetry, changesRetryCeiling: changesRetryCeiling, socketReauthorize: socketReauthorize, sessions: map[socketKey][]*socketSession{}}
}

// admit counts a socket in, asking the caller's oldest to give way past the
// per-caller limit.
func (r *strataSockets) admit(key socketKey) (*socketSession, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.stopping || r.total >= r.max {
		return nil, socketUnavailable("this replica is not taking write sockets; retry")
	}
	s := &socketSession{key: key, stop: make(chan websocket.StatusCode, 1), ending: make(chan struct{})}
	r.sessions[key] = append(r.sessions[key], s)
	r.total++
	r.live.Add(1)
	staying := 0
	for _, other := range r.sessions[key] {
		if !other.superseded {
			staying++
		}
	}
	for _, other := range r.sessions[key] {
		if staying <= maxSocketsPerCaller {
			break
		}
		if !other.superseded {
			other.superseded = true
			other.end(closeSuperseded)
			staying--
		}
	}
	return s, nil
}

func (r *strataSockets) release(s *socketSession) {
	r.mu.Lock()
	defer r.mu.Unlock()
	mine := r.sessions[s.key]
	for i, other := range mine {
		if other == s {
			r.sessions[s.key] = append(mine[:i], mine[i+1:]...)
			r.total--
			break
		}
	}
	if len(r.sessions[s.key]) == 0 {
		delete(r.sessions, s.key)
	}
	r.live.Done()
}

func (r *strataSockets) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	r.stopping = true
	for _, mine := range r.sessions {
		for _, s := range mine {
			s.end(websocket.StatusServiceRestart)
		}
	}
	r.mu.Unlock()
	done := make(chan struct{})
	go func() { r.live.Wait(); close(done) }()
	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func socketUnavailable(msg string) error {
	return huma.ErrorWithHeaders(huma.Error503ServiceUnavailable(msg), http.Header{"Retry-After": {socketRetryAfter}})
}

type RepoStrataSocketInput struct {
	RepoID       string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Store        string `path:"store" doc:"Store (schema) name"`
	ChangesToken string `query:"changes_token" doc:"The changesToken of the records read the editor's page made: the socket tells it what other writers change after that state. Without it the socket reports no changes."`
}

type socketFrame struct {
	Op     string           `json:"op"`
	Seq    int64            `json:"seq"`
	Batch  *recordapi.Batch `json:"batch,omitempty"`
	Type   string           `json:"type,omitempty"`
	ID     string           `json:"id,omitempty"`
	Field  string           `json:"field,omitempty"`
	Value  string           `json:"value,omitempty"`
	Remove []string         `json:"remove,omitempty"`
	recordapi.ReorderRequest
}

type socketMessage struct {
	Type    string                `json:"type"`
	Writer  string                `json:"writer,omitempty"`
	Seq     *int64                `json:"seq,omitempty"`
	Written []recordapi.RecordRef `json:"written,omitempty"`
	Error   string                `json:"error,omitempty"`
	Status  int                   `json:"status,omitempty"`
	Patches []records.RecordPatch `json:"patches,omitempty"`
	Records []recordapi.RecordDTO `json:"records,omitempty"`
	Deleted []recordapi.RecordRef `json:"deleted,omitempty"`
}

func registerStrataSocket(api huma.API, deps *RepoActivityDeps) {
	gate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
	op := teamOp(api, "repoStrataSocket", http.MethodGet, "/repos/{repo_id}/strata/{store}/sockets",
		"Hold a write socket on a strata record store", "strata", gate)
	op.Errors = withExtraErrors(op.Errors, http.StatusNotFound, http.StatusServiceUnavailable)
	huma.Register(api, op, func(ctx context.Context, in *RepoStrataSocketInput) (*huma.StreamResponse, error) {
		if deps.StrataRepoURL == nil || deps.StrataSockets == nil {
			return nil, huma.Error404NotFound("strata writes need an entiredb upstream")
		}
		if deps.RefEventsNATS == nil {
			return nil, huma.Error503ServiceUnavailable("live ref events are not configured")
		}
		// Catches a session logged out since its JWT was minted.
		if err := deps.StreamCredentials.Check(ctx); err != nil {
			return nil, huma.Error401Unauthorized("the bearer is no longer valid")
		}
		id := auth.FromContext(ctx)
		deadline := id.BearerExpiry()
		if time.Until(deadline) < 2*credentialMargin {
			return nil, huma.Error401Unauthorized("the bearer expires too soon to hold a write socket; refresh it and reconnect")
		}
		caller, ok := id.Subject.AccountID()
		if !ok {
			caller = id.Subject.String()
		}
		if in.ChangesToken != "" {
			if _, err := recordsReader(deps); err != nil {
				return nil, err
			}
			if err := records.ValidChangesToken(in.ChangesToken, in.RepoID, in.Store); err != nil {
				return nil, recordsHTTPError(err)
			}
		}
		session, err := deps.StrataSockets.admit(socketKey{caller: caller, repo: in.RepoID, store: in.Store})
		if err != nil {
			return nil, err
		}
		return &huma.StreamResponse{Body: func(hctx huma.Context) {
			defer deps.StrataSockets.release(session)
			w, ok := hctx.BodyWriter().(http.ResponseWriter)
			if !ok {
				hctx.SetStatus(http.StatusInternalServerError)
				return
			}
			// Origin is not checked: the bearer on the upgrade authorizes the
			// socket, never an ambient cookie a cross-origin page could borrow.
			conn, err := websocket.Accept(w, upgradeRequest(hctx), &websocket.AcceptOptions{InsecureSkipVerify: true})
			if err != nil {
				slog.WarnContext(hctx.Context(), "strata socket: accepting the upgrade failed", slog.Any("error", err))
				return
			}
			conn.SetReadLimit(socketReadLimit)
			serveStrataSocket(context.WithoutCancel(hctx.Context()), deps, conn, session, deadline, in.RepoID, in.Store, in.ChangesToken)
		}}, nil
	})
}

func serveStrataSocket(ctx context.Context, deps *RepoActivityDeps, conn *websocket.Conn, session *socketSession, deadline time.Time, repoID, store, changesToken string) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	remote := stratawrite.Remote{
		URL: deps.StrataRepoURL(repoID),
		// Only the wait for headers is bounded: a pack download grows with the
		// store.
		Client: &http.Client{Transport: headerTimeoutTransport{timeout: deps.StrataSockets.upstreamTimeout, base: contentRoundTripper(ctx, deps)}},
	}
	writer, err := stratawrite.Start(ctx, remote, deps.Store, repoID, store, deps.StrataSockets.replica,
		strataAuthor(ctx), stratawrite.DefaultEvictAfter)
	if errors.Is(err, recstore.ErrNoSchema) {
		_ = conn.Close(closeNoStore, "no such store")
		return
	}
	if err != nil {
		slog.WarnContext(ctx, "strata socket: starting a writer", slog.String("store", store), slog.Any("error", err))
		_ = conn.Close(websocket.StatusInternalError, "could not start a writer")
		return
	}
	s := &socketLoop{ctx: ctx, conn: conn, writer: writer, deps: deps, repoID: repoID, store: store, token: changesToken}
	closing := s.run(session, deadline)
	endCtx, stop := context.WithTimeout(context.WithoutCancel(ctx), deps.StrataSockets.endTimeout)
	defer stop()
	if err := writer.End(endCtx); err != nil {
		slog.WarnContext(ctx, "strata socket: ending a writer", slog.String("writer", writer.ID()), slog.Any("error", err))
	}
	_ = conn.Close(closing.code, closing.reason)
}

type socketLoop struct {
	ctx    context.Context
	conn   *websocket.Conn
	writer *stratawrite.Writer
	deps   *RepoActivityDeps
	repoID string
	store  string
	// token is empty when the page passed no changes_token: the socket then reports no changes.
	token string
	// held are answers to frames applied but not yet pushed: they follow the push that covers them.
	held []socketMessage
}

func (s *socketLoop) send(m socketMessage) error {
	ctx, cancel := context.WithTimeout(s.ctx, socketWriteTimeout)
	defer cancel()
	return wsjson.Write(ctx, s.conn, m)
}

// run is the connection's loop, and the one goroutine that calls the writer
// (cutWhenStuck's Abort aside). It returns how to close.
func (s *socketLoop) run(session *socketSession, deadline time.Time) *closeError {
	deps := s.deps
	// Subscribed before ready, so no later write by another writer is missed.
	hubs := deps.refEventHubs()
	hub, err := hubs.acquire(s.repoID)
	if err != nil {
		slog.WarnContext(s.ctx, "strata socket: ref events", slog.Any("error", err))
		return &closeError{code: websocket.StatusTryAgainLater, reason: "live ref events unavailable"}
	}
	defer hubs.release(hub)
	doorbell := hub.addDoorbell([]string{reflayout.For(s.store).Root().Prefix() + "/"})
	defer hub.remove(doorbell)

	if err := s.send(socketMessage{Type: "ready", Writer: s.writer.ID()}); err != nil {
		return errGoneAway
	}
	// Tell what landed since the page's read at once, not on the next ring.
	if s.token != "" {
		doorbell.signal()
	}

	frames := make(chan socketFrame, 64)
	gone := make(chan struct{}) // the client is: its connection no longer reads
	go func() {
		defer close(frames)
		defer close(gone)
		for {
			var f socketFrame
			if err := wsjson.Read(s.ctx, s.conn, &f); err != nil {
				return
			}
			select {
			case frames <- f:
			case <-s.ctx.Done():
				return
			}
		}
	}()

	tick := time.NewTicker(stratawrite.DefaultEvictAfter / 4)
	defer tick.Stop()
	backoff := s.deps.StrataSockets.changesRetry
	var retry *time.Timer
	defer func() {
		if retry != nil {
			retry.Stop()
		}
	}()
	reauthorize := time.NewTicker(s.deps.StrataSockets.socketReauthorize)
	defer reauthorize.Stop()
	expiring := time.NewTimer(time.Until(deadline) - credentialMargin)
	defer expiring.Stop()
	lifetime := time.NewTimer(maxSocketLife)
	defer lifetime.Stop()
	looping := make(chan struct{})
	defer close(looping)
	go s.cutWhenStuck(s.writer.ID(), session.ending, gone, time.Until(deadline)-credentialMargin, deps.StrataSockets.endTimeout, looping)

	for {
		select {
		case f, ok := <-frames:
			if !ok {
				return errClosedNormally
			}
			if closing := s.handle(f, frames); closing != nil {
				return closing
			}
		case <-doorbell.wake:
			rang := doorbell.drain()
			if s.token == "" || onlyOwnLog(rang, s.writer.ID()) {
				continue
			}
			if err := s.changes(rang); err != nil {
				slog.WarnContext(s.ctx, "strata socket: reading changes", slog.Any("error", err))
				// The token did not move, so nothing is lost; but nothing else may ring.
				if retry != nil {
					retry.Stop()
				}
				retry = time.AfterFunc(backoff, doorbell.signal)
				backoff = min(backoff*2, s.deps.StrataSockets.changesRetryCeiling)
				continue
			}
			backoff = s.deps.StrataSockets.changesRetry
		case <-tick.C:
			if err := s.writer.Tick(s.ctx); errors.Is(err, stratawrite.ErrFenced) {
				return errFenced
			} else if err != nil {
				slog.WarnContext(s.ctx, "strata socket: tick", slog.Any("error", err))
			}
		case <-reauthorize.C:
			if err := deps.StreamCredentials.Check(s.ctx); err != nil {
				return errCredential
			}
			ok, err := repoPermissionAllowed(s.ctx, deps, s.repoID, permRepoWrite)
			if err != nil {
				return errUnconfirmedAccess
			}
			if !ok {
				return errRevoked
			}
		case <-expiring.C:
			return errExpiring
		case <-lifetime.C:
			return errMaxLife
		case <-s.writer.Fenced():
			return errFenced
		case code := <-session.stop:
			return &closeError{code: code, reason: "closing"}
		}
	}
}

// cutWhenStuck cuts the writer's transport when the socket has had to end for
// grace and its loop hasn't: an operation stalled mid-body on git would hold it
// past shutdown, a disconnect or the bearer lapsing. End can then publish
// nothing, so the lease lapses and the next session evicts the writer.
func (s *socketLoop) cutWhenStuck(writer string, ending, gone <-chan struct{}, expiring, grace time.Duration, looping <-chan struct{}) {
	expired := time.NewTimer(expiring)
	defer expired.Stop()
	select {
	case <-ending:
	case <-gone:
	case <-expired.C:
	case <-looping:
		return
	}
	cut := time.NewTimer(grace)
	defer cut.Stop()
	select {
	case <-cut.C:
		select {
		case <-looping:
			return
		default:
		}
		slog.WarnContext(s.ctx, "strata socket: the writer outlived its socket; cutting its transport",
			slog.String("writer", writer))
		s.writer.Abort()
	case <-looping:
	}
}

// onlyOwnLog: a ring that moved only this writer's log is its own write coming
// back. A ring naming no refs (the hub's NATS reconnect) is not.
func onlyOwnLog(rang map[string]ingest.RefEvent, writer string) bool {
	if len(rang) == 0 {
		return false
	}
	for name := range rang {
		r := reflayout.Parse(name)
		if r.Kind != reflayout.LogRotation || r.Writer != writer {
			return false
		}
	}
	return true
}

// changes reports other writers' changes, as the records changes stream does.
func (s *socketLoop) changes(rang map[string]ingest.RefEvent) error {
	res, err := s.deps.RecordsReader.Changes(s.ctx, s.repoID, s.store, s.token, records.ChangesOptions{Except: s.writer.ID()})
	if err != nil {
		return err
	}
	recordRingLag(s.ctx, "socket", rang, res)
	s.token = REDACTED
	switch {
	case res.Reload:
		return s.send(socketMessage{Type: "reload"})
	case !res.Empty():
		return s.send(socketMessage{Type: "changed", Patches: res.Patches, Records: res.Records, Deleted: res.Deleted})
	}
	return nil
}

// maxFramesPerPush bounds how long a burst can hold back its acks.
const maxFramesPerPush = 64

// handle applies a frame and the frames already queued behind it, then
// publishes them in one push: each push is a round trip to the store's remote.
func (s *socketLoop) handle(f socketFrame, queued <-chan socketFrame) *closeError {
	frames := []socketFrame{f}
drain:
	for len(frames) < maxFramesPerPush {
		select {
		case next, ok := <-queued:
			if !ok {
				break drain
			}
			frames = append(frames, next)
		default:
			break drain
		}
	}
	for len(frames) > 0 {
		n := 1
		var closing *closeError
		if frames[0].Op == "write" {
			for n < len(frames) && frames[n].Op == "write" {
				n++
			}
			closing = s.applyWrites(frames[:n])
		} else {
			closing = s.apply(frames[0])
		}
		if closing != nil {
			return closing
		}
		frames = frames[n:]
	}
	s.writer.Publish(s.ctx)
	for _, m := range s.held {
		if err := s.send(m); err != nil {
			return errGoneAway
		}
	}
	clear(s.held)
	s.held = s.held[:0]
	return nil
}

func (s *socketLoop) apply(f socketFrame) *closeError {
	var err error
	switch f.Op {
	case "reorder":
		err = s.writer.Reorder(s.ctx, f.Type, f.ReorderRequest)
	case "push":
		err = s.writer.Push(s.ctx, f.Type, f.ID, f.Field, f.Value)
	case "fold":
		err = s.writer.Fold(s.ctx, f.Type, f.ID, f.Field, f.Remove, f.Value)
	default:
		err = huma.Error400BadRequest("unknown op " + f.Op)
	}
	return s.answer(f.Seq, nil, err)
}

// applyWrites lands write frames in as few commits as their order allows. A
// commit lands deletes after all its writes, so frames combine only up to and
// including one that deletes.
func (s *socketLoop) applyWrites(writes []socketFrame) *closeError {
	valid := writes[:0:0]
	for _, f := range writes {
		if f.Batch == nil {
			s.hold(f.Seq, nil, huma.Error400BadRequest("write without a batch"))
			continue
		}
		valid = append(valid, f)
	}
	for len(valid) > 0 {
		n := 1
		for n < len(valid) && len(valid[n-1].Batch.Deletes) == 0 {
			n++
		}
		if closing := s.applyCombined(valid[:n]); closing != nil {
			return closing
		}
		valid = valid[n:]
	}
	return nil
}

// applyCombined lands frames as one commit, or each alone if that is refused.
func (s *socketLoop) applyCombined(valid []socketFrame) *closeError {
	if len(valid) > 1 {
		var combined recordapi.Batch
		for _, f := range valid {
			combined.Writes = append(combined.Writes, f.Batch.Writes...)
			combined.Deletes = append(combined.Deletes, f.Batch.Deletes...)
		}
		written, err := s.writer.Apply(s.ctx, combined)
		if errors.Is(err, stratawrite.ErrFenced) {
			return errFenced
		}
		if err == nil && len(written) != len(combined.Writes) {
			// Committed, but which refs belong to which frame is lost, so the
			// client re-reads.
			slog.WarnContext(s.ctx, "strata socket: a combined write answered with an unexpected number of refs",
				slog.Int("writes", len(combined.Writes)), slog.Int("written", len(written)))
			for _, f := range valid {
				s.hold(f.Seq, nil, nil)
			}
			s.held = append(s.held, socketMessage{Type: "reload"})
			return nil
		}
		if err == nil {
			for _, f := range valid {
				n := len(f.Batch.Writes)
				s.hold(f.Seq, written[:n], nil)
				written = written[n:]
			}
			return nil
		}
	}
	for _, f := range valid {
		written, err := s.writer.Apply(s.ctx, *f.Batch)
		if closing := s.answer(f.Seq, written, err); closing != nil {
			return closing
		}
	}
	return nil
}

func (s *socketLoop) answer(seq int64, written []recordapi.RecordRef, err error) *closeError {
	if errors.Is(err, stratawrite.ErrFenced) {
		return errFenced
	}
	s.hold(seq, written, err)
	return nil
}

func (s *socketLoop) hold(seq int64, written []recordapi.RecordRef, err error) {
	m := socketMessage{Type: "ack", Seq: &seq, Written: written}
	if err != nil {
		m = s.reject(seq, err)
	}
	s.held = append(s.held, m)
}

// reject names a server-side failure only by its status, as the HTTP routes
// redact one, and logs it.
func (s *socketLoop) reject(seq int64, err error) socketMessage {
	status := socketStatus(err)
	msg := err.Error()
	if status >= http.StatusInternalServerError {
		slog.ErrorContext(s.ctx, "strata socket: frame failed", slog.Int("status", status), slog.Any("error", err))
		msg = http.StatusText(status)
	}
	return socketMessage{Type: "reject", Seq: &seq, Error: msg, Status: status}
}

func socketStatus(err error) int {
	var se huma.StatusError
	if !errors.As(err, &se) {
		errors.As(recordsVerdict(err, "strata write failed"), &se)
	}
	return se.GetStatus()
}

// upgradeRequest rebuilds the method, host and headers a WebSocket upgrade
// reads, since this huma version doesn't expose the *http.Request.
func upgradeRequest(hctx huma.Context) *http.Request {
	r := &http.Request{Method: hctx.Method(), Host: hctx.Host(), Header: http.Header{}, ProtoMajor: 1, ProtoMinor: 1}
	hctx.EachHeader(func(name, value string) { r.Header.Add(name, value) })
	u := hctx.URL()
	r.URL = &u
	return r.WithContext(hctx.Context())
}

