35	// EnableStrataSockets is for a harness that sets StrataRepoURL itself.
36	func (deps *RepoActivityDeps) EnableStrataSockets() {
37		if deps.StrataSockets == nil {
38			deps.StrataSockets = newStrataSockets()
39		}
40	}
