51	// RepoStrataCreateInput is PUT /repos/{repo_id}/strata/{store}.
52	type RepoStrataCreateInput struct {
53		RepoID string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
54		Store  string `path:"store" doc:"Store (schema) name"`
55		Body   struct {
56			Definition string `json:"definition" doc:"The schema definition file (YAML); its name must match {store}"`
57		}
58	}
