61	type RepoStrataCreateOutput struct{ Status int }
62	
63	// RepoStrataEditsInput is POST /repos/{repo_id}/strata/{store}/edits.
64	type RepoStrataEditsInput struct {
65		RepoID         string          `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
66		Store          string          `path:"store" doc:"Store (schema) name"`
67		IdempotencyKey string          `header:"Idempotency-Key" doc:"Optional replay-safe key; a retried request with the same key and body returns the cached response instead of re-executing."`
68		Body           recordapi.Batch `doc:"Writes and deletes to land as one commit"`
69	}
