71	type RepoStrataEditsOutput struct {
72		// Status is 202 when the write may not have landed.
73		Status              int
74		IdempotencyReplayed string `header:"Idempotency-Replayed" doc:"true when an earlier request with the same Idempotency-Key wrote these records and nothing was written now; absent otherwise."`
75		Body                struct {
76			Written   []recordapi.RecordRef `json:"written"`
77			Confirmed bool                  `json:"confirmed" doc:"false (with 202) when the write may or may not have landed: the push's answer was lost. Look for the written records before writing them again."`
78		}
