83	func (o *RepoStrataEditsOutput) responseStatus() int { return o.Status }
84	
85	func registerRepoStrata(api huma.API, deps *RepoActivityDeps) {
86		// Any cell: a strata write is a git push to the repo, which may enter at any
87		// placement that holds it.
88		createGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoManageSettings(api, deps))
89		writeGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
90		extra := []int{http.StatusNotFound, http.StatusBadGateway}
91	
92		createOp := teamOp(api, "repoStrataCreate", http.MethodPut, "/repos/{repo_id}/strata/{store}",
93			"Create a strata record store, or update its schema", "strata", createGate)
94		createOp.Errors = withExtraErrors(createOp.Errors, append(extra, http.StatusConflict)...)
95		createOp.DefaultStatus = http.StatusNoContent
96		createOp.Responses = map[string]*huma.Response{"202": {Description: "The push's answer was lost, so the schema may or may not have landed. Sending it again is safe."}}
97		huma.Register(api, createOp, func(ctx context.Context, in *RepoStrataCreateInput) (*RepoStrataCreateOutput, error) {
98			r, err := strataRemote(ctx, deps, in.RepoID)
99			if err != nil {
100				return nil, err
101			}
102			desired, err := parseStrataSchema(in.Store, in.Body.Definition)
103			if err != nil {
104				return nil, huma.Error400BadRequest(err.Error())
105			}
106			err = r.Create(ctx, desired, strataAuthor(ctx))
107			switch {
108			case errors.Is(err, stratawrite.ErrUnconfirmed):
109				slog.WarnContext(ctx, "strata schema unconfirmed", slog.Any("error", err))
110				return &RepoStrataCreateOutput{Status: http.StatusAccepted}, nil
111			case err != nil:
112				return nil, strataHTTPError(err)
113			}
114			return &RepoStrataCreateOutput{Status: http.StatusNoContent}, nil
115		})
116	
117		editsOp := teamOp(api, "repoStrataEdits", http.MethodPost, "/repos/{repo_id}/strata/{store}/edits",
118			"Write a batch of records into a strata record store", "strata", writeGate)
119		editsOp.Errors = withExtraErrors(editsOp.Errors, append(extra, http.StatusConflict)...)
120		editsOp.Responses = map[string]*huma.Response{"202": {Description: "The push's answer was lost, so the write may or may not have landed; the body names what it wrote, with confirmed false."}}
121		huma.Register(api, editsOp, withIdempotency(deps, http.StatusOK,
122			func(in *RepoStrataEditsInput) string { return in.IdempotencyKey },
123			func(in *RepoStrataEditsInput) string { return "strata:edits:" + in.RepoID + ":" + in.Store },
124			func(ctx context.Context, in *RepoStrataEditsInput) (*RepoStrataEditsOutput, error) {
125				r, err := strataRemote(ctx, deps, in.RepoID)
126				if err != nil {
127					return nil, err
128				}
129				written, err := r.OneShot(ctx, in.Store, in.Body, strataAuthor(ctx))
130				out := &RepoStrataEditsOutput{Status: http.StatusOK}
131				switch {
132				case errors.Is(err, stratawrite.ErrUnconfirmed):
133					slog.WarnContext(ctx, "strata write unconfirmed", slog.Any("error", err))
134					out.Status = http.StatusAccepted
135				case err != nil:
136					return nil, strataHTTPError(err)
137				default:
138					out.Body.Confirmed = true
139				}
140				out.Body.Written = written
141				return out, nil
142			}))
143	}
144	
145	func parseStrataSchema(store, definition string) (schema.Schema, error) {
146		desired, err := schema.ParseFile([]byte(definition))
147		if err != nil {
148			return schema.Schema{}, err
149		}
150		if err := schema.ValidateFile(desired); err != nil {
151			return schema.Schema{}, err
152		}
153		if desired.Name != store {
154			return schema.Schema{}, fmt.Errorf("schema name %q does not match store %q", desired.Name, store)
155		}
156		return desired, nil
157	}
158	
159	func strataRemote(ctx context.Context, deps *RepoActivityDeps, repoID string) (stratawrite.Remote, error) {
160		if deps.StrataRepoURL == nil {
161			return stratawrite.Remote{}, huma.Error404NotFound("strata writes need an entiredb upstream")
162		}
163		return stratawrite.Remote{URL: deps.StrataRepoURL(repoID), Client: contentHTTPClient(ctx, deps)}, nil
164	}
165	
166	func strataAuthor(ctx context.Context) string {
167		name, email := auth.CommitAuthor(ctx)
168		return fmt.Sprintf("%s <%s>", name, email)
169	}
170	
171	func strataHTTPError(err error) error {
172		if errors.Is(err, recstore.ErrNoSchema) {
173			return huma.Error404NotFound(err.Error())
174		}
175		if errors.Is(err, stratawrite.ErrSchemaRefused) || errors.Is(err, git.ErrRejected) {
176			return huma.Error409Conflict(err.Error())
177		}
178		return recordsVerdict(err, "strata write failed")
179	}
