1	package httpapi
2	
3	import (
4		"context"
5		"errors"
6		"log/slog"
7		"net/http"
8		"os"
9		"sync"
10		"time"
11	
12		"github.com/coder/websocket"
13		"github.com/coder/websocket/wsjson"
14		"github.com/danielgtaylor/huma/v2"
15		"github.com/entirehq/entire-records/recordapi"
16		recstore "github.com/entirehq/entire-records/store"
17		"github.com/entirehq/strata/reflayout"
18	
19		"github.com/entirehq/entire-api/internal/auth"
20		"github.com/entirehq/entire-api/internal/ingest"
21		"github.com/entirehq/entire-api/internal/records"
22		"github.com/entirehq/entire-api/internal/stratawrite"
23	)
24	
25	// Application close codes. A client reconnects on all but closeNoStore.
26	const (
27		// closeFenced: the writer could not keep its lease. Reconnect as a new one.
28		closeFenced websocket.StatusCode = 4000
29		// closeCredential: the bearer is about to lapse. Reconnect with a fresh one.
30		closeCredential websocket.StatusCode = 4001
31		// closeSuperseded: the caller opened too many sockets; the oldest gave way.
32		closeSuperseded websocket.StatusCode = 4003
33		// closeNoStore: nobody created this store. Not worth reconnecting.
34		closeNoStore websocket.StatusCode = 4004
35	)
36	
37	const (
38		maxSocketsPerCaller = 5
39		defaultMaxSockets   = 500
40		// credentialMargin is how long before the bearer lapses the socket ends: End
41		// publishes the writer's eviction with that bearer.
42		credentialMargin = 2 * time.Minute
43		// socketUpstreamTimeout is generous: a push is answered only once entiredb
44		// has taken the whole pack.
45		socketUpstreamTimeout = time.Minute
46		// socketReadLimit matches entire-records' HTTP body limit. A fold's frame
47		// carries removed entries too, which the library's 32 KiB default refuses.
48		socketReadLimit    = 4 << 20
49		socketEndTimeout   = 15 * time.Second
50		socketWriteTimeout = 10 * time.Second
51		socketRetryAfter   = "5"
52		// maxSocketLife ends a socket's writer well before StaleBlockerAfter, so no
53		// live writer looks stale to a cell that cannot see its lease.
54		maxSocketLife = stratawrite.StaleBlockerAfter / 2
55	)
56	
57	// changesRetry is how long a socket whose changes read failed waits before
58	// reading again, doubling to changesRetryCeiling. socketReauthorize is how often
59	// an open socket re-checks its credential and push access; the credential check
60	// reads a liveness answer up to a minute old, so a revoked session can keep
61	// writing for up to two minutes plus one Core lookup.
62	const (
63		changesRetry        = time.Second
64		changesRetryCeiling = 30 * time.Second
65		socketReauthorize   = time.Minute
66	)
67	
68	type closeError struct {
69		code   websocket.StatusCode
70		reason string
71	}
72	
73	var (
74		errClosedNormally    = &closeError{code: websocket.StatusNormalClosure}
75		errGoneAway          = &closeError{code: websocket.StatusGoingAway}
76		errFenced            = &closeError{code: closeFenced, reason: "lease lost; reconnect"}
77		errCredential        = &closeError{code: closeCredential, reason: "credential no longer valid"}
78		errExpiring          = &closeError{code: closeCredential, reason: "credential expiring; reconnect with a fresh one"}
79		errMaxLife           = &closeError{code: closeCredential, reason: "socket reached its maximum life; reconnect"}
80		errRevoked           = &closeError{code: websocket.StatusPolicyViolation, reason: "push access revoked"}
81		errUnconfirmedAccess = &closeError{code: websocket.StatusTryAgainLater, reason: "push access could not be confirmed; reconnect"}
82	)
83	
84	// strataSockets is this replica's live sockets, for the limits and for shutdown:
85	// http.Server.Shutdown does not wait for a hijacked connection.
86	type strataSockets struct {
87		replica         string
88		max             int
89		endTimeout      time.Duration
90		upstreamTimeout time.Duration
91		// Per registry, not package vars, so a test can shrink them without racing
92		// a socket loop that outlives the test's own cleanup.
93		changesRetry        time.Duration
94		changesRetryCeiling time.Duration
95		socketReauthorize   time.Duration
96	
97		mu       sync.Mutex
98		sessions map[socketKey][]*socketSession
99		total    int
100		stopping bool
101		live     sync.WaitGroup
102	}
103	
104	type socketKey struct{ caller, repo, store string }
105	
106	type socketSession struct {
107		key        socketKey
108		stop       chan websocket.StatusCode // buffered(1): the first reason to end wins
109		ending     chan struct{}
110		once       sync.Once
111		superseded bool
112	}
113	
114	func (s *socketSession) end(code websocket.StatusCode) {
115		s.once.Do(func() {
116			s.stop <- code
117			close(s.ending)
118		})
119	}
120	
121	func newStrataSockets() *strataSockets {
122		replica, _ := os.Hostname()
123		return &strataSockets{replica: replica, max: defaultMaxSockets, endTimeout: socketEndTimeout, upstreamTimeout: socketUpstreamTimeout,
124			changesRetry: changesRetry, changesRetryCeiling: changesRetryCeiling, socketReauthorize: socketReauthorize, sessions: map[socketKey][]*socketSession{}}
125	}
126	
127	// admit counts a socket in, asking the caller's oldest to give way past the
128	// per-caller limit.
129	func (r *strataSockets) admit(key socketKey) (*socketSession, error) {
130		r.mu.Lock()
131		defer r.mu.Unlock()
132		if r.stopping || r.total >= r.max {
133			return nil, socketUnavailable("this replica is not taking write sockets; retry")
134		}
135		s := &socketSession{key: key, stop: make(chan websocket.StatusCode, 1), ending: make(chan struct{})}
136		r.sessions[key] = append(r.sessions[key], s)
137		r.total++
138		r.live.Add(1)
139		staying := 0
140		for _, other := range r.sessions[key] {
141			if !other.superseded {
142				staying++
143			}
144		}
145		for _, other := range r.sessions[key] {
146			if staying <= maxSocketsPerCaller {
147				break
148			}
149			if !other.superseded {
150				other.superseded = true
151				other.end(closeSuperseded)
152				staying--
153			}
154		}
155		return s, nil
156	}
157	
158	func (r *strataSockets) release(s *socketSession) {
159		r.mu.Lock()
160		defer r.mu.Unlock()
161		mine := r.sessions[s.key]
162		for i, other := range mine {
163			if other == s {
164				r.sessions[s.key] = append(mine[:i], mine[i+1:]...)
165				r.total--
166				break
167			}
168		}
169		if len(r.sessions[s.key]) == 0 {
170			delete(r.sessions, s.key)
171		}
172		r.live.Done()
173	}
174	
175	func (r *strataSockets) Shutdown(ctx context.Context) error {
176		r.mu.Lock()
177		r.stopping = true
178		for _, mine := range r.sessions {
179			for _, s := range mine {
180				s.end(websocket.StatusServiceRestart)
181			}
182		}
183		r.mu.Unlock()
184		done := make(chan struct{})
185		go func() { r.live.Wait(); close(done) }()
186		select {
187		case <-done:
