228	func registerStrataSocket(api huma.API, deps *RepoActivityDeps) {
229		gate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
230		op := teamOp(api, "repoStrataSocket", http.MethodGet, "/repos/{repo_id}/strata/{store}/sockets",
231			"Hold a write socket on a strata record store", "strata", gate)
232		op.Errors = withExtraErrors(op.Errors, http.StatusNotFound, http.StatusServiceUnavailable)
233		huma.Register(api, op, func(ctx context.Context, in *RepoStrataSocketInput) (*huma.StreamResponse, error) {
234			if deps.StrataRepoURL == nil || deps.StrataSockets == nil {
235				return nil, huma.Error404NotFound("strata writes need an entiredb upstream")
236			}
237			if deps.RefEventsNATS == nil {
238				return nil, huma.Error503ServiceUnavailable("live ref events are not configured")
239			}
240			// Catches a session logged out since its JWT was minted.
241			if err := deps.StreamCredentials.Check(ctx); err != nil {
242				return nil, huma.Error401Unauthorized("the bearer is no longer valid")
243			}
244			id := auth.FromContext(ctx)
245			deadline := id.BearerExpiry()
246			if time.Until(deadline) < 2*credentialMargin {
247				return nil, huma.Error401Unauthorized("the bearer expires too soon to hold a write socket; refresh it and reconnect")
248			}
249			caller, ok := id.Subject.AccountID()
250			if !ok {
251				caller = id.Subject.String()
252			}
253			if in.ChangesToken != "" {
254				if _, err := recordsReader(deps); err != nil {
255					return nil, err
256				}
257				if err := records.ValidChangesToken(in.ChangesToken, in.RepoID, in.Store); err != nil {
258					return nil, recordsHTTPError(err)
259				}
260			}
261			session, err := deps.StrataSockets.admit(socketKey{caller: caller, repo: in.RepoID, store: in.Store})
262			if err != nil {
263				return nil, err
264			}
265			return &huma.StreamResponse{Body: func(hctx huma.Context) {
266				defer deps.StrataSockets.release(session)
267				w, ok := hctx.BodyWriter().(http.ResponseWriter)
268				if !ok {
269					hctx.SetStatus(http.StatusInternalServerError)
270					return
271				}
272				// Origin is not checked: the bearer on the upgrade authorizes the
273				// socket, never an ambient cookie a cross-origin page could borrow.
274				conn, err := websocket.Accept(w, upgradeRequest(hctx), &websocket.AcceptOptions{InsecureSkipVerify: true})
275				if err != nil {
276					slog.WarnContext(hctx.Context(), "strata socket: accepting the upgrade failed", slog.Any("error", err))
277					return
278				}
279				conn.SetReadLimit(socketReadLimit)
280				serveStrataSocket(context.WithoutCancel(hctx.Context()), deps, conn, session, deadline, in.RepoID, in.Store, in.ChangesToken)
281			}}, nil
282		})
283	}
