285	func serveStrataSocket(ctx context.Context, deps *RepoActivityDeps, conn *websocket.Conn, session *socketSession, deadline time.Time, repoID, store, changesToken string) {
286		ctx, cancel := context.WithCancel(ctx)
287		defer cancel()
288		remote := stratawrite.Remote{
289			URL: deps.StrataRepoURL(repoID),
290			// Only the wait for headers is bounded: a pack download grows with the
291			// store.
292			Client: &http.Client{Transport: headerTimeoutTransport{timeout: deps.StrataSockets.upstreamTimeout, base: contentRoundTripper(ctx, deps)}},
293		}
294		writer, err := stratawrite.Start(ctx, remote, deps.Store, repoID, store, deps.StrataSockets.replica,
295			strataAuthor(ctx), stratawrite.DefaultEvictAfter)
296		if errors.Is(err, recstore.ErrNoSchema) {
297			_ = conn.Close(closeNoStore, "no such store")
298			return
299		}
300		if err != nil {
301			slog.WarnContext(ctx, "strata socket: starting a writer", slog.String("store", store), slog.Any("error", err))
302			_ = conn.Close(websocket.StatusInternalError, "could not start a writer")
303			return
304		}
305		s := &socketLoop{ctx: ctx, conn: conn, writer: writer, deps: deps, repoID: repoID, store: store, token: changesToken}
306		closing := s.run(session, deadline)
307		endCtx, stop := context.WithTimeout(context.WithoutCancel(ctx), deps.StrataSockets.endTimeout)
308		defer stop()
309		if err := writer.End(endCtx); err != nil {
310			slog.WarnContext(ctx, "strata socket: ending a writer", slog.String("writer", writer.ID()), slog.Any("error", err))
311		}
312		_ = conn.Close(closing.code, closing.reason)
313	}
