315	type socketLoop struct {
316		ctx    context.Context
317		conn   *websocket.Conn
318		writer *stratawrite.Writer
319		deps   *RepoActivityDeps
320		repoID string
321		store  string
322		// token is empty when the page passed no changes_token: the socket then reports no changes.
323		token string
324		// held are answers to frames applied but not yet pushed: they follow the push that covers them.
325		held []socketMessage
326	}
