328	func (s *socketLoop) send(m socketMessage) error {
329		ctx, cancel := context.WithTimeout(s.ctx, socketWriteTimeout)
330		defer cancel()
331		return wsjson.Write(ctx, s.conn, m)
332	}
333	
334	// run is the connection's loop, and the one goroutine that calls the writer
335	// (cutWhenStuck's Abort aside). It returns how to close.
336	func (s *socketLoop) run(session *socketSession, deadline time.Time) *closeError {
337		deps := s.deps
338		// Subscribed before ready, so no later write by another writer is missed.
339		hubs := deps.refEventHubs()
340		hub, err := hubs.acquire(s.repoID)
341		if err != nil {
342			slog.WarnContext(s.ctx, "strata socket: ref events", slog.Any("error", err))
343			return &closeError{code: websocket.StatusTryAgainLater, reason: "live ref events unavailable"}
344		}
345		defer hubs.release(hub)
346		doorbell := hub.addDoorbell([]string{reflayout.For(s.store).Root().Prefix() + "/"})
347		defer hub.remove(doorbell)
348	
349		if err := s.send(socketMessage{Type: "ready", Writer: s.writer.ID()}); err != nil {
350			return errGoneAway
351		}
352		// Tell what landed since the page's read at once, not on the next ring.
353		if s.token != "" {
354			doorbell.signal()
355		}
356	
357		frames := make(chan socketFrame, 64)
358		gone := make(chan struct{}) // the client is: its connection no longer reads
359		go func() {
360			defer close(frames)
361			defer close(gone)
362			for {
363				var f socketFrame
364				if err := wsjson.Read(s.ctx, s.conn, &f); err != nil {
365					return
366				}
367				select {
368				case frames <- f:
369				case <-s.ctx.Done():
370					return
371				}
372			}
373		}()
374	
375		tick := time.NewTicker(stratawrite.DefaultEvictAfter / 4)
376		defer tick.Stop()
377		backoff := s.deps.StrataSockets.changesRetry
378		var retry *time.Timer
379		defer func() {
380			if retry != nil {
381				retry.Stop()
382			}
383		}()
384		reauthorize := time.NewTicker(s.deps.StrataSockets.socketReauthorize)
385		defer reauthorize.Stop()
386		expiring := time.NewTimer(time.Until(deadline) - credentialMargin)
387		defer expiring.Stop()
388		lifetime := time.NewTimer(maxSocketLife)
389		defer lifetime.Stop()
390		looping := make(chan struct{})
391		defer close(looping)
392		go s.cutWhenStuck(s.writer.ID(), session.ending, gone, time.Until(deadline)-credentialMargin, deps.StrataSockets.endTimeout, looping)
393	
394		for {
395			select {
396			case f, ok := <-frames:
397				if !ok {
398					return errClosedNormally
399				}
400				if closing := s.handle(f, frames); closing != nil {
401					return closing
402				}
403			case <-doorbell.wake:
404				rang := doorbell.drain()
405				if s.token == "" || onlyOwnLog(rang, s.writer.ID()) {
406					continue
407				}
408				if err := s.changes(rang); err != nil {
409					slog.WarnContext(s.ctx, "strata socket: reading changes", slog.Any("error", err))
410					// The token did not move, so nothing is lost; but nothing else may ring.
411					if retry != nil {
412						retry.Stop()
413					}
414					retry = time.AfterFunc(backoff, doorbell.signal)
415					backoff = min(backoff*2, s.deps.StrataSockets.changesRetryCeiling)
416					continue
417				}
418				backoff = s.deps.StrataSockets.changesRetry
419			case <-tick.C:
420				if err := s.writer.Tick(s.ctx); errors.Is(err, stratawrite.ErrFenced) {
421					return errFenced
422				} else if err != nil {
423					slog.WarnContext(s.ctx, "strata socket: tick", slog.Any("error", err))
424				}
425			case <-reauthorize.C:
426				if err := deps.StreamCredentials.Check(s.ctx); err != nil {
427					return errCredential
428				}
429				ok, err := repoPermissionAllowed(s.ctx, deps, s.repoID, permRepoWrite)
430				if err != nil {
431					return errUnconfirmedAccess
432				}
433				if !ok {
434					return errRevoked
435				}
436			case <-expiring.C:
437				return errExpiring
438			case <-lifetime.C:
439				return errMaxLife
440			case <-s.writer.Fenced():
441				return errFenced
442			case code := <-session.stop:
443				return &closeError{code: code, reason: "closing"}
444			}
445		}
446	}
