448	// cutWhenStuck cuts the writer's transport when the socket has had to end for
449	// grace and its loop hasn't: an operation stalled mid-body on git would hold it
450	// past shutdown, a disconnect or the bearer lapsing. End can then publish
451	// nothing, so the lease lapses and the next session evicts the writer.
452	func (s *socketLoop) cutWhenStuck(writer string, ending, gone <-chan struct{}, expiring, grace time.Duration, looping <-chan struct{}) {
453		expired := time.NewTimer(expiring)
454		defer expired.Stop()
455		select {
456		case <-ending:
457		case <-gone:
458		case <-expired.C:
459		case <-looping:
460			return
461		}
462		cut := time.NewTimer(grace)
463		defer cut.Stop()
464		select {
465		case <-cut.C:
466			select {
467			case <-looping:
468				return
469			default:
470			}
471			slog.WarnContext(s.ctx, "strata socket: the writer outlived its socket; cutting its transport",
472				slog.String("writer", writer))
473			s.writer.Abort()
474		case <-looping:
475		}
476	}
