478	// onlyOwnLog: a ring that moved only this writer's log is its own write coming
479	// back. A ring naming no refs (the hub's NATS reconnect) is not.
480	func onlyOwnLog(rang map[string]ingest.RefEvent, writer string) bool {
481		if len(rang) == 0 {
482			return false
483		}
484		for name := range rang {
485			r := reflayout.Parse(name)
486			if r.Kind != reflayout.LogRotation || r.Writer != writer {
487				return false
488			}
489		}
490		return true
491	}
