493	// changes reports other writers' changes, as the records changes stream does.
494	func (s *socketLoop) changes(rang map[string]ingest.RefEvent) error {
495		res, err := s.deps.RecordsReader.Changes(s.ctx, s.repoID, s.store, s.token, records.ChangesOptions{Except: s.writer.ID()})
496		if err != nil {
497			return err
498		}
499		recordRingLag(s.ctx, "socket", rang, res)
500		s.token = REDACTED
501		switch {
502		case res.Reload:
503			return s.send(socketMessage{Type: "reload"})
504		case !res.Empty():
505			return s.send(socketMessage{Type: "changed", Patches: res.Patches, Records: res.Records, Deleted: res.Deleted})
506		}
507		return nil
508	}
