673	// upgradeRequest rebuilds the method, host and headers a WebSocket upgrade
674	// reads, since this huma version doesn't expose the *http.Request.
675	func upgradeRequest(hctx huma.Context) *http.Request {
676		r := &http.Request{Method: hctx.Method(), Host: hctx.Host(), Header: http.Header{}, ProtoMajor: 1, ProtoMinor: 1}
677		hctx.EachHeader(func(name, value string) { r.Header.Add(name, value) })
678		u := hctx.URL()
679		r.URL = &u
680		return r.WithContext(hctx.Context())
681	}
