71			// Subscribed before the first read, so a move during it still rings.
72			hubs := deps.refEventHubs()
73			hub, err := hubs.acquire(in.RepoID)
74			if err != nil {
75				return nil, huma.Error503ServiceUnavailable("live ref events unavailable", err)
76			}
77			doorbell := hub.addDoorbell([]string{reflayout.For(store).Root().Prefix() + "/"})
78			// Read before streaming, so a bad token or schema is a status, not a frame.
79			first, err := read(ctx, token)
80			if err != nil {
81				hub.remove(doorbell)
82				hubs.release(hub)
83				return nil, recordsHTTPError(err)
84			}
85	
86			repoID, userID := in.RepoID, callerCacheKey(ctx)
87			seedStreamAuth(authCache, userID, repoID, true)
88			authorized := cachedStreamAuth(authCache, userID, repoID, func(actx context.Context) (bool, error) {
89				return repoPermissionAllowed(actx, deps, repoID, permRepoRead)
90			})
91			return &huma.StreamResponse{Body: func(hctx huma.Context) {
92				defer hubs.release(hub)
93				defer hub.remove(doorbell)
94				// Not held for the stream's lifetime: it may be many records.
95				answer := first
96				first = records.ChangesResult{}
97				recordsChangesConnection(hctx.Context(), openSSE(hctx), doorbell, authorized, read, answer)
98			}}, nil
99		})
100	}
101	
102	func recordsChangesConnection(ctx context.Context, s *sseWriter, doorbell *refHubConn, authorized func(context.Context) (bool, error), read recordsChangesReader, first records.ChangesResult) {
103		token, ok := sendRecordsChanges(s, first)
104		if !ok {
105			return
106		}
107		if !s.frame("ready", token, struct{}{}) {
108			return
109		}
110	
111		startedAt := time.Now()
112		lastPing := startedAt
113		lastAuthAt := startedAt.Add(-ssePollInterval)
114		for ctx.Err() == nil {
115			now := time.Now()
116			if now.Sub(startedAt) > sseMaxDuration {
117				s.frame("reconnect", "", sseReason("max_duration"))
118				return
119			}
120			if now.Sub(lastAuthAt) >= ssePollInterval {
121				lastAuthAt = now
122				allowed, err := authorized(ctx)
123				if err != nil || !allowed {
124					s.frame("forbidden", "", sseReason("access_revoked"))
125					return
126				}
127			}
128			if now = time.Now(); now.Sub(lastPing) >= ssePingInterval {
129				if !s.ping(now) {
130					return
131				}
132				lastPing = now
133			}
134			rung, ok := waitForWake(ctx, doorbell.wake, nextConnTick(time.Now(), startedAt, lastPing, lastAuthAt))
135			if !ok {
136				return
137			}
138			if !rung {
139				continue
140			}
141			// Even a ring naming no refs (the hub's NATS reconnect) reads: moves may have been missed.
142			rang := doorbell.drain()
143			res, err := read(ctx, token)
144			if err != nil {
145				if ctx.Err() == nil && !errors.Is(err, context.Canceled) {
146					s.frame("error", "", sseError())
147				}
148				return
149			}
150			recordRingLag(ctx, "changes", rang, res)
151			if token, ok = sendRecordsChanges(s, res); !ok {
152				return
153			}
154		}
155	}
156	
157	// nonNil encodes as [] rather than null.
158	func nonNil[T any](s []T) []T {
159		if s == nil {
160			return []T{}
161		}
162		return s
163	}
164	
165	// sendRecordsChanges returns the token to read from next; ok is false once the stream is over.
166	func sendRecordsChanges(s *sseWriter, res records.ChangesResult) (token string, ok bool) {
167		if res.Reload {
168			s.frame("reload", "", sseReason("read_again"))
169			return "", false
170		}
171		if res.Empty() {
172			return res.Token, true
173		}
174		data := recordsChangedData{Tip: res.Tip, Patches: nonNil(res.Patches), Records: nonNil(res.Records), Deleted: nonNil(res.Deleted)}
175		return res.Token, s.frame("changed", res.Token, data)
176	}
