package httpapi

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"

	"github.com/danielgtaylor/huma/v2"
	"github.com/entirehq/entire-records/recordapi"

	"github.com/entirehq/entire-api/internal/recordprojection"
	"github.com/entirehq/entire-api/internal/records"
	"github.com/entirehq/entire-api/internal/stratagit"
)

// The records routes: a read-only view of a repo's entire-records stores —
// schema-described records held in strata stores (refs/strata/<schema>/),
// served from this cell's projection of them. They are served on the v0 surface
// (APIv0Base), not v1: the shapes are not settled yet.
//
// A thin adapter over internal/records, which owns the read and its paging, over
// internal/recordprojection, which keeps the projection current. Reads gate on repo pull and are authenticated-only: a records
// store carries arbitrary user data with no per-record access control, so the
// whole store is exactly as readable as the repo, and this stays off the
// anonymous public surface for the same reason git-meta does.
//
// The response bodies embed entire-records' own DTOs rather than mirroring them,
// so entire-api's wire shape cannot drift from the decode that produces it. The
// OpenAPI component names are therefore that package's (RecordDTO, SchemaDTO),
// renamed for the gateway by schemanames.go.

// RecordsReader is the records surface the routes need, satisfied by
// *records.Reader. A fake stands in for route tests.
type RecordsReader interface {
	ListSchemas(ctx context.Context, repoID string, page records.Page) (records.SchemasResult, error)
	Schema(ctx context.Context, repoID, address string) (records.SchemaResult, error)
	Collections(ctx context.Context, repoID, address string, types []string, page records.Page) (records.CollectionsResult, error)
	Collection(ctx context.Context, repoID, address, typeName string, page records.Page) (records.CollectionResult, error)
	Record(ctx context.Context, repoID, address, typeName, id string) (records.RecordResult, error)
	Changes(ctx context.Context, repoID, address, token string, opts records.ChangesOptions) (records.ChangesResult, error)
}

// RecordsSchemaSummary is one schema a repo holds.
//
// No version here; the schema read reports it.
type RecordsSchemaSummary struct {
	Name string `json:"name" doc:"Schema name, as used in the {schema} path segment"`
	Tip  string `json:"tip" doc:"Names the store's current state"`
}

// RepoRecordsListSchemasInput is GET /repos/{repo_id}/records.
type RepoRecordsListSchemasInput struct {
	RepoID string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	RecordsPage
}

// RepoRecordsListSchemasOutput lists the repo's records schemas. No ETag: the
// listing spans every store, so there is no one state for it to name.
type RepoRecordsListSchemasOutput struct {
	Body struct {
		Items         []RecordsSchemaSummary `json:"items"`
		NextPageToken string                 `json:"nextPageToken,omitempty"`
	}
}

// RecordsPage is the pagination pair every list read here shares.
//
// Exported, and it has to be: huma resolves parameters by walking the input
// struct's exported fields, and an embedded field takes its type's name — so an
// unexported type embeds as an unexported field, which the walk skips silently.
//
// The token carries the state its scan started at along with the scope it
// covers. A continuation after the store has moved is refused with 409, and the
// caller restarts; a token that contradicts an explicit types list is refused
// rather than silently answering a different question.
type RecordsPage struct {
	PageSize  int    `query:"pageSize" minimum:"1" maximum:"100" default:"50" doc:"Maximum records per page"`
	PageToken string `query:"pageToken" doc:"Cursor from a previous page's nextPageToken"`
}

// RepoRecordsSchemaInput is GET /repos/{repo_id}/records/{schema}.
type RepoRecordsSchemaInput struct {
	RepoID string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Schema string `path:"schema" doc:"Schema name"`
}

// RepoRecordsSchemaOutput is a schema's type model and the state it was read from.
type RepoRecordsSchemaOutput struct {
	ETag string `header:"ETag"`
	Body struct {
		Tip     string `json:"tip" doc:"Names the state of the store this response was read from"`
		Version int    `json:"version" doc:"Version of the schema, counting the breaking changes it has survived"`
		// Named TypeModel rather than Schema: huma builds the response's
		// $schema link by prepending a struct field of its own called Schema,
		// and a body field with that Go name collides — reflect.StructOf
		// panics, huma recovers, and the link is silently dropped. The wire key
		// is unaffected.
		TypeModel recordapi.SchemaDTO `json:"schema"`
	}
}

// RepoRecordsCollectionsInput is GET /repos/{repo_id}/records/{schema}/collections.
type RepoRecordsCollectionsInput struct {
	RepoID string   `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Schema string   `path:"schema" doc:"Schema name"`
	Types  []string `query:"types,explode" doc:"Type names to read (repeatable or comma-separated). Omit for every type the schema declares, nested types included."`
	RecordsPage
}

// RepoRecordsCollectionsOutput is one page of records, all from one state of the
// store.
//
// A flat list rather than a map keyed by type: every record names its own type,
// so grouping stays the client's to do, and a page of a map of arrays has no
// well-defined boundary. Paging bounds the response; a page still reads every
// record of the types it spans.
type RepoRecordsCollectionsOutput struct {
	ETag string `header:"ETag"`
	Body struct {
		Tip           string                `json:"tip" doc:"Names the state of the store this page was read from; every page of one scan carries the same tip"`
		ChangesToken  string                `json:"changesToken" doc:"Where GET …/changes continues from this state, as its changes_token"`
		Items         []recordapi.RecordDTO `json:"items"`
		NextPageToken string                `json:"nextPageToken,omitempty"`
	}
}

// RepoRecordsCollectionInput is GET /repos/{repo_id}/records/{schema}/collections/{type}.
type RepoRecordsCollectionInput struct {
	RepoID string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Schema string `path:"schema" doc:"Schema name"`
	Type   string `path:"type" doc:"Type name, as declared by the schema"`
	RecordsPage
}

// RepoRecordsCollectionOutput is one page of a single type's records.
type RepoRecordsCollectionOutput struct {
	ETag string `header:"ETag"`
	Body struct {
		Tip           string                `json:"tip"`
		Type          string                `json:"type"`
		Items         []recordapi.RecordDTO `json:"items"`
		NextPageToken string                `json:"nextPageToken,omitempty"`
	}
}

// RepoRecordsGetInput is GET /repos/{repo_id}/records/{schema}/collections/{type}/{recordId}.
//
// recordId is camelCase, which is the rule (CASING-002) and the dominant
// spelling for a resource id here — reviewId, commentId, trailId, threadId and
// the rest. repo_id is the exception, and not one this surface may fix on its
// own: the access gate resolves it by name (authz.go's requireRepoAccess reads
// hctx.Param("repo_id")), so renaming it on these routes alone would hand the
// gate an empty id. It is one spelling across 95 route declarations; changing
// it is a platform-wide change, not a records one.
type RepoRecordsGetInput struct {
	RepoID   string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Schema   string `path:"schema" doc:"Schema name"`
	Type     string `path:"type" doc:"Type name, as declared by the schema"`
	RecordID string `path:"recordId" doc:"Record id (ULID). A nested record is read from its container's response, not here."`
}

// RepoRecordsGetOutput is one record with its children and nested records.
type RepoRecordsGetOutput struct {
	ETag string `header:"ETag"`
	Body struct {
		Tip    string                    `json:"tip"`
		Record recordapi.RecordDetailDTO `json:"record"`
	}
}

// registerRepoRecords wires the records read routes onto api, the v0 surface.
// repoOp bundles the access gate (repoReadGate: authn + repo pull, the same gate
// as registerRepos' reads), so none of these can be registered ungated.
func registerRepoRecords(api huma.API, deps *RepoActivityDeps) {
	gate := repoReadGate(api, deps)
	repoOp := func(id, method, path, summary, tag string) huma.Operation {
		return teamOp(api, id, method, path, summary, tag, gate)
	}
	// 404: the repo is not in this region (the gate), or no schema by that name.
	// 409: a page token the store has moved past; restart from the first page.
	// 429: the per-IP read-through throttle. 502: catching the projection up
	// over git failed.
	extra := []int{http.StatusNotFound, http.StatusConflict, http.StatusTooManyRequests, http.StatusBadGateway}

	listOp := repoOp("repoRecordsListSchemas", http.MethodGet, "/repos/{repo_id}/records",
		"List the repository's records schemas", "records")
	listOp.Errors = withExtraErrors(listOp.Errors, extra...)
	huma.Register(api, listOp, func(ctx context.Context, in *RepoRecordsListSchemasInput) (*RepoRecordsListSchemasOutput, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		found, err := reader.ListSchemas(ctx, in.RepoID, records.Page{Size: in.PageSize, Token: in.PageToken})
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		out := &RepoRecordsListSchemasOutput{}
		out.Body.NextPageToken = REDACTED
		out.Body.Items = make([]RecordsSchemaSummary, 0, len(found.Schemas))
		for _, s := range found.Schemas {
			out.Body.Items = append(out.Body.Items, RecordsSchemaSummary{Name: s.Name, Tip: s.Tip})
		}
		return out, nil
	})

	schemaOp := repoOp("repoRecordsSchema", http.MethodGet, "/repos/{repo_id}/records/{schema}",
		"Read a records schema's type model", "records")
	schemaOp.Errors = withExtraErrors(schemaOp.Errors, extra...)
	huma.Register(api, schemaOp, func(ctx context.Context, in *RepoRecordsSchemaInput) (*RepoRecordsSchemaOutput, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		res, err := reader.Schema(ctx, in.RepoID, in.Schema)
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		out := &RepoRecordsSchemaOutput{ETag: etag(res.Tip)}
		out.Body.Tip = res.Tip
		out.Body.Version = res.Version
		out.Body.TypeModel = res.Schema
		return out, nil
	})

	collectionsOp := repoOp("repoRecordsCollections", http.MethodGet, "/repos/{repo_id}/records/{schema}/collections",
		"Read several types' records from one state of the store", "records")
	collectionsOp.Errors = withExtraErrors(collectionsOp.Errors, extra...)
	huma.Register(api, collectionsOp, func(ctx context.Context, in *RepoRecordsCollectionsInput) (*RepoRecordsCollectionsOutput, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		// splitCSV (changes.go), because huma's `explode` reads repeated
		// parameters only and never splits on commas — without it the
		// documented `?types=a,b` spelling arrives as one type named "a,b"
		// and is refused by name, an error about a type nobody asked for.
		res, err := reader.Collections(ctx, in.RepoID, in.Schema, splitCSV(in.Types),
			records.Page{Size: in.PageSize, Token: in.PageToken})
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		out := &RepoRecordsCollectionsOutput{ETag: etag(res.Tip)}
		out.Body.Tip = res.Tip
		out.Body.ChangesToken = res.ChangesToken
		out.Body.Items = res.Records
		out.Body.NextPageToken = REDACTED
		return out, nil
	})

	collectionOp := repoOp("repoRecordsCollection", http.MethodGet, "/repos/{repo_id}/records/{schema}/collections/{type}",
		"Read one type's records", "records")
	collectionOp.Errors = withExtraErrors(collectionOp.Errors, extra...)
	huma.Register(api, collectionOp, func(ctx context.Context, in *RepoRecordsCollectionInput) (*RepoRecordsCollectionOutput, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		res, err := reader.Collection(ctx, in.RepoID, in.Schema, in.Type,
			records.Page{Size: in.PageSize, Token: in.PageToken})
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		out := &RepoRecordsCollectionOutput{ETag: etag(res.Tip)}
		out.Body.Tip = res.Tip
		out.Body.Type = res.Type
		out.Body.Items = res.Records
		out.Body.NextPageToken = REDACTED
		return out, nil
	})

	getOp := repoOp("repoRecordsGet", http.MethodGet, "/repos/{repo_id}/records/{schema}/collections/{type}/{recordId}",
		"Read one record with its children and nested records", "records")
	getOp.Errors = withExtraErrors(getOp.Errors, extra...)
	huma.Register(api, getOp, func(ctx context.Context, in *RepoRecordsGetInput) (*RepoRecordsGetOutput, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		res, err := reader.Record(ctx, in.RepoID, in.Schema, in.Type, in.RecordID)
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		out := &RepoRecordsGetOutput{ETag: etag(res.Tip)}
		out.Body.Tip = res.Tip
		out.Body.Record = res.Record
		return out, nil
	})
}

// EnableRecords wires the records routes: reads from this cell's projection of
// the repo's strata stores, caught up by fetching the store over git as the
// caller, through the same per-request content transport the other
// read-throughs use. Call after ContentBaseTransport / ContentTransport are set.
func (deps *RepoActivityDeps) EnableRecords() error {
	if deps.RepoAPIBase == "" || deps.Store == nil {
		return nil
	}
	origin, err := deps.gitOrigin()
	if err != nil {
		return fmt.Errorf("records: %w", err)
	}
	deps.RecordsReader = records.New(recordprojection.Reads{
		Store: deps.Store,
		Remote: func(ctx context.Context, repoID string) stratagit.Remote {
			return stratagit.Remote{URL: origin + "/git/repo/" + url.PathEscape(repoID), Client: contentHTTPClient(ctx, deps)}
		},
	})
	return nil
}

// recordsReader is the prologue every records handler shares.
func recordsReader(deps *RepoActivityDeps) (RecordsReader, error) {
	if deps.RecordsReader == nil {
		return nil, huma.Error500InternalServerError("records not configured", errors.New("RecordsReader nil"))
	}
	return deps.RecordsReader, nil
}

// recordsHTTPError maps a records read's failures onto statuses: the store's own
// absence, a page token the store has moved past, then entire-records'
// invalid/not-found verdicts via recordapi.StatusFor — the function its own
// surface uses — and anything else as the read upstream failing.
func recordsHTTPError(err error) error {
	switch {
	case errors.Is(err, records.ErrNoSchema):
		return huma.Error404NotFound(err.Error())
	case errors.Is(err, records.ErrStoreMoved):
		return huma.Error409Conflict(err.Error())
	}
	return recordsVerdict(err, "records read failed")
}

// recordsVerdict maps entire-records' verdicts onto 400/404 and the rest,
// failed round trips to entiredb, onto a 502.
func recordsVerdict(err error, upstream string) error {
	switch recordapi.StatusFor(err) {
	case http.StatusBadRequest:
		return huma.Error400BadRequest(err.Error())
	case http.StatusNotFound:
		return huma.Error404NotFound(err.Error())
	}
	return huma.Error502BadGateway(upstream, err)
}

package httpapi

import (
	"context"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	"github.com/entirehq/entire-api/internal/ingest"
	"github.com/entirehq/entire-api/internal/records"
)

// ringLag is how long a store's move takes to reach a live records reader,
// changes stream or write socket: from entiredb stamping the ref event to the
// read it rang being answered. It spans entiredb's outbox relay, NATS, the hub
// and the catch-up read, which no single span covers. otelsetup buckets it by
// name.
var ringLag, _ = otel.Meter("github.com/entirehq/entire-api/internal/httpapi").
	Float64Histogram("records.ring_lag",
		metric.WithDescription("Seconds from a records store's ref event to the live read it rang being answered, by consumer (changes, socket) and outcome (changed, empty, reload)"),
		metric.WithUnit("s"))

// recordRingLag measures a ring from the oldest event behind it. A ring with
// none, such as a NATS reconnect or a retry, has nothing to measure from.
func recordRingLag(ctx context.Context, consumer string, rang map[string]ingest.RefEvent, res records.ChangesResult) {
	oldest := oldestEvent(rang)
	if oldest.IsZero() {
		return
	}
	ringLag.Record(ctx, time.Since(oldest).Seconds(), metric.WithAttributes(
		attribute.String("consumer", consumer),
		attribute.String("outcome", ringOutcome(res))))
}

// oldestEvent is the earliest stamp among a ring's events, zero when none is
// stamped.
func oldestEvent(rang map[string]ingest.RefEvent) time.Time {
	var oldest time.Time
	for _, ev := range rang {
		if !ev.Timestamp.IsZero() && (oldest.IsZero() || ev.Timestamp.Before(oldest)) {
			oldest = ev.Timestamp
		}
	}
	return oldest
}

func ringOutcome(res records.ChangesResult) string {
	switch {
	case res.Reload:
		return "reload"
	case res.Empty():
		return "empty"
	}
	return "changed"
}

