// contentHTTPClient is the bearer-forwarding HTTP client the content
// read-throughs share (repoContentClient wraps the same transport in the typed
// repoapi client; the pass-throughs use it directly).
func contentHTTPClient(ctx context.Context, deps *RepoActivityDeps) *http.Client {
	return &http.Client{Timeout: contentRequestTimeout, Transport: contentRoundTripper(ctx, deps)}
}

// gitContentPassthrough opens the upstream request before writing any body
// byte, so upstream failures still map to a clean status; a non-404 failure
// becomes a 502 that does not echo upstream error text.
//
