package httpapi

// SSE (text/event-stream) live ref-change stream: GET /repos/{repo_id}/refs/events.
//
// Unlike the DB-polling SSE families (reviews_events_sse.go, threads_events_sse.go —
// one shared poll per resource, fanned out to every connection), this hub is
// push-driven: it owns one shared core NATS subscription per repo_id
// (internal/refstream, subject repo_refs_v1.{repo_id}), fed by entiredb's
// live ref-push stream, and fans debounced events out to every connection
// watching that repo — so N viewers of a hot repo cost one subscription, not
// N, the same "one shared drain" leverage as the poll-based hubs, just
// sourced from NATS instead of a store poll.
//
// Design, decided after exploring alternatives (Postgres LISTEN/NOTIFY was a
// lower-infra-cost option; not chosen because it was scoped for a
// low-latency signal at real scale):
//   - Source: a plain core (non-JetStream) NATS subscription, not a durable
//     JetStream consumer — at-most-once delivery is the right contract for a
//     live tail where a client re-syncs current state on every reconnect
//     rather than replaying history. See internal/refstream.
//   - Debounce: rapid updates to the SAME ref are coalesced to at most one
//     flush per refDebounceWindow (leaky-bucket: the first update schedules a
//     flush; further updates before it fires just replace the pending
//     payload, latest wins), computed ONCE in the hub and fanned out — so a
//     hot repo with many viewers doesn't multiply (raw update rate × viewer
//     count) into unbounded per-connection work. A doorbell (addDoorbell) is
//     rung at once instead: it renders no event, only reads what moved, and
//     its one-slot wake already folds a burst into the next read. The
//     debounce never merged across refs: each ref has its own timer, so a
//     burst over several refs flushed with the spacing it arrived with.
//   - No persisted history, no cursor, no catch-up walk (unlike the
//     poll-based hubs): this is a live-only signal. A connection's initial
//     state comes from a one-time live entiredb ListRefsWithSymrefs read (the
//     "snapshot" frame) — NOT repo_branch_tip, which only tracks branches
//     and never resolves symref targets — filtered by the same `prefix` the
//     connection requested, matching GET /repos/{repo_id}/refs's own
//     repeatable prefix convention (api/repov1.ListRefsInput, entiredb) so a
//     client that already knows that filter gets it for free here. symrefs=true
//     so a HEAD entry's symrefTarget is actually populated in the snapshot.
//   - Re-auth: unlike a poll-driven hub (which gets re-auth "for free" every
//     poll tick), a push-driven connection has no natural tick — a quiet
//     repo could go minutes between NATS messages — so each connection runs
//     its own ~ssePollInterval re-auth timer via the same shared
//     cachedStreamAuth cache the poll-based hubs use.
import (
	"context"
	"errors"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"github.com/entirehq/entiredb/modules/apidocs"
	"github.com/nats-io/nats.go"

	"github.com/entirehq/entire-api/internal/ingest"
	"github.com/entirehq/entire-api/internal/refstream"
	"github.com/entirehq/entire-api/internal/repoapi"
)

// refDebounceWindow bounds how long a burst of rapid updates to the SAME ref
// can be coalesced into one delivered event: the first update to a quiet ref
// schedules a flush at most this far out; any further update to that ref
// before the flush fires just replaces the pending payload (latest wins)
// instead of rescheduling the timer, so a continuously hot ref still flushes
// on a steady ~refDebounceWindow cadence rather than waiting for a quiet
// moment that never comes. A package var (not a const), matching
// ssePollInterval et al. in reviews_events_sse.go, so a test can shrink it to
// run in milliseconds.
var refDebounceWindow = 200 * time.Millisecond

// RefEventsInput is GET /repos/{repo_id}/refs/events.
type RefEventsInput struct {
	RepoID string `path:"repo_id"`
	// Prefix mirrors GET /repos/{repo_id}/refs's own repeatable prefix filter
	// verbatim (api/repov1.ListRefsInput, entiredb): query:"prefix,explode",
	// maxItems 100, empty = every ref.
	Prefix []string `query:"prefix,explode" maxItems:"100" doc:"Ref-name prefixes to filter by (repeatable), e.g. \"refs/heads/\", \"refs/tags/\", \"HEAD\" — the same convention as GET /repos/{repo_id}/refs. Empty streams every ref."`
}

// refSnapshotEntryJSON/refSnapshotData/refDeltaData are the SSE payloads,
// camelCase per CASING-001 (matching toReviewEventJSON/toThreadEventJSON).

type refSnapshotEntryJSON struct {
	Name         string `json:"name"`
	OID          string `json:"oid,omitempty"`
	SymrefTarget string `json:"symrefTarget,omitempty"`
}

type refSnapshotData struct {
	Refs []refSnapshotEntryJSON `json:"refs"`
}

// refDeltaData is one live ref-change event, projected from ingest.RefEvent.
// The SSE `event:` name is normally the ref op itself (create/update/
// force_update/delete/symref_update — entiredb's refevents.RefOp* wire
// values), mirroring the review/thread hubs' convention of using the event's
// own type as the frame name — but see refFrameEvent for why the frame name
// is validated first. RefOp is also carried in the JSON body regardless, so a
// client can always recover the real op even on the rare refFallbackOp path.
type refDeltaData struct {
	RefName         string `json:"refName"`
	RefOp           string `json:"refOp"`
	OldTarget       string `json:"oldTarget,omitempty"`
	NewTarget       string `json:"newTarget,omitempty"`
	OldSymrefTarget string `json:"oldSymrefTarget,omitempty"`
	NewSymrefTarget string `json:"newSymrefTarget,omitempty"`
	PusherID        string `json:"pusherId,omitempty"`
	EventAt         string `json:"eventAt"`
}

func toRefDeltaData(ev ingest.RefEvent) refDeltaData {
	return refDeltaData{
		RefName:         ev.RefName,
		RefOp:           ev.RefOp,
		OldTarget:       ev.OldTarget,
		NewTarget:       ev.NewTarget,
		OldSymrefTarget: ev.OldSymrefTarget,
		NewSymrefTarget: ev.NewSymrefTarget,
		PusherID:        ev.PusherID,
		EventAt:         isoMillis(ev.Timestamp),
	}
}

// refKnownOps is the closed set of ref_op wire values entiredb's envelope
// version 1 ever publishes on repo_refs_v1 (refevents.RefOp{Create,Update,
// Delete,ForceUpdate}, plus internal/ingest's own unexported
// refOpSymrefUpdate — both mirrored here as literals since neither package
// exports them for this use).
var refKnownOps = map[string]bool{
	"create": true, "update": true, "delete": true, "force_update": true,
	"symref_update": true,
}

// refFallbackOp substitutes for any ref_op outside refKnownOps.
const refFallbackOp = "ref_change"

// refFrameEvent returns refOp verbatim if it's one of refKnownOps, else
// refFallbackOp. ev.RefOp is decoded straight from an external NATS payload
// with no format check (ingest.ParseRefEvent), and sseWriter.frame
// (reviews_events_sse.go) builds a frame by raw string concatenation with no
// escaping — unlike the DB-polling hubs, whose event: name always comes from
// an internal, store-constrained enum. Without this check, a ref_op
// containing "\n"/"\r" would inject extra lines into the frame, corrupting it
// for every connection sharing that repo's hub. The real value is never lost
// even on the fallback path — refDeltaData.RefOp (JSON-escaped, so safe
// regardless of its content) always carries it too.
func refFrameEvent(refOp string) string {
	if refKnownOps[refOp] {
		return refOp
	}
	return refFallbackOp
}

// ---- shared per-repo push drain ----

// refEventHubs is shared so a repo costs one NATS subscription per replica.
func (deps *RepoActivityDeps) refEventHubs() *refHubRegistry {
	deps.refHubsOnce.Do(func() {
		deps.refHubs = newRefHubRegistry(func(ctx context.Context, repoID string) (<-chan ingest.RefEvent, func(), error) {
			return refstream.Subscribe(ctx, deps.RefEventsNATS, repoID)
		})
		deps.refHubs.reconnected = func() (<-chan nats.Status, func()) {
			return refstream.Reconnected(deps.RefEventsNATS)
		}
	})
	return deps.refHubs
}

// refHubRegistry maps a repo_id to its live per-replica ref-events hub,
// ref-counted so a hub is created (and subscribed) on the first connection
// and torn down when the last leaves — the push-driven counterpart of
// changeHubRegistry (reviews_events_sse.go): one shared NATS subscription per
// repo, never one per connection.
type refHubRegistry struct {
	mu          sync.Mutex
	hubs        map[string]*refHub
	subscribe   func(ctx context.Context, repoID string) (<-chan ingest.RefEvent, func(), error)
	reconnected func() (<-chan nats.Status, func())
}

func newRefHubRegistry(subscribe func(ctx context.Context, repoID string) (<-chan ingest.RefEvent, func(), error)) *refHubRegistry {
	return &refHubRegistry{hubs: map[string]*refHub{}, subscribe: subscribe}
}

// acquire returns the live hub for repoID, subscribing and starting it on the
// first connection. Each successful acquire must be paired with a release.
// Unlike changeHubRegistry.acquire, this can fail — the underlying NATS
// subscribe call can itself error (e.g. a permissions violation) — in which
// case no hub is registered, so a subsequent connection gets a fresh attempt
// rather than being stuck sharing a broken one.
func (r *refHubRegistry) acquire(repoID string) (*refHub, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if h := r.hubs[repoID]; h != nil {
		h.refs++
		return h, nil
	}
	// The hub's subscription must outlive whichever connection happens to
	// create it, so it is subscribed under its OWN long-lived context, never
	// the first caller's request context (cancelled the moment that caller
	// disconnects, which must not tear down a subscription later callers are
	// now also relying on).
	hubCtx, cancel := context.WithCancel(context.Background())
	ch, unsub, err := r.subscribe(hubCtx, repoID)
	if err != nil {
		cancel()
		return nil, err
	}
	h := newRefHub(repoID, ch, unsub, hubCtx, cancel)
	if r.reconnected != nil {
		h.reconnected, h.unwatch = r.reconnected()
	}
	r.hubs[repoID] = h
	h.refs = 1
	h.start()
	return h, nil
}

// release drops one reference to h; when the last connection leaves, the hub
// is removed from the registry and its subscription torn down. A fresh
// connection arriving concurrently takes r.mu, doesn't find the removed hub,
// and starts a new one — so a stopping hub is never handed out.
func (r *refHubRegistry) release(h *refHub) {
	r.mu.Lock()
	h.refs--
	stop := h.refs <= 0
	if stop {
		delete(r.hubs, h.repoID)
	}
	r.mu.Unlock()
	if stop {
		h.stop()
	}
}

// refHub is one shared per-repo live ref-events drainer (per replica): it
// owns the repo's NATS subscription, debounces rapid updates to the same ref
// (refDebounceWindow), and fans each debounced event out to every connection
// watching the repo (filtered by that connection's own prefix set at
// delivery) — so N viewers of a hot repo cost one subscription, not N. Its
// subscription outlives any single request, running under its own context
// (cancelled by stop), never a request context.
type refHub struct {
	repoID      string
	sub         <-chan ingest.RefEvent
	unsub       func()
	ctx         context.Context
	cancel      context.CancelFunc
	done        chan struct{} // closed when the drain goroutine exits (stop waits on it)
	reconnected <-chan nats.Status
	unwatch     func()

	refs int // guarded by the owning registry's mu

	mu      sync.Mutex
	conns   map[*refHubConn]struct{}
	pending map[string]ingest.RefEvent // ref_name -> latest event awaiting its debounce flush; presence IS "a flush is already scheduled"
}

func newRefHub(repoID string, sub <-chan ingest.RefEvent, unsub func(), ctx context.Context, cancel context.CancelFunc) *refHub {
	return &refHub{
		repoID: repoID, sub: sub, unsub: unsub, ctx: ctx, cancel: cancel,
		done:    make(chan struct{}),
		conns:   map[*refHubConn]struct{}{},
		pending: map[string]ingest.RefEvent{},
	}
}

func (h *refHub) start() { go h.run() }

// stop cancels the hub, tears down its NATS subscription, and waits for the
// drain goroutine to exit — so a released hub is fully quiesced before its
// slot is reused. Any debounce timer still pending at this point fires
// harmlessly afterward (within refDebounceWindow) and no-ops via flush's own
// h.ctx.Err() guard, so there's nothing further to cancel here.
func (h *refHub) stop() {
	h.cancel()
	h.unsub()
	<-h.done
	if h.unwatch != nil {
		h.unwatch()
	}
}

// run drains the shared NATS subscription until the hub is stopped,
// debouncing each ref through scheduleFlush. Unlike the DB-polling hubs' run
// loop, there is no poll cadence or backoff here — delivery is purely
// event-driven off the channel refstream.Subscribe returns; refstream itself
// logs and drops anything it can't parse, so every value received here is a
// valid ingest.RefEvent.
func (h *refHub) run() {
	defer close(h.done)
	for {
		select {
		case <-h.ctx.Done():
			return
		case ev := <-h.sub:
			h.scheduleFlush(ev)
		case _, ok := <-h.reconnected:
			if !ok {
				h.reconnected = nil
				continue
			}
			h.ring()
		}
	}
}

// ring wakes every connection after a reconnect: what moved meanwhile was
// never published.
func (h *refHub) ring() {
	h.mu.Lock()
	defer h.mu.Unlock()
	for c := range h.conns {
		c.signal()
	}
}

// scheduleFlush implements the leaky-bucket debounce described at the top of
// this file: the first update to a quiet ref schedules flush() at most
// refDebounceWindow out; a further update to that same ref before the timer
// fires just replaces the pending payload without rescheduling, bounding the
// worst-case delivery latency for any single update to refDebounceWindow
// regardless of how hot the ref is. Whether a flush is already scheduled is
// read directly off h.pending (its presence for this ref IS the scheduled
// state) rather than a second timers map kept in lockstep with it. Doorbells
// are rung here, as the event arrives, and left out of the flush.
func (h *refHub) scheduleFlush(ev ingest.RefEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for c := range h.conns {
		if c.doorbell {
			c.deliver(ev)
		}
	}
	_, alreadyScheduled := h.pending[ev.RefName]
	h.pending[ev.RefName] = ev
	if alreadyScheduled {
		return
	}
	refName := ev.RefName // captured alone, not ev, so the timer doesn't keep the whole event alive
	time.AfterFunc(refDebounceWindow, func() { h.flush(refName) })
}

// flush delivers the latest pending event for refName to every connection
// currently watching this hub and clears the debounce state for that ref.
// Delivery runs inside the same h.mu critical section as the pending-map
// read: refHubConn.deliver only ever takes its own c.mu, never h.mu, so this
// can't deadlock, and it avoids copying the connection set to a slice on
// every flush (this fires per distinct ref about every refDebounceWindow, not
// a rare event) at the cost of briefly serializing flush against
// add/remove/scheduleFlush.
func (h *refHub) flush(refName string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.ctx.Err() != nil {
		return // hub stopping/stopped; every connection is already gone or going
	}
	ev, ok := h.pending[refName]
	delete(h.pending, refName)
	if !ok {
		return
	}
	for c := range h.conns {
		if !c.doorbell {
			c.deliver(ev)
		}
	}
}

func (h *refHub) add(prefixes []string) *refHubConn { return h.join(prefixes, false) }

// addDoorbell is add, rung as each event arrives rather than debounced (see the
// file header).
func (h *refHub) addDoorbell(prefixes []string) *refHubConn { return h.join(prefixes, true) }

func (h *refHub) join(prefixes []string, doorbell bool) *refHubConn {
	c := &refHubConn{prefixes: prefixes, doorbell: doorbell, pending: map[string]ingest.RefEvent{}, wake: make(chan struct{}, 1)}
	h.mu.Lock()
	h.conns[c] = struct{}{}
	h.mu.Unlock()
	return c
}

func (h *refHub) remove(c *refHubConn) {
	h.mu.Lock()
	delete(h.conns, c)
	h.mu.Unlock()
}

// refHubConn is one connection's state within a refHub: its own prefix
// filter and a single-slot-per-ref mailbox of undelivered events. Because the
// hub already debounces each ref to "latest wins" before delivery, a
// connection never needs a growing queue — if it hasn't drained the previous
// delivery for a ref before a new one arrives, the mailbox just holds the
// newer one (still "latest wins", now applied per-connection too), so no
// separate backpressure/slow-consumer policy is needed beyond this map.
type refHubConn struct {
	prefixes []string // nil/empty = every ref
	doorbell bool     // delivered undebounced (addDoorbell)

	mu      sync.Mutex
	pending map[string]ingest.RefEvent
	wake    chan struct{} // buffered(1)
}

func (c *refHubConn) signal() { signalWake(c.wake) }

// matches reports whether refName passes this connection's prefix filter (no
// filter → everything) — the same prefix semantics as GET /repos/{repo_id}/refs.
func (c *refHubConn) matches(refName string) bool {
	if len(c.prefixes) == 0 {
		return true
	}
	for _, p := range c.prefixes {
		if strings.HasPrefix(refName, p) {
			return true
		}
	}
	return false
}

func (c *refHubConn) deliver(ev ingest.RefEvent) {
	if !c.matches(ev.RefName) {
		return
	}
	c.mu.Lock()
	c.pending[ev.RefName] = ev
	c.mu.Unlock()
	c.signal()
}

// drain empties and returns the connection's pending mailbox, or nil without
// allocating a replacement map when it's already empty — called every
// ~1s tick from refConnLoop for every open connection, so an idle connection
// (the common case between debounce flushes) shouldn't cost an allocation.
// Ranging over a nil map is a no-op, so callers need no special case.
func (c *refHubConn) drain() map[string]ingest.RefEvent {
	c.mu.Lock()
	defer c.mu.Unlock()
	if len(c.pending) == 0 {
		return nil
	}
	batch := c.pending
	c.pending = map[string]ingest.RefEvent{}
	return batch
}

// ---- per-connection stream ----

// refEventsSnapshot fetches a connection's initial ref state — a live
// entiredb ListRefsWithSymrefs read (NOT repo_branch_tip, which only tracks
// branches and never resolves symref targets), filtered by the connection's
// own requested prefixes. symrefs=true so a HEAD entry's SymrefTarget
// (refSnapshotEntryJSON) is actually populated, matching what the field
// promises.
type refEventsSnapshot func(ctx context.Context, prefixes []string) ([]repoapi.RefEntry, error)

