// Command refevents measures how long a record takes to become readable in
// another clone, when the reader is woken by the remote's own ref-change events
// rather than by a poll.
//
// Two clones of one store, in one process, on opposite sides of the wire:
//
//	writer ──append──▶ local refs ──push──▶ remote ──ref event──▶ reader
//	                                          │                     │
//	                                          └───────fetch─────────┘
//
// The point is what the reader does *not* do. It never polls the remote on a
// timer, and it never reads a value out of an event. It waits to be told that
// something moved, then fetches and folds — so the stream is a latency
// optimisation over a correct-but-slow loop, not a source of truth. That is what
// lets it stay correct under a signal that coalesces bursts, replays no history,
// keeps no cursor, and re-snapshots on reconnect. See events.go.
//
// # How the number is arrived at
//
// The writer puts the time it is about to commit into the record itself; the
// reader subtracts that from the time the value became visible in its read
// model. Both readings come from one process on one machine, so the subtraction
// is a duration and not a comparison of two clocks — which is the only reason
// this is worth measuring this way. Split the two halves across machines and the
// number would be measuring NTP skew as much as anything else.
//
// What it therefore includes, end to end: a local commit, a push to the remote,
// the remote's own ref-event fan-out, the reader's fetch, and the fold into a
// read model. The second half of that — from being woken to the value being
// visible — is timed separately and reported alongside, because it is the half
// that is this library's to answer for. The rest is the network and the host.
//
// This is the remote sibling of `mise run latency`, which measures the same
// question without a wire: how long a write takes to become readable in SQL in
// the clone that wrote it.
//
// Run it against a real repository:
//
//	go run ./refevents \
//	  -repo et/your-org/your-repo \
//	  -remote entire://aws-ap-southeast-2.entire.io/et/your-org/your-repo \
//	  -token "$(entire auth token -j au)"
//
// It writes real records under refs/strata/<store>/ and prints what the reader
// sees. -clean removes them again on the way out.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"os"
	"os/signal"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/entirehq/strata/examples/gogit"
	"github.com/entirehq/strata/git"
	"github.com/entirehq/strata/gitbin"
	"github.com/entirehq/strata/project"
	"github.com/entirehq/strata/record"
	"github.com/entirehq/strata/reflayout"
	"github.com/entirehq/strata/settings"
	"github.com/entirehq/strata/store"
)

func main() {
	var (
		api      = flag.String("api", "https://aws-ap-southeast-2.api.entire.io/api/v1", "API root, including its version prefix")
		repoPath = flag.String("repo", "", "repository path to resolve, e.g. et/org/name")
		repoID   = flag.String("repo-id", "", "repository id, if you already have it (skips resolving)")
		remote   = flag.String("remote", "", "git remote URL the writer pushes to")
		token    = flag.String("token", os.Getenv("ENTIRE_TOKEN"), "bearer token; defaults to $ENTIRE_TOKEN")
		name     = flag.String("store", "refevents", "store name, which decides the ref prefix")
		every    = flag.Duration("every", 2*time.Second, "how often the writer appends and pushes")
		rounds   = flag.Int("rounds", 5, "how many pushes the writer makes before stopping")
		batch    = flag.Int("batch", 1, "records per push — the lever, since cost is per push and not per record")
		clean    = flag.Bool("clean", true, "withdraw this store's refs from the remote on the way out")
		via      = flag.String("transport", "gitbin", "how to reach the remote: gitbin (forks git) or gogit (in-process)")
	)
	flag.Parse()
	if *remote == "" || *token == "" || (*repoPath == "" && *repoID == "") {
		flag.Usage()
		log.Fatal("need -remote, -token, and one of -repo or -repo-id")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	id := *repoID
	if id == "" {
		var err error
		if id, err = resolve(ctx, *api, *token, *repoPath); err != nil {
			log.Fatalf("resolving %s: %v", *repoPath, err)
		}
	}

	// The two transports do not dial the same URLs, and that is not an accident
	// of configuration. entire:// is a remote-helper scheme — an instruction to
	// run git-remote-entire, which only the git binary knows to do — so gogit
	// needs the smart-HTTP endpoint that helper would have dialled, plus the
	// credential it would have minted. See examples/gogit.
	var tp git.Transport
	switch *via {
	case "gitbin":
		tp = gitbin.Transport{}
	case "gogit":
		tp = gogit.Transport{Client: &http.Client{Transport: bearer{token: *token}}}
	default:
		log.Fatalf("unknown -transport %q; want gitbin or gogit", *via)
	}

	dir, err := os.MkdirTemp("", "refevents-")
	if err != nil {
		log.Fatal(err)
	}
	defer os.RemoveAll(dir)

	// Two clones, because that is the interesting shape: the reader must learn
	// about the writer's work the way any other clone would, through the remote.
	// A store's refs live under one prefix, and reflayout is what says which —
	// the same value the watcher filters the stream by, so the reader is woken
	// for this store's pushes and nobody else's.
	layout := reflayout.For(*name)
	prefix := layout.Root().Prefix() + "/"

	writer, err := open(dir, "writer", *name, *remote, tp)
	if err != nil {
		log.Fatalf("writer: %v", err)
	}
	reader, err := open(dir, "reader", *name, *remote, tp)
	if err != nil {
		log.Fatalf("reader: %v", err)
	}

	log.Printf("repo %s, store %q, watching %s, transport %s", id, *name, prefix, *via)

	var wg sync.WaitGroup
	writing, cancelWriting := context.WithCancel(ctx)
	defer cancelWriting()

	wg.Add(1)
	go func() {
		defer wg.Done()
		defer cancelWriting()
		if err := stream(writing, writer, *every, *rounds, *batch); err != nil && !errors.Is(err, context.Canceled) {
			log.Printf("writer: %v", err)
		}
	}()

	samples := make(chan sample, 1024)
	var collected []sample
	var collect sync.WaitGroup
	collect.Add(1)
	go func() {
		defer collect.Done()
		for s := range samples {
			collected = append(collected, s)
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		follow(writing, reader, Watcher{
			BaseURL:  *api,
			Token:    *token,
			RepoID:   id,
			Prefixes: []string{prefix},
			// No client timeout: the stream is meant to stay open, and the
			// context is what bounds it.
			Client: &http.Client{},
		}, samples)
	}()

	wg.Wait()
	collect.Wait()
	report(collected)
	if *clean {
		withdraw(filepath.Join(dir, "writer"), layout, tp)
	}
}

// open prepares one clone of the store, pointed at the remote.
func open(root, who, name, remote string, tp git.Transport) (*store.Store, error) {
	dir := filepath.Join(root, who)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	// The driver is the binary either way: every primitive a local repository
	// needs — create-if-absent compare-and-swap, a real ref transaction — is one
	// go-git's reference store does not offer. Only the wire is swappable, which
	// is exactly the split docs/adr/0020 makes.
	return store.Prepare(gitbin.Driver{}, tp, dir, name, settings.Settings{}, remote)
}

// bearer attaches the token to every request the transport makes.
type bearer struct{ token string }

func (b bearer) RoundTrip(r *http.Request) (*http.Response, error) {
	r = r.Clone(r.Context())
	r.Header.Set("Authorization", "Bearer "+b.token)
	return http.DefaultTransport.RoundTrip(r)
}

// stream is the writer: append a record, publish it, repeat.
//
// Nothing here knows the reader exists. A push is the only thing it does that
// anyone else can observe, which is the property the whole arrangement rests on.
// A push costs what a push costs, whatever it carries.
//
// One advertisement of every ref on the remote, one receive-pack, one packfile —
// and on a host that locks per repository for a create-bearing push, one
// acquisition of that lock. None of it divides by the number of records in the
// batch, which makes batch size the only lever there is. It is not connection
// reuse: a receive-pack session serves exactly one push and cannot be reused,
// so "several updates down one connection" already means "one push carrying
// several refs", which is what a batch is.
func stream(ctx context.Context, s *store.Store, every time.Duration, rounds, batch int) error {
	tick := time.NewTicker(every)
	defer tick.Stop()
	for i := range rounds {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-tick.C:
		}
		// One draft, every record in the batch: the whole batch is stamped at
		// the same moment and lands in one commit and one push.
		draft := s.Begin()
		body := strconv.FormatInt(time.Now().UnixNano(), 10)
		for b := range batch {
			draft.Set("note", fmt.Sprintf("m%03d-%02d", i, b), "body", []byte(body))
		}
		if err := draft.Commit(); err != nil {
			return fmt.Errorf("writing batch %d: %w", i, err)
		}
		if err := s.Push("origin"); err != nil {
			return fmt.Errorf("publishing batch %d: %w", i, err)
		}
		log.Printf("writer  ── pushed %d record(s) in one push", batch)
	}
	// A moment for the last push's event to arrive before the reader is stopped.
	select {
	case <-ctx.Done():
	case <-time.After(3 * time.Second):
	}
	return nil
}

// follow is the reader: wait to be told something moved, then go and look.
//
// The two halves are deliberately separate. Watch decides *when* to look and
// knows nothing about records; drain decides *what changed* and knows nothing
// about the stream. Neither reads a value out of an event.
func follow(ctx context.Context, s *store.Store, w Watcher, samples chan<- sample) {
	sink := project.NewMemory()
	var cursor project.Cursor
	seen := map[record.Key]bool{}

	look := make(chan string, 1)
	go func() {
		_ = w.Watch(ctx, func(ev Event) {
			what := ev.Name
			if ev.RefName != "" {
				what = fmt.Sprintf("%s %s", ev.RefOp, ev.RefName)
			}
			// Coalescing on purpose: several events while a fetch is in flight
			// collapse into one more look, because looking twice for one push
			// costs a round trip and tells you nothing new. It also means a
			// sample's measured latency is never inflated by queueing behind a
			// fetch that was already going to cover it.
			select {
			case look <- what:
			default:
			}
		})
	}()

	for {
		select {
		case <-ctx.Done():
			close(samples)
			return
		case what := <-look:
			woke := time.Now()
			n, touched, err := drain(s, sink, &cursor)
			visible := time.Now()
			if err != nil {
				log.Printf("reader  ── woken by %s, but: %v", what, err)
				continue
			}
			if n == 0 {
				log.Printf("reader  ── woken by %s, nothing new", what)
				continue
			}
			fresh := 0
			var slowest time.Duration
			for _, k := range touched {
				if seen[k] {
					continue
				}
				v, ok := sink.Visible(k, "body")
				if !ok {
					continue
				}
				written, convErr := strconv.ParseInt(string(v.Bytes), 10, 64)
				if convErr != nil {
					continue
				}
				seen[k] = true
				fresh++
				total := visible.Sub(time.Unix(0, written))
				samples <- sample{key: k, total: total, read: visible.Sub(woke)}
				slowest = max(slowest, total)
			}
			switch {
			case fresh == 0:
				log.Printf("reader  ── woken by %s, %d op(s), nothing newly visible", what, n)
			default:
				// One line per wake-up rather than per record: a batch of a
				// hundred arrives together and shares a latency, so a line each
				// would be a hundred copies of one fact.
				log.Printf("reader  ── woken by %s, %d record(s) readable, slowest %s (%s of that fetch+fold)",
					what, fresh, slowest.Round(time.Millisecond), visible.Sub(woke).Round(time.Millisecond))
			}
		}
	}
}

// sample is one record's journey, timed.
type sample struct {
	key record.Key
	// total is write to readable-elsewhere: commit, push, the host's ref-event
	// fan-out, the fetch it triggered, and the fold.
	total time.Duration
	// read is the tail of that — from being woken to the value being visible —
	// which is the part this library answers for rather than the network.
	read time.Duration
}

// report prints the distribution, which is the output that matters. A mean would
// hide the thing worth knowing: this path has a floor set by a round trip and a
// tail set by whatever the host was doing at the time.
func report(samples []sample) {
	if len(samples) == 0 {
		log.Print("no samples: nothing became readable")
		return
	}
	totals := make([]time.Duration, len(samples))
	reads := make([]time.Duration, len(samples))
	for i, s := range samples {
		totals[i], reads[i] = s.total, s.read
	}
	sort.Slice(totals, func(i, j int) bool { return totals[i] < totals[j] })
	sort.Slice(reads, func(i, j int) bool { return reads[i] < reads[j] })

	log.Printf("%d samples", len(samples))
	log.Printf("  write ─▶ readable elsewhere   min %s  p50 %s  p95 %s  max %s",
		ms(totals[0]), ms(pick(totals, 0.50)), ms(pick(totals, 0.95)), ms(totals[len(totals)-1]))
	log.Printf("    of which fetch+fold         min %s  p50 %s  p95 %s  max %s",
		ms(reads[0]), ms(pick(reads, 0.50)), ms(pick(reads, 0.95)), ms(reads[len(reads)-1]))
}

// pick is the nearest-rank percentile of a sorted slice.
func pick(sorted []time.Duration, q float64) time.Duration {
	if len(sorted) == 0 {
		return 0
	}
	i := int(q * float64(len(sorted)))
	if i >= len(sorted) {
		i = len(sorted) - 1
	}
	return sorted[i]
}

func ms(d time.Duration) string { return d.Round(time.Millisecond).String() }

// drain fetches what the remote has and folds it into the read model.
//
// Looped until a batch moves nothing, because one wake-up may cover several
// pushes: the stream coalesces, and a fetch can land more than the event that
// prompted it was about. The cursor is what makes that safe to repeat.
//
// It returns the keys the batch touched, which is the only thing the caller
// needs in order to print what changed — and note where they come from: the
// batch, not the event.
func drain(s *store.Store, sink *project.Memory, cursor *project.Cursor) (int, []record.Key, error) {
	if err := s.Fetch("origin"); err != nil {
		return 0, nil, fmt.Errorf("fetch: %w", err)
	}
	applied := 0
	seen := map[record.Key]bool{}
	var touched []record.Key
	note := func(k record.Key) {
		if !seen[k] {
			seen[k] = true
			touched = append(touched, k)
		}
	}
	for {
		batch, err := s.Feed(*cursor)
		if err != nil {
			return applied, touched, fmt.Errorf("feed: %w", err)
		}
		next, err := project.Apply(sink, batch)
		if err != nil {
			return applied, touched, fmt.Errorf("apply: %w", err)
		}
		for _, op := range batch.Ops {
			note(op.Key())
		}
		for _, sd := range batch.Seed {
			note(sd.Key)
		}
		moved := len(batch.Ops) + len(batch.Seed)
		applied += moved
		*cursor = next
		if moved == 0 {
			return applied, touched, nil
		}
	}
}

// withdraw removes this store's refs from the remote, so a demo run leaves
// nothing behind.
//
// Straight through the transport seam rather than through the store, because
// this is not a store operation — retiring a writer is, and that is a different
// thing with a barrier to respect. What this wants is the plain wire verb, and
// git.Transport is where that lives. Publishing is <ref>:<ref> and withdrawing
// is the same string with the left side left off, which is precisely why Push
// takes two lists instead of composed refspecs.
func withdraw(dir string, layout reflayout.Layout, tp git.Transport) {
	repo, err := gitbin.Open(dir)
	if err != nil {
		log.Printf("clean: %v", err)
		return
	}
	refs, err := tp.LsRemote(repo, "origin", layout.Root().Prefix())
	if err != nil {
		log.Printf("clean: listing: %v", err)
		return
	}
	doomed := make([]string, 0, len(refs))
	for ref := range refs {
		doomed = append(doomed, ref)
	}
	if len(doomed) == 0 {
		return
	}
	if err := tp.Push(repo, "origin", nil, git.Unleased(doomed...)); err != nil {
		log.Printf("clean: %v", err)
		return
	}
	log.Printf("cleaned %d ref(s) from the remote", len(doomed))
}

// resolve turns a repository path into the id the event stream is keyed by.
func resolve(ctx context.Context, api, token, path string) (string, error) {
	u := fmt.Sprintf("%s/git/repos/resolve?repoPath=%s", strings.TrimRight(api, "/"), url.QueryEscape(path))
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("resolve: %s", resp.Status)
	}
	var body struct {
		RepoID string `json:"repoId"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return "", err
	}
	if body.RepoID == "" {
		return "", fmt.Errorf("resolve: no repoId for %q", path)
	}
	return body.RepoID, nil
}

package main

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// A ref event is a doorbell, not a delivery.
//
// This is the whole design of the reader below, and it is what makes an
// at-most-once live signal enough. The stream promises very little: rapid
// updates to one ref are coalesced to at most one event every ~200ms, there is
// no history and no cursor, and a reconnect re-snapshots rather than catching up
// on what it missed. Every one of those would be a problem for a consumer that
// treated events as the data.
//
// None of them is a problem for a consumer that treats an event as "something
// moved, go and look". The refs on the remote are the truth; the event only says
// when it is worth paying for a fetch. Miss one and the next one still leads to
// the same fetch. Get two for one push and the second fetch finds nothing new.
// Reconnect and the snapshot frame is just another prompt to look.
//
// The alternative — reading refName/newTarget out of the payload and treating it
// as state — would inherit every one of the stream's weaknesses as a correctness
// bug, and would do it silently.

// Event is one frame from the ref-event stream.
//
// Carried in full because it is useful to print, and deliberately not used to
// decide anything: see the note above. RefOp is also in the body rather than
// only in the SSE frame name, because the server substitutes a safe frame name
// for any op it does not recognise and keeps the real one here.
type Event struct {
	Name string // the SSE frame name: snapshot, create, update, delete, ...

	RefName         string `json:"refName"`
	RefOp           string `json:"refOp"`
	OldTarget       string `json:"oldTarget"`
	NewTarget       string `json:"newTarget"`
	OldSymrefTarget string `json:"oldSymrefTarget"`
	NewSymrefTarget string `json:"newSymrefTarget"`
	PusherID        string `json:"pusherId"`
	EventAt         string `json:"eventAt"`

	// Refs is the snapshot frame's body, sent once when a connection opens.
	Refs []struct {
		Name         string `json:"name"`
		OID          string `json:"oid"`
		SymrefTarget string `json:"symrefTarget"`
	} `json:"refs"`
}

// Watcher subscribes to a repository's ref-event stream.
type Watcher struct {
	// BaseURL is the API root, including its version prefix.
	BaseURL string
	Token   string
	RepoID  string
	// Prefixes filters the stream server-side, in the same dialect the ref
	// listing takes. Worth setting: a repository's branches and tags move for
	// reasons a record store does not care about, and every one of them would
	// otherwise cost a wasted fetch.
	Prefixes []string
	// Client is optional; http.DefaultClient is used when nil. A long-lived
	// stream wants no timeout on the client itself — bound it with the context.
	Client *http.Client
}

// Watch calls ring for every frame until ctx ends, reconnecting on its own.
//
// Reconnection is not error handling here, it is the normal path: the server
// closes a connection after a bounded lifetime and says so with a reconnect
// frame. Because the reader re-derives its state from the store rather than from
// the stream, a gap between connections costs nothing but latency.
func (w Watcher) Watch(ctx context.Context, ring func(Event)) error {
	backoff := 250 * time.Millisecond
	for ctx.Err() == nil {
		err := w.connect(ctx, ring)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if err != nil {
			// Ring anyway. A connection that dropped may have dropped mid-push,
			// and the cheapest way to find out is to look rather than to reason
			// about it.
			ring(Event{Name: "reconnect"})
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(backoff):
		}
		if backoff < 5*time.Second {
			backoff *= 2
		}
	}
	return ctx.Err()
}

func (w Watcher) connect(ctx context.Context, ring func(Event)) error {
	q := url.Values{}
	for _, p := range w.Prefixes {
		q.Add("prefix", p)
	}
	endpoint := fmt.Sprintf("%s/repos/%s/refs/events", strings.TrimRight(w.BaseURL, "/"), url.PathEscape(w.RepoID))
	if len(q) > 0 {
		endpoint += "?" + q.Encode()
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+w.Token)
	req.Header.Set("Accept", "text/event-stream")

	cl := w.Client
	if cl == nil {
		cl = http.DefaultClient
	}
	resp, err := cl.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
		return fmt.Errorf("refs/events: %s: %s", resp.Status, strings.TrimSpace(string(body)))
	}
	return parse(resp.Body, ring)
}

// parse reads server-sent events and calls ring once per complete frame.
//
// Only the two line kinds this stream uses are handled — "event:" and "data:" —
// plus comments, which is what the heartbeat is (": ping <millis>"). A blank
// line ends a frame. Anything else is skipped rather than refused: a stream that
// gained a field should not stop a reader that does not need it.
func parse(r io.Reader, ring func(Event)) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	var name, data string
	for sc.Scan() {
		line := sc.Text()
		switch {
		case line == "":
			if name != "" || data != "" {
				ev := Event{Name: name}
				if data != "" {
					// A frame whose body will not parse is still a prompt to
					// look, which is the one thing this reader needs from it.
					_ = json.Unmarshal([]byte(data), &ev)
				}
				ring(ev)
			}
			name, data = "", ""
		case strings.HasPrefix(line, ":"):
			// A heartbeat. It proves the connection is alive and means nothing
			// moved, so it is deliberately not a prompt to fetch.
		case strings.HasPrefix(line, "event:"):
			name = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
		case strings.HasPrefix(line, "data:"):
			data += strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		}
	}
	return sc.Err()
}

// Package authz decides whether a push may touch the refs it names.
//
// Write access to a repository is push access to every store in it. Nothing in
// the record protocol changes that: a store's refs are ordinary refs and git has
// no per-ref authorization. So the boundary a group actually gets is whatever the
// server enforces at receive time, and this package is the decision that
// enforcement makes — a pure function of a policy, an identity and the ref
// updates a push proposes.
//
// It is deliberately not a signing scheme. Signatures answer "who wrote this
// value", survive compaction, and are checked by readers; that lives on the
// record and outside the protocol. This answers "who may move this ref", is
// checked once at push time by the server, and protects the parts of the layout
// that no later reader could tell had been tampered with.
package authz

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/entirehq/strata/reflayout"
)

// Update is one line of what a push proposes: a ref, what the server holds, and
// what the push would leave there. Old is all zeros for a creation and New is all
// zeros for a deletion, which is git's own convention on a hook's stdin.
type Update struct {
	Ref string
	Old string
	New string
}

// Creating reports whether the ref does not exist on the server yet.
func (u Update) Creating() bool { return isZero(u.Old) }

// Deleting reports whether the push would remove the ref.
func (u Update) Deleting() bool { return isZero(u.New) }

// isZero accepts both object-id widths, since a repository may be sha1 or sha256
// and a hook that only knew one would wave every creation through in the other.
func isZero(oid string) bool {
	if len(oid) != 40 && len(oid) != 64 {
		return false
	}
	return strings.Trim(oid, "0") == ""
}

// Rejection is one ref a push may not have, and why. Every rejected ref is
// reported rather than the first, because a push is atomic: the pusher will fix
// them all or none, and a hook that reveals one problem per attempt turns a
// misconfiguration into an afternoon.
type Rejection struct {
	Ref    string
	Reason string
}

func (r Rejection) String() string { return r.Ref + ": " + r.Reason }

// Policy is who may move what.
//
// Patterns are literal ref names, or a prefix ending in "/*" matching anything
// below it. There is no other globbing, and that is a decision rather than an
// omission: a pattern language with wildcards in the middle is where
// authorization bugs live, and every rule this layout needs is a prefix.
type Policy struct {
	allow map[string][]rule
}

// direction is which way a ref may move: brought into existence, taken out of it,
// or moved from one value to another.
//
// A dimension the pattern language does not have and does not need — every rule
// this layout wants is a prefix — but which a *breadth* of pattern does. Granting
// somebody every writer's log is only reasonable if what they may do to one is
// end it: a deletion is loud, because the ref is gone and Check reports what
// dangles, where a forged append is silent and attributed to somebody else.
type direction uint8

const (
	creating direction = 1 << iota
	deleting
	updating

	anyDirection = creating | deleting | updating
)

// directionOf reads which way an update moves a ref, from git's own convention
// on the hook's stdin.
func directionOf(u Update) direction {
	switch {
	case u.Creating():
		return creating
	case u.Deleting():
		return deleting
	default:
		return updating
	}
}

// rule is one pattern and the directions it covers.
type rule struct {
	pattern string
	allows  direction
}

// Parse reads a policy.
//
// Line-oriented and dull, because the real control here is a person reading a
// diff of it. A format that needs a tool to see what changed is a format where a
// grant slips through review.
//
//	# comments and blank lines are ignored
//	allow alice refs/strata/alpha/log/W1/*
//	allow alice refs/strata/alpha/announced/W1
//	allow alice refs/strata/alpha/evicted/W1
//	allow alice refs/strata/alpha/gen/*
func Parse(b []byte) (*Policy, error) {
	p := &Policy{allow: map[string][]rule{}}
	for n, line := range strings.Split(string(b), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) != 3 {
			return nil, fmt.Errorf("authz: line %d: want \"<rule> <identity> <ref-pattern>\", got %q", n+1, line)
		}
		allows, ok := rules[fields[0]]
		if !ok {
			return nil, fmt.Errorf("authz: line %d: unknown rule %q, want one of %s", n+1, fields[0], ruleWords())
		}
		identity, pattern := fields[1], fields[2]
		if !strings.HasPrefix(pattern, "refs/") {
			return nil, fmt.Errorf("authz: line %d: %q is not a ref pattern", n+1, pattern)
		}
		// A bare "*" would be a wildcard nobody meant to write as one.
		if i := strings.IndexByte(pattern, '*'); i >= 0 && pattern[max(i-1, 0):] != "/*" {
			return nil, fmt.Errorf("authz: line %d: %q may only end in \"/*\"", n+1, pattern)
		}
		p.allow[identity] = append(p.allow[identity], rule{pattern: pattern, allows: allows})
	}
	return p, nil
}

// Grant is the lines one writer of one store needs.
//
// Generated rather than typed, because the ref layout is this protocol's business
// and a policy file that spells it out by hand is a second, silently diverging
// copy of it. It is also the shape of the mistake worth designing out: granting
// `refs/strata/<store>/*` to a member hands them every other member's log.
//
// Which refs those are is reflayout's to say, and this is the whole of what
// changed when it became so: the layout grew an eviction ref, this function did
// not, and every push of one was refused for as long as the two were separate
// copies. Rendering rather than retyping is the difference between a grant that
// can fall behind the layout and one that cannot.
func Grant(identity, store, writer string) []string {
	patterns := reflayout.For(store).Grant(writer)
	out := make([]string, len(patterns))
	for i, p := range patterns {
		out[i] = fmt.Sprintf("allow %s %s", identity, p)
	}
	return out
}

// Operator is the lines an identity needs to end writers that are not itself.
//
// Evict and Retire act on somebody else's refs, so Grant cannot express them: it
// is scoped to one writer by construction, and permitting an operator to end W2
// by handing it W2's own lines is impersonation with extra steps.
//
// So the patterns are broad and the verb is not. ADR-0012 refused a store-wide
// grant because it "hands every member every other member's log", and it was
// right about the danger and one word off about where it lives: the danger is
// update. Ending a writer creates an eviction and deletes refs, and never moves
// one from one value to another — so an operator holding these can end anybody
// and speak as nobody. Withholding update is what makes the breadth affordable.
//
// What it still permits is destruction. Retire refuses to delete a log the
// newest generation does not yet cover, but that check runs in the client, and
// this decision is a pure function with no git in it — so the server cannot
// repeat it. An operator can destroy an unfolded log, which is inherent to
// giving anyone retire powers rather than a hole in this.
func Operator(identity, store string) []string {
	l := reflayout.For(store)
	var out []string
	add := func(word string, p reflayout.Pattern) {
		out = append(out, fmt.Sprintf("%s %s %s", word, identity, p))
	}
	// Evict creates an eviction; Retire deletes it along with the rest.
	add("allow-create", l.EveryEviction().Pattern())
	add("allow-delete", l.EveryEviction().Pattern())
	add("allow-delete", l.EveryAnnouncement().Pattern())
	add("allow-delete", l.EveryLog().Pattern())
	return out
}

// OneShot is the line an identity needs to introduce one-shot writers.
//
// A one-shot writer's identity is 130 bits of crypto/rand minted as it commits,
// deliberately derived from nothing — because two processes that both claimed one
// identity would hand the same sequence number to different ops, which is silent,
// permanent divergence. So no grant can name it, and until this existed a CI
// runner could report to a store nobody guarded and to no other kind.
//
// This names the shape instead. The glossary already defines a one-shot writer
// as one that "creates its log, writes once, never appends, and evicts itself
// on completion", and that sentence is the whole of what this permits:
// announcement, log at rotation zero, and eviction, arriving together as
// creations for one writer.
//
// The pattern names the store and carries no "/*", because this rule does not
// match a ref by prefix and a wildcard would suggest it does.
func OneShot(identity, store string) []string { return []string{OneShotLine(identity, store)} }

// OneShotLine is the single line OneShot returns, for a caller composing a policy
// by hand rather than joining slices.
func OneShotLine(identity, store string) string {
	return fmt.Sprintf("allow-oneshot %s %s", identity, reflayout.For(store).Root().Prefix())
}

// oneShotWriters returns the writers this push introduces whole.
//
// A writer qualifies only if the push creates its low-water mark, its log at
// rotation zero, and its eviction — all three, all as creations, and nothing else
// of its. Everything that makes the grant safe falls out of that rather than
// being checked separately:
//
//   - It cannot be grafted onto a writer that already exists, because that
//     writer's announcement is already there, so the update naming it would
//     not be a creation and the set would be short.
//   - It cannot append later, because rotation zero is named and a second push
//     carrying one ref is not a whole writer.
//   - It cannot introduce a writer that does not close itself, because the
//     eviction is one of the three. A writer arriving without one would count
//     toward the barrier for ever, and there is no clone left to evict it.
//
// Decided from the update set alone, which the hook hands over whole: a
// pre-receive runs once per push and sees every ref it proposes. So this stays a
// pure function with no git in it, like everything else here.
func oneShotWriters(updates []Update) map[string]bool {
	type parts struct {
		announcement, log, evicted bool
		extra                      bool
	}
	seen := map[string]*parts{}
	for _, u := range updates {
		r := reflayout.Parse(u.Ref)
		if r.Writer == "" {
			continue
		}
		key := r.Store + "\x00" + r.Writer
		p := seen[key]
		if p == nil {
			p = &parts{}
			seen[key] = p
		}
		if !u.Creating() {
			p.extra = true
			continue
		}
		switch {
		case r.Kind == reflayout.Announcement:
			p.announcement = true
		case r.Kind == reflayout.LogRotation && r.Rotation == 0:
			p.log = true
		case r.Kind == reflayout.Evicted:
			p.evicted = true
		default:
			p.extra = true
		}
	}
	out := map[string]bool{}
	for key, p := range seen {
		if p.announcement && p.log && p.evicted && !p.extra {
			out[key] = true
		}
	}
	return out
}

// introduces reports whether identity may introduce writers into ref's store.
func (p *Policy) introduces(identity, store string) bool {
	for _, r := range p.allow[identity] {
		if r.allows == 0 && r.pattern == reflayout.For(store).Root().Prefix() {
			return true
		}
	}
	return false
}

// Check returns every update the identity may not make.
//
// Two things have to hold, and they are different in kind. The policy has to
// permit the ref, which is a deployment's decision. And the update has to be one
// the layout allows at all, which is the protocol's and applies to everyone —
// including an identity the policy trusts completely.
func (p *Policy) Check(identity string, updates []Update) []Rejection {
	// Which writers this push introduces whole, decided once for the batch: a
	// one-shot writer cannot be authorised a ref at a time, because what makes it
	// safe to admit is the shape of the whole set.
	whole := oneShotWriters(updates)

	var out []Rejection
	for _, u := range updates {
		if reason := shapeOf(u); reason != "" {
			out = append(out, Rejection{u.Ref, reason})
			continue
		}
		if p.permits(identity, u.Ref, directionOf(u)) {
			continue
		}
		if r := reflayout.Parse(u.Ref); r.Writer != "" &&
			whole[r.Store+"\x00"+r.Writer] && p.introduces(identity, r.Store) {
			continue
		}
		out = append(out, Rejection{u.Ref, identity + " is not allowed to write this ref"})
	}
	return out
}

func (p *Policy) permits(identity, ref string, way direction) bool {
	for _, r := range p.allow[identity] {
		if r.allows&way == 0 {
			continue
		}
		if prefix, ok := strings.CutSuffix(r.pattern, "/*"); ok {
			if strings.HasPrefix(ref, prefix+"/") {
				return true
			}
			continue
		}
		if ref == r.pattern {
			return true
		}
	}
	return false
}

// rules are the words a policy line may begin with.
//
// Two directions and not three. Nothing in this design wants update-only: a
// writer needs every direction on its own refs, and an operator needs create and
// delete on other writers'. A third word would be one no generator emits, and
// Parse refuses what it does not know — so the day something wants it, adding it
// is a line here rather than a gap nobody noticed.
var rules = map[string]direction{
	"allow":        anyDirection,
	"allow-create": creating,
	"allow-delete": deleting,
	// allow-oneshot is a different kind of rule and carries no direction of its
	// own: what it permits is a whole writer arriving at once, which is three
	// creations or nothing. See oneShotWriters.
	"allow-oneshot": 0,
}

func ruleWords() string {
	words := make([]string, 0, len(rules))
	for w := range rules {
		words = append(words, strconv.Quote(w))
	}
	sort.Strings(words)
	return strings.Join(words, ", ")
}

// shapeOf returns why the layout forbids an update, or "" if it does not.
//
// The layout itself is reflayout's; what may be *done* to a ref it describes is
// this package's, and that is the whole of the split. A generation is the one
// shape with a rule beyond its name, and the rule is about object ids — which
// reflayout has never heard of and should not.
func shapeOf(u Update) string {
	r := reflayout.Parse(u.Ref)
	if reason := r.Refusal(); reason != "" {
		return reason
	}
	// A generation is verified by recomputation, which only works while the
	// bytes at a number are the bytes everyone folded. Replacing them leaves
	// no evidence in any later read: a clone that had already adopted the old
	// generation is simply, permanently, holding different data from one that
	// adopts the new one. Creating and deleting are how generations are meant
	// to move — published once, dropped by retention — and neither can do
	// that.
	if r.Kind == reflayout.Gen && !u.Creating() && !u.Deleting() {
		return "a published generation cannot be replaced"
	}
	return ""
}

