// self-declaration: every pusher would simply claim to be whoever they liked.
// The same disqualifies the committer, the author, and anything else carried in
// the objects.
//
// # Where the policy comes from
//
// A file in the bare repository, which is to say from the server's disk and not
// from the push. Keeping policy in the repository, gittuf-style, is the better
// answer to distribution and rotation, but it needs a trusted root to start from
// and a gated path for its own updates. gittuf has both, at the cost of a
// hash-chained log every writer appends to — the one structure this project
// measured as unusable, at 7.4 attempts per append with sixteen writers. Policy
// on the server's disk is a smaller claim, and it is one that can actually be
// kept.
package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entirehq/strata/authz"
)

func main() {
	if err := run(); err != nil {
		// Prefixed, because git relays a hook's stderr to the person pushing
		// with no indication of where it came from.
		fmt.Fprintf(os.Stderr, "strata: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	identity := os.Getenv(identityVar())
	if identity == "" {
		return fmt.Errorf("no pushing identity in %s; the server must set it", identityVar())
	}

	policyPath := filepath.Join(gitDir(), "strata-policy")
	raw, err := os.ReadFile(policyPath)
	if err != nil {
		// Denied rather than open. A missing policy is a repository that was
		// never configured, and the safe reading of "nobody is allowed anything"
		// is the one that fails visibly on the first push instead of the first
		// incident.
		return fmt.Errorf("reading %s: %w", policyPath, err)
	}
	policy, err := authz.Parse(raw)
	if err != nil {
		return err
	}

	updates, err := readUpdates(os.Stdin)
	if err != nil {
		return err
	}
	rejections := policy.Check(identity, updates)
	if len(rejections) == 0 {
		return nil
	}

