func (s *Service) HandleReceivePack(w http.ResponseWriter, r *http.Request, st *storage.Storage, pushSizeLimit int64, mirrorTargets *mirrorWriteTargets, mirrorRepo bool, protection *repostore.BranchProtection) {
	ctx := r.Context()
	ctx, span := otel.Tracer().Start(ctx, "server.handleReceivePack")
	defer span.End()

	ctx = gitspan.WithRoot(ctx, span)
	gitspan.SetOp(ctx, gitspan.OpPush)
	gitspan.SetClientKindFromUA(ctx, r.Header.Get("User-Agent"))

	pv := v2dispatch.ProtocolVersionFromHeader(r.Header.Get("Git-Protocol"))
	span.SetAttributes(attribute.String("git.protocol.version", pv.String()))

	pushSizeLimit = applyAbsolutePushCeiling(pushSizeLimit)

	// Validate content type
	contentType := strings.ToLower(strings.TrimSpace(r.Header.Get("Content-Type")))
	if contentType != "application/x-git-receive-pack-request" {
		http.Error(w, "403 Forbidden", http.StatusForbidden)
		return
	}

	// Parse declared push size from header (shared by gates below).
	var declaredSize int64
	if pushSizeStr := r.Header.Get("X-Entire-Push-Size"); pushSizeStr != "" {
		if v, err := strconv.ParseInt(pushSizeStr, 10, 64); err == nil {
			declaredSize = v
		}
	}

	// Gate 1: Early rejection using declared push size header.
	// The remote helper sends this before the body — reject fast for well-behaved clients.
	if pushSizeLimit > 0 && declaredSize > pushSizeLimit {
		slogutil.Warn(ctx, "receive-pack: push rejected by size limit",
			slog.Int64("declared_bytes", declaredSize),
			slog.Int64("limit_bytes", pushSizeLimit))
		secsignal.Emit(ctx, secsignal.PushRejected,
			secsignal.WithSurface("githttp"),
			secsignal.WithReason("size_limit"))
		http.Error(w, fmt.Sprintf("push rejected: declared size %d exceeds limit %d",
			declaredSize, pushSizeLimit), http.StatusRequestEntityTooLarge)
		return
	}

	// Gate 1b: Reject if accepting this push would breach the free space threshold.
	// Check: freeBytes - declaredSize < threshold (would the push eat into headroom?)
	if threshold := s.FreeSpaceThresholdBytes; threshold > 0 && declaredSize > 0 {
		if ls := s.LocalStorage; ls != nil {
			freeBytes := ls.FreeBytes()
			if objstore.WouldBreachFreeSpaceThreshold(freeBytes, uint64(declaredSize), threshold) {
				slogutil.Warn(ctx, "receive-pack: push rejected by disk space",
					slog.Int64("declared_bytes", declaredSize),
					slog.Uint64("free_bytes", freeBytes),
					slog.Uint64("threshold_bytes", threshold))
				http.Error(w, fmt.Sprintf("push rejected: insufficient disk space (free=%d, threshold=%d, push=%d)",
					freeBytes, threshold, declaredSize), http.StatusInsufficientStorage)
				return
			}
		}
	}

	// Set response headers (matching go-git's serviceRPC pattern)
	w.Header().Set("Content-Type", "application/x-git-receive-pack-result")
	w.Header().Set("Connection", "Keep-Alive")
	w.Header().Set("Transfer-Encoding", "chunked")
	w.Header().Set("X-Content-Type-Options", "nosniff")

	// Bound the wall-clock time available for the rest of the request. The
	// read deadline interrupts blocking body reads if the client stalls; the
	// context timeout cancels downstream ctx-aware work. Clear the deadline
	// on exit so it doesn't leak onto a subsequent request that reuses the
	// keep-alive connection. The constant lives in diss, next to the
	// quarantine sweep grace that must stay strictly above it.
	deadline := time.Now().Add(diss.PackfileIngestDeadline)
	rc := http.NewResponseController(w)
	if err := rc.SetReadDeadline(deadline); err != nil {
		slogutil.Warn(ctx, "receive-pack: set read deadline", slog.Any("error", err))
	}
	defer func() {
		if err := rc.SetReadDeadline(time.Time{}); err != nil {
			slogutil.Warn(ctx, "receive-pack: clear read deadline", slog.Any("error", err))
		}
	}()
	ctx, cancel := context.WithDeadline(ctx, deadline)
	defer cancel()

	splitLOP := s.shouldSplitLOP(ctx, st)
	limitWriter := w
	if splitLOP {
		limitWriter = bodyLimitWriter{w}
	}

	// Gate 2: MaxBytesReader safety net on the raw HTTP body.
	// Catches tampered headers or clients that don't send X-Entire-Push-Size.
	body := r.Body
	if pushSizeLimit > 0 {
		body = http.MaxBytesReader(limitWriter, r.Body, pushSizeLimit)
	}

	// Count wire (compressed) bytes for push.bytes_received telemetry.
	// Wraps body BEFORE the gzip layer so the attribute records what the
	// client actually sent over the wire, not the decompressed size. The
	// final value is recorded via defer so every return path reports it.
	bodyCounter := &countingReader{r: body}
	body = struct {
		io.Reader
		io.Closer
	}{Reader: bodyCounter, Closer: body}
	defer func() { gitspan.SetPushBytesReceived(ctx, bodyCounter.n) }()

	// Handle gzip content encoding
	var reader io.ReadCloser
	switch r.Header.Get("Content-Encoding") {
	case compressionGzip:
		gr, err := gzip.NewReader(body)
		if err != nil {
			slogutil.Error(ctx, "Failed to create gzip reader", slog.Any("error", err))
			http.Error(w, "500 Internal Server Error", http.StatusInternalServerError)
			return
		}
		defer gr.Close()
		// Cap the decompressed stream too — a small gzip body of redundant
		// bytes can inflate past pushSizeLimit and let the parser see far
		// more pktlines / pack bytes than the compressed cap admitted.
		if pushSizeLimit > 0 {
			reader = http.MaxBytesReader(limitWriter, gr, pushSizeLimit)
		} else {
			reader = gr
		}
	default:
		reader = body
	}

	rd := bufio.NewReader(reader)

	// Check for empty push (flush packet = client has nothing to send)
	l, _, err := pktline.PeekLine(rd)
	if err != nil {
		// A well-behaved client signals "nothing to send" with a flush
		// packet. A zero-byte or truncated body (EOF before any pkt-line)
		// is an aborted/empty request — not a server fault. The common
		// source is a helper retry after a push that already landed.
		// Answer 400, not 500: it's the honest status, it stops paging
		// on a client condition, and (since it's <500) it doesn't trip
		// the helper's replica failover, which retries 5xx against every
		// node and turns one empty POST into N errors across AZs.
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			slogutil.Warn(ctx, "receive-pack: empty or truncated request body", slog.Any("error", err))
			http.Error(w, "empty request body", http.StatusBadRequest)
			return
		}
		emitStallIfClientRead(ctx, err)
		slogutil.Error(ctx, "Failed to peek at request", slog.Any("error", err))
		http.Error(w, "malformed pkt-line in request", http.StatusBadRequest)
		return
	}
	if l == pktline.Flush {
		return
	}

	// Decode update requests (commands + capabilities)
	updreq := &packp.UpdateRequests{}
	if err := pushreq.Decode(updreq, rd); err != nil {
		slogutil.Error(ctx, "Failed to decode update requests", slog.Any("error", err))
		http.Error(w, "400 Bad Request", http.StatusBadRequest)
		return
	}
	if err := checkClientObjectFormat(transport.ReceivePackService, &updreq.Capabilities, st.ObjectFormat()); err != nil {
		slogutil.Warn(ctx, "receive-pack: client object-format mismatch", slog.Any("error", err))
		secsignal.Emit(ctx, secsignal.MalformedInput,
			secsignal.WithSurface("githttp"),
			secsignal.WithReason("object_format_mismatch"))
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if rejectIfTooMany(ctx, w, "receive-pack", "ref-update commands", len(updreq.Commands), maxRefUpdateCommands, secsignal.PushRejected, "ref_count") {
		return
	}

	for _, cmd := range updreq.Commands {
		if gitwire.CommandAction(cmd) == packp.Invalid {
			http.Error(w, "malformed ref-update command", http.StatusBadRequest)
			return
		}
	}

	// Reject pathological ref names (path traversal, control chars, @{,
	// reserved suffixes, etc.) before they reach refstore CAS.
	for _, cmd := range updreq.Commands {
		if err := validatePushRefName(cmd.Name); err != nil {
			slogutil.Warn(ctx, "receive-pack: invalid ref name",
				slog.String("ref", cmd.Name.String()),
				slog.Any("error", err))
			http.Error(w, fmt.Sprintf("invalid ref name %q: %v", cmd.Name.String(), err),
				http.StatusBadRequest)
			return
		}
	}

	// Reject duplicate commands for the same ref (as C git receive-pack does).
	// Everything downstream — CAS results, report-status, ref events, RSL —
	// keys per-ref state by name, so duplicates would let one command's
	// outcome silently mask the other's and the reported state could disagree
	// with what was committed.
	seenRefs := make(map[plumbing.ReferenceName]struct{}, len(updreq.Commands))
	for _, cmd := range updreq.Commands {
		if _, dup := seenRefs[cmd.Name]; dup {
			slogutil.Warn(ctx, "receive-pack: duplicate ref-update command",
				slog.String("ref", cmd.Name.String()))
			http.Error(w, fmt.Sprintf("multiple updates for ref %q not allowed", cmd.Name.String()),
				http.StatusBadRequest)
			return
		}
		seenRefs[cmd.Name] = struct{}{}
	}

	// Classify push shape and record span attributes.
	var creates, updates, deletes int
	for _, c := range updreq.Commands {
		switch {
		case c.Old.IsZero() && !c.New.IsZero():
			creates++
		case !c.Old.IsZero() && c.New.IsZero():
			deletes++
		default:
			updates++
		}
	}
	gitspan.SetPushShape(ctx, gitspan.PushShapeOf(creates, updates, deletes))
	gitspan.SetPushCommandsCount(ctx, len(updreq.Commands))
	// Forensic counts (no signal): a mass-delete or all-create push stands out
	// in aggregate without alerting on every ordinary update.
	span.SetAttributes(
		attribute.Int("push.create_count", creates),
		attribute.Int("push.delete_count", deletes),
	)

	// Handle push-options if negotiated
	var pushOptions []string
	if updreq.Capabilities.Supports(capability.PushOptions) {
		var pushOpts packp.PushOptions
		if err := pushOpts.Decode(rd); err != nil {
			slogutil.Error(ctx, "Failed to decode push-options", slog.Any("error", err))
			http.Error(w, "400 Bad Request", http.StatusBadRequest)
			return
		}
		pushOptions = pushOpts.Options
	}

	// The write path goes on the storer here, before the CAS transaction
	// begins, so the whole transaction sees one path. It is set on the
	// storer and not on ctx for the same reason SetCommitMeta is: the CAS
	// entry points read the context the storer captured at construction.
	// The span records the requested path. The refstore layer can still
	// force legacy, for example in restore mode or for placement writes.
	refstorePath := refstore.ResolveRefstorePath(pushOptions, s.FencePushOption, s.FenceDefault)
	st.SetRefstorePath(refstorePath)
	span.SetAttributes(attribute.String("refstore.path.requested", refstorePath))

	// Set up sideband muxer for progress reporting and report-status.
	caps := updreq.Capabilities
	mux, wantProgress := negotiateSideband(&caps, w)

	// Build a flushing progress writer whenever there is a side-band to write
	// to. quiet decides whether the progress counters are written, not whether
	// the writer exists: the RSL receipt and the advisory warnings travel on
	// the same channel, and git sends quiet on every push whose stderr is not
	// a terminal, so gating the writer itself hid them from exactly the
	// scripted and CI pushes that rely on reading them back.
	var progress *progressWriter
	if mux != nil {
		rc := http.NewResponseController(w)
		if err := rc.EnableFullDuplex(); err != nil {
			slogutil.Warn(ctx, "Failed to enable full-duplex", slog.Any("error", err))
		}

		pw := &progressWriter{mux: mux, quiet: !wantProgress}
		if f, ok := w.(http.Flusher); ok {
			pw.flusher = f
		}
		progress = pw
	}

	// A flow 1 restore ingest (ADR 20261022-rsl-restore-flows) checks what it
	// can before the pack is read. A refusal here stores nothing.
	ingest, refusal := s.admitRestoreIngest(ctx, st, pushOptions, updreq.Commands)
	if refusal != nil {
		refuseRestorePush(ctx, w, rd, mux, progress, updreq, refusal)
		return
	}

	// Reject pushes to reserved ref namespaces (refs/internal/*, refs/replace/*,
	// etc. — see isReservedPushRef). Three scoped exceptions:
	//   - restore mode: entire-backup repopulates every ref a live cluster
	//     carried, so the whole gate is skipped.
	//   - a workload-writable namespace (namespaceWriters): a ref whose
	//     namespace the caller's mTLS workload identity (recorded by the
	//     listener's WorkloadGate) is permitted to push — e.g. refs/meta/entire/*
	//     by entire-api. A direct push carries no workload identity, so a user
	//     can't write Entire's own repo metadata by hand; every write to that
	//     sub-namespace funnels through the owning workload, which holds
	//     per-operation authz. Other refs/meta/* paths aren't reserved, so
	//     standard git-meta clients can push them directly.
	//   - native-mirror replication: the mirror worker replicating a native
	//     primary into a placement may write refs/gittuf/**, because that push
	//     republishes trust material the primary signed. refpolicy owns the
	//     carve-out; isNativeReplication says which push qualifies.
	//
	// A native-mirror replication push is refused PER REF instead of whole
	// (ENT-2423). It is a full-refset transfer that no operator drives, so one
	// blocked ref taking the whole push down leaves the placement holding
	// nothing — and an empty placement is what selects the full transfer, so the
	// next attempt repeats it. Every other push stays all-or-nothing: a person
	// is there to read the 403 and retry a narrower push.
	var reservedErrors map[plumbing.ReferenceName]error
	if !refstore.IsRestoreMode(ctx) {
		caller := callerWorkload(ctx)
		policy := s.refPolicyResolver().For(refpolicy.DomainForMirror(mirrorRepo))
		refCaller := refpolicy.Caller{Workload: caller, NativeReplication: isNativeReplication(ctx)}
		for _, cmd := range updreq.Commands {
			check := policy.CheckPush(cmd.Name.String(), refCaller)
			if check.Allowed {
				continue
			}
			slogutil.Warn(ctx, "rejecting push to reserved ref namespace", slog.String("ref", cmd.Name.String()))
			s.recordReservedRefBlock(ctx, st.RepoID().String(), cmd.Name, caller, check.Bucket)
			secsignal.Emit(ctx, secsignal.PushRejected,
				secsignal.WithSurface("githttp"),
				secsignal.WithReason("reserved_ref"),
				secsignal.WithResource("repo", st.RepoID().String()),
				secsignal.WithDetail("security.detail.ref", cmd.Name.String()))
			if !refCaller.NativeReplication {
				http.Error(w, fmt.Sprintf("push to %s is not allowed", cmd.Name), http.StatusForbidden)
				return
			}
			if reservedErrors == nil {
				reservedErrors = make(map[plumbing.ReferenceName]error, 1)
			}
			reservedErrors[cmd.Name] = fmt.Errorf("push to %s is not allowed", cmd.Name)
		}
	}

	// Refuse deletion of the branch HEAD points at (receive.denyDeleteCurrent
	// = refuse). An unreadable HEAD refuses every delete. Recorded as a per-ref
	// rejection so other commands in the same push can still succeed.
	denyErrors := denyCurrentBranchDelete(ctx, st, updreq.Commands)

	// Refuse creating a branch whose whole name is a full-length object ID.
	// Per ref, so an import that carries one still lands the rest.
	objectIDNameErrors := objectIDBranchNameErrors(ctx, st.RepoID().String(), updreq.Commands)

	// Writer scope: on a GitHub mirror, a worker sync may only write the
	// Entire-owned namespace when it declares the namespace job kind. Per ref,
	// so the rest of the sync converges.
	scopeErrors := namespaceWriterScopeErrors(ctx, r, mirrorRepo, st.RepoID().String(), updreq.Commands)

	// Branch protection, applied here rather than left to AdvanceRefs (which
	// enforces the same policy for every mirror write) for two reasons: a
	// protected ref never reaches the packfile ingest below, and its refusal
	// takes precedence over deny-current-branch for a delete of the default
	// branch, where "the branch is protected" is the more useful of the two
	// true statements. Refs refused here are filtered out of survivingCmds, so
	// AdvanceRefs never sees them and cannot double-report.
	//
	// Two rules share this block, and the ref decides which one owns a
	// command. The mirror rule (GitHub-derived, mirrorProtectedErrors) owns a
	// mirror row's ordinary refs: serveAuthenticatedGit leaves mirrorTargets
	// nil for non-mirrors and for the mirror-worker and restore pushes, and
	// the worker's inbound sync is precisely what must keep advancing the
	// default branch once users are locked out of it. The row's own graded
	// rule (nativeProtectedErrors) owns every ref on a native primary, and on
	// a mirror row the Entire namespace it owns. This pre-ingest pass refuses
	// deletes and, under server-side-merge-only, every update; force updates
	// are refused in the post-ingest pass below once ancestry can be walked.
	//
	// The mirror rule must never reach a namespace ref. That ref does not
	// exist on GitHub, so applying GitHub's default branch to it would refuse
	// a write the namespace owner alone decides (COR-1565).
	nativeRuleCmds, mirrorRuleCmds := protectionScopes(updreq.Commands, mirrorTargets, protection)
	var nativePolicy refprotect.Policy
	if len(nativeRuleCmds) > 0 {
		nativePolicy = refprotect.Policy{Protected: protection.Refs(), ServerSideMergeOnly: protection.ServerSideMergeOnlyRefs()}
	}
	var protectedErrors map[plumbing.ReferenceName]error
	if len(mirrorRuleCmds) > 0 || len(nativeRuleCmds) > 0 {
		protected := make(map[plumbing.ReferenceName]error)
		var err error
		if len(mirrorRuleCmds) > 0 {
			var refused map[plumbing.ReferenceName]error
			refused, err = mirrorProtectedErrors(ctx, st, mirrorRuleCmds)
			maps.Copy(protected, refused)
		}
		if err == nil && len(nativeRuleCmds) > 0 {
			var refused map[plumbing.ReferenceName]error
			refused, err = nativeProtectedErrors(ctx, st, nativePolicy, nativeRuleCmds, refprotect.Write{})
			maps.Copy(protected, refused)
		}
		if err != nil {
			// Policy evaluation failed before the packfile was read or any
			// object work started — bail out cleanly rather than proceed as
			// if nothing were protected. Reachable: refprotect.DefaultBranchSource
			// returns a real error on a genuine refstore/HEAD-read failure. The
			// client already wrote its packfile bytes after the ref-update
			// pkt-lines (updreq.Decode above only consumed those); drain rd
			// before responding for the same reason the !needPackfile path
			// below does — net/http closes rather than drains an unread body
			// of meaningful size, so skipping this leaves the client with a
			// connection reset instead of the 503.
			if _, drainErr := io.Copy(io.Discard, rd); drainErr != nil {
				slogutil.Warn(ctx, "receive-pack: draining unread packfile body", slog.Any("error", drainErr))
			}
			slogutil.Error(ctx, "receive-pack: branch protection check failed", slog.Any("error", err))
			http.Error(w, "unable to evaluate branch protection", http.StatusServiceUnavailable)
			return
		}
		for ref, refusal := range protected {
			if protectedErrors == nil {
				protectedErrors = make(map[plumbing.ReferenceName]error, 1)
			}
			protectedErrors[ref] = refusal
			slogutil.Info(ctx, "receive-pack: rejecting write to protected ref",
				slog.String("repo_id", st.RepoID().String()),
				slog.String("ref", ref.String()))
		}
	}

	// Create commands that would form a directory/file conflict with an
	// existing ref (or another ref created earlier in the same batch) are
	// rejected by the refstore CAS itself: the Create INSERT guards against
	// the conflict and a hit surfaces as a per-ref refstore.ErrDirFileConflict
	// (see casCommandError). No separate pre-CAS gate is needed.
	// denyErrors goes first. Its Unavailable refusal can name any delete, and
	// every permanent reason must win over that temporary one. protectedErrors
	// goes last so it wins on a protected default branch, where
	// deny-current-branch also fires. scopeErrors cannot overlap protectedErrors
	// or the default branch: neither lives in the Entire-owned namespace.
	// reservedErrors cannot overlap protectedErrors: a reserved ref is not
	// branch-protected. The writer scope only refuses refs the reserved gate
	// already admits. objectIDNameErrors refuses creates alone, so it cannot
	// overlap a delete refusal.
	//
	// namespaceErrors (see namespaceRefusalErrors) overlaps none of the sets
	// above, with one exception. When HEAD cannot be read, denyErrors names
	// every delete, including a delete of a namespace ref on a mirror push.
	// Then namespaceErrors joins later and its permanent reason wins.
	// Otherwise: the writer scope fires only for a mirror-worker push, which
	// carries no mirrorTargets; protectionScopes hands a refused namespace ref
	// to neither protection rule; and a namespace ref is never the default
	// branch, because HEAD is only ever seeded to a mirrored one.
	namespaceErrors := namespaceRefusalErrors(mirrorTargets, updreq.Commands)
	otherEarlyPreCASErrors := joinErrors(denyErrors, reservedErrors, objectIDNameErrors, scopeErrors, protectedErrors)
	// Held before the namespace refusals join in, for the attribution test below.
	commandsWithoutNamespaceGate := filterSurvivingCommands(updreq.Commands, otherEarlyPreCASErrors)
	earlyPreCASErrors := joinErrors(otherEarlyPreCASErrors, namespaceErrors)
	commandsAfterEarlyRejects := filterSurvivingCommands(updreq.Commands, earlyPreCASErrors)

	// Determine if any command that can still commit needs the packfile. Commands
	// already rejected by policy should not force us to ingest otherwise
	// unreachable objects.
	needPackfile := commandsNeedPack(commandsAfterEarlyRejects)

// Package refpolicy is the single source of truth for how entiredb treats the
// reserved and internal Git ref namespaces. It answers three questions that
// were previously decided in three places and drifted:
//
//   - Push: may this caller push this ref, or is the namespace reserved?
//     (was server/githttp/receive_pack.go's reservedPush* slices)
//   - Fetch: is this ref hidden from advertisement for this caller?
//     (uploadpack.hideRefs, previously wired nil everywhere)
//   - Recording: should a push to this ref produce a signed RSL entry?
//     (was rslstore.ShouldRecord's denylist)
//
// Recording starts from fetch visibility: a hidden ref is never signed. Two
// visible namespaces are carved out as well. Unmirrored branches
// (refs/heads/entire/unmirrored/*) stay visible on fetch but are never mirrored
// to GitHub, and git-sync's transfer scaffolding (refs/gitsync/**) stays visible
// so a bootstrap can resume but exists only on a replication target (see
// ShouldRecord). The coverage mode then narrows what remains to branches, tags,
// and checkpoints (see CoveredByMode). Deriving visibility and the recording
// base from one hidden set keeps a hidden ref from ever being signed.
//
// The policy is layered as a chain of command (see resolve): a base layer of
// fleet-wide invariants, then per-domain deltas (native vs GitHub-mirror repos),
// then per-caller carve-outs. Each layer may only ADD restrictions; the only
// ways to loosen are an explicit workload carve-out (push) or the trusted-reader
// exemption (fetch). Deny-by-default, fail-closed.
package refpolicy

import (
	"slices"
	"strings"

	"entire.io/core/servicetoken"
	"entire.io/internal/go-git/plumbing/transport/hiderefs"
	"github.com/gittuf/gittuf/pkg/rsl"
)

// Canonical ref namespaces. These names previously lived as unexported
// constants in receive_pack.go, rslstore/writer.go, and refstore; this package
// is now their one home.
const (
	// GittufPrefix is gittuf's reserved namespace (RSL, policy, policy-staging,
	// attestations). entiredb owns it server-side; direct client pushes to any
	// refs/gittuf/* are refused.
	GittufPrefix = "refs/gittuf/"
	// RSLRef is the gittuf Reference State Log, written server-side by rslstore.
	// Bound to gittuf's own constant so the recording carve-out (ShouldRecord)
	// cannot drift from the ref gittuf actually writes and start signing the RSL
	// into itself.
	RSLRef = rsl.Ref
	// PolicyStagingRef is gittuf's staging policy ref. gittuf keeps its own copy
	// unexported (unlike rsl.Ref), so this literal must be kept equal to it by
	// hand.
	PolicyStagingRef = "refs/gittuf/policy-staging"
	// PolicyRef is the repo's root of trust. It is client-visible so clients can
	// verify against it, so it is neither hidden nor exempt from recording.
	PolicyRef = "refs/gittuf/policy"

	// ManagedMetaPrefix is the git-meta service's shared metadata namespace,
	// reserved for direct client pushes but writable by the entire-api workload.
	// It is client-visible and recorded.
	ManagedMetaPrefix = "refs/meta/entire/"

	// InternalPrefix, LocalPrefix, and EntirePrefix are entiredb-internal
	// namespaces: reserved from direct client push, hidden from external fetch,
	// and not recorded. Two sub-namespaces below are exceptions on all three
	// counts, because a client owns each: EntireCheckpointsPrefix and
	// EntirePoliciesPrefix. refs/local/* holds node-local refs that never leave
	// the server, so they are never advertised and users cannot push them.
	InternalPrefix = "refs/internal"
	LocalPrefix    = "refs/local"
	EntirePrefix   = "refs/entire"

	// HeadsPrefix and TagsPrefix are the two ordinary user-facing namespaces.
	// They carry no policy of their own here. They exist so the coverage modes
	// in coverage.go name them from the same place as every other namespace
	// literal rather than re-spelling them.
	HeadsPrefix = "refs/heads/"
	TagsPrefix  = "refs/tags/"

	// GitSyncScaffoldPrefix is git-sync's own temp-ref namespace on a
	// replication TARGET: a batched bootstrap parks each branch at
	// refs/gitsync/bootstrap/heads/<branch> and removes it when the branch
	// lands. It is transfer scaffolding the sync writes and deletes itself, not
	// repository content, and it exists ONLY on the target — the primary never
	// holds one, so the primary's RSL never attests one.
	//
	// It is carved out of recording for that reason, and deliberately NOT hidden:
	// git-sync reads its own scaffolding back from the target's advertisement to
	// resume an interrupted bootstrap, so hiding it would break the resume.
	// See server/githttp's gitsyncScaffoldPrefix, which pins the same literal for
	// the writer-scope gate.
	GitSyncScaffoldPrefix = "refs/gitsync/"

	// EntireCheckpointsPrefix is the checkpoint sub-namespace of refs/entire. It
	// is the exception to the refs/entire rules: checkpoints are client-visible
	// (un-hidden), user-amendable (pushable), and therefore recorded, while the
	// rest of refs/entire stays hidden and reserved. refs/entire/checkpoints/* is
	// written both by the entire-api path (repoapi commit_create) and by users.
	EntireCheckpointsPrefix = "refs/entire/checkpoints"

	// EntirePoliciesPrefix is the checkpoint-policy sub-namespace of
	// refs/entire. The entire CLI owns it: checkpointpolicy.Push writes
	// refs/entire/policies/checkpoint, and the same package lists and fetches
	// that ref to compare a local policy against the remote baseline.
	//
	// It therefore follows the EntireCheckpointsPrefix rules. The CLI is an
	// ordinary client, so the ref is pushable by every caller, and it is
	// advertised: a hidden ref returns nothing to the CLI's ls-remote and
	// fails its fetch. It is not a branch, tag, or checkpoint, so no coverage
	// mode signs it.
	//
	// Reserving this namespace refused two writers at once (ENT-2479): the
	// CLI's own push, and the mirror worker's GitHub sync, which replays the
	// ref a CLI left on the upstream. A worker-only carve-out fixes the sync
	// and leaves every CLI user refused, so the opening is not scoped to a
	// workload.
	//
	// entiredb stores the content and interprets none of it. Nothing here
	// reads policy.json. Giving this ref a meaning in entiredb is a separate
	// change: the refs already in the fleet were written under no server-side
	// rule, so that change needs a migration over them, validation at the
	// write path, or both, before anything may trust their content.
	EntirePoliciesPrefix = "refs/entire/policies"

	// entireHeadsAnchor, unmirroredAnchor and nativeAnchor are the directory
	// anchors that protect the two mirror-only Entire-owned branch namespaces
	// (refs/heads/entire/unmirrored/* and refs/heads/entire/native/*). They are
	// reserved on GitHub-mirror repos only; a native repo may use them as
	// ordinary branches.
	entireHeadsAnchor = "refs/heads/entire"
	unmirroredAnchor  = "refs/heads/entire/unmirrored"
	nativeAnchor      = "refs/heads/entire/native"
)

// Domain is the class of repository a ref policy applies to. Native repos and
// GitHub mirrors share a base policy and differ only in their deltas.
type Domain int

const (
	// DomainNative is an Entire-native repository.
	DomainNative Domain = iota
	// DomainGitHubMirror is a repository mirrored from GitHub.
	DomainGitHubMirror
)

// DomainForMirror maps the repo row's is_mirror flag onto a Domain, keeping the
// classification in one place without coupling this package to repostore.
func DomainForMirror(isMirror bool) Domain {
	if isMirror {
		return DomainGitHubMirror
	}
	return DomainNative
}

// Caller is the request identity a policy needs. Workload is the mTLS workload
// identity (empty for a public client). TrustedReader marks a caller that must
// see every ref regardless of hideRefs, i.e. backup/restore capture, so a
// bundle stays complete. The server adapts its request principal onto this.
type Caller struct {
	Workload      servicetoken.Workload
	TrustedReader bool
	// NativeReplication marks the mirror-worker push that replicates a native
	// primary's refs into a native-mirror PLACEMENT. It is the one caller that
	// may write gittuf's namespace (see the carve-out in baseRules), because
	// that push republishes trust material the primary already signed rather
	// than authoring any. The server sets it from the repos row and the request
	// principal together, never from the request alone.
	NativeReplication bool
}

// PushCheck is the reserved-ref verdict for one ref and caller.
type PushCheck struct {
	// Reserved reports whether the ref falls in a reserved namespace.
	Reserved bool
	// Bucket is the matched rule, a low-cardinality metric label; "" when not
	// reserved.
	Bucket string
	// Allowed reports whether this caller may push the ref: true when the ref is
	// not reserved, or a carve-out lifts the reservation for this caller.
	Allowed bool
}

// carveOut lifts the reserved-ref gate on a namespace for named workloads.
// nativeReplicationOnly narrows it further, to the native-mirror replication
// push alone: the workload identity says WHO is calling, and that flag says
// WHICH of its pushes qualifies. A carve-out needs both when the same workload
// also runs pushes that must stay blocked.
type carveOut struct {
	prefix                string
	writers               []servicetoken.Workload
	nativeReplicationOnly bool
}

// rules is one layer's contribution to a policy. Layers are merged (see
// resolve); every field is additive.
type rules struct {
	reservedPrefixes []string // matched with a trailing slash (path prefix)
	reservedExact    []string // matched whole
	pushOpenPrefixes []string // sub-prefixes pushable for ALL callers despite a reserved parent
	carveOuts        []carveOut
	hidePatterns     []string // uploadpack.hideRefs syntax (hiderefs.IsHidden)
}

// Policy is the resolved, immutable ref policy for one domain. Its zero value is
// not valid; obtain one from a Resolver.
type Policy struct {
	r rules
}

// baseRules are the fleet-wide invariants that apply to every repo, whatever its
// domain. Each entry below notes why it is reserved/hidden and whether it can be
// overridden. The two override mechanisms are distinct:
//
//   - Push reservations are lifted two ways: a workload carve-out (see
//     carveOuts) opens a namespace to a named workload, and a pushOpenPrefixes
//     entry opens a sub-namespace to every caller (e.g. refs/entire/checkpoints/*
//     inside reserved refs/entire). The domain layer can add but never remove a
//     base reservation (tighten-only).
//   - Hide patterns are overridable per-subtree by a "!"-prefixed exception,
//     since hiderefs matching is last-match-wins (see hidePatterns).
func baseRules() rules {
	return rules{
		// Reserved from client push, matched as a path prefix (trailing slash
		// required). Overridable only by a workload carve-out where noted.
		reservedPrefixes: []string{
			// Git convention for server-internal refs; also hidden from fetch
			// (hidePatterns). Blocking push closes the write side. No carve-out.
			InternalPrefix + "/",
			// Node-local refs that never leave the server; also hidden from fetch
			// (hidePatterns) and excluded from recording. Blocking push closes the
			// write side. No carve-out.
			LocalPrefix + "/",
			// entiredb-managed refs; also hidden from fetch and excluded from
			// recording. Reserved from direct client push, EXCEPT the two
			// sub-namespaces in pushOpenPrefixes below: checkpoints and
			// policies, both of which the entire CLI writes. The remainder is
			// written only through server-side paths (not receive-pack), so
			// this gate does not block them. No carve-out.
			EntirePrefix + "/",
			// Git object-replacement: a ref here rewrites how every cloner sees an
			// object, so push is object substitution against all clients. No carve-out.
			"refs/replace/",
			// git bisect's session-local refs; meaningless on the server. No carve-out.
			"refs/bisect/",
			// The client's own remote-tracking view; no server-side meaning. No carve-out.
			"refs/remotes/",
			// Entire's structured-metadata namespace (ENT-1106), reserved so writes
			// funnel through the git-meta service, which owns format + authz.
			// OVERRIDABLE: the entire-api carve-out below lifts it for nested refs.
			ManagedMetaPrefix,
			// Git's GIT_NAMESPACE feature; entiredb uses one repo per ULID and never
			// namespaces, so a push here makes double-nested refs no tool expects.
			// No carve-out.
			"refs/namespaces/",
			// Prefix-form custom stash layouts (the bare refs/stash is an anchor
			// below). No carve-out.
			"refs/stash/",
			// gittuf's namespace: the RSL is server-managed and user-authored
			// policy/RSL is not supported yet, so the whole namespace is closed to
			// direct client push. refs/gittuf/policy stays fetch-visible for
			// verification. The server's own RSL writes bypass this gate.
			// OVERRIDABLE: the native-replication carve-out below lifts it for the
			// mirror worker replicating a primary into a native mirror.
			GittufPrefix,
		},
		// Directory anchors: the bare namespace roots, reserved exact so a leaf ref
		// squatting one cannot D/F-conflict with (and thereby block) every ref
		// beneath it. Reserved for EVERY caller, carve-out workloads included: a
		// carve-out matches by prefix + "/", so it never reaches the bare anchor,
		// and the anchor's only legitimate writers create nested refs. Not
		// overridable. refs/heads and refs/tags matter most on an uninitialised
		// repo, where nothing beneath them exists yet to reject the squat; ordinary
		// refs/heads/* and refs/tags/* stay pushable.
		reservedExact: []string{
			"refs/heads", // blocks squatting the branch root
			"refs/tags",  // blocks squatting the tag root
			"refs/stash",
			"refs/meta",
			"refs/meta/entire",
			"refs/gittuf",
			EntirePrefix,            // refs/entire anchor, matching its reserved prefix above
			EntireCheckpointsPrefix, // refs/entire/checkpoints anchor, so squatting the bare leaf can't block the pushable checkpoints/* subtree
			EntirePoliciesPrefix,    // refs/entire/policies anchor, for the same reason as checkpoints above
		},
		// Pushable for ALL callers despite the reserved refs/entire/ parent: the
		// entire CLI writes both sub-namespaces as an ordinary client, so a
		// workload carve-out cannot express either one. Nested refs only; both
		// bare anchors stay reserved (above). Both are un-hidden below, so
		// recording follows the push opening rather than trailing it.
		pushOpenPrefixes: []string{
			EntireCheckpointsPrefix + "/",
			EntirePoliciesPrefix + "/",
		},
		// Carve-outs are the ONLY way to lift a push reservation: each names the
		// workload(s) allowed to write an otherwise-reserved namespace, matched by
		// prefix + "/" (so the bare directory anchor stays reserved even for them).
		carveOuts: []carveOut{
			// entire-api owns refs/meta/entire/* (nested refs only).
			{prefix: ManagedMetaPrefix, writers: []servicetoken.Workload{servicetoken.WorkloadEntireAPI}},
			// The mirror worker replicates a native primary's refs/gittuf/** into a
			// native-mirror placement (ENT-2423). Without this the bootstrap push
			// carries the primary's policy and RSL, the whole push is refused, and
			// the mirror can never hold managed refs — which is the very condition
			// that selects bootstrap, so it never converges.
			//
			// The carve-out admits the push; it does not trust it. The mirror is a
			// read-only copy, so what lands must be exactly what the primary
			// published: refstore's fast-forward guard refuses a rewind of the
			// namespace, the rooted-policy pin refuses a forward swap to a different
			// root, and recording is suppressed under this mode so the placement
			// never signs an entry of its own.
			//
			// The worker's GitHub-mirror syncs carry the same workload identity and
			// are NOT covered: nativeReplicationOnly keys on the target being a
			// native-mirror placement, so a GitHub mirror's trust material stays
			// closed until ENT-1395 decides what it should be.
			{
				prefix:                GittufPrefix,
				writers:               []servicetoken.Workload{servicetoken.WorkloadMirrorWorker},
				nativeReplicationOnly: true,
			},
		},
		// Hidden from external fetch: the entiredb-internal namespaces only. The
		// RSL and policy-staging are deliberately NOT hidden (gittuf clients fetch
		// the RSL to verify); they are carved out of recording instead, see
		// ShouldRecord.
		//
		// OVERRIDABLE per subtree: hiderefs matching is last-match-wins, so a
		// "!"-prefixed pattern appended AFTER a hide un-hides that subtree. The two
		// exceptions below are exactly that: refs/entire is hidden, then each
		// "!" pattern advertises one sub-namespace as a visible island inside the
		// otherwise-hidden refs/entire. Of the two, only checkpoints are inside
		// a coverage mode, so only checkpoint updates are signed.
		//
		// Both islands exist because the entire CLI reads them over the wire. It
		// is an ordinary client, so hiding a ref does not merely conceal it: the
		// CLI's ls-remote returns nothing and its fetch fails.
		hidePatterns: []string{
			InternalPrefix,                // server-internal refs (synthetic haves, etc.)
			LocalPrefix,                   // node-local refs that never leave the server
			EntirePrefix,                  // entiredb-managed refs (future trust material, etc.)
			"!" + EntireCheckpointsPrefix, // un-hide checkpoints (must follow EntirePrefix)
			"!" + EntirePoliciesPrefix,    // un-hide checkpoint policy (must follow EntirePrefix)
		},
	}
}

// domainRules are the per-domain deltas layered onto baseRules. A delta is
// tighten-only: it adds reservations/hides, never removes a base one. Only the
// GitHub-mirror domain adds rules today.

	// channel rather than the public :443 listener — that listener
	// explicitly rejects service-identity tokens (server/http.go:259-269,
	// "split-listener policy"). The auth shape on this mount is the same
	// Bearer→AuthenticateToken→AcceptGitAuth chain as :443, minus the
	// service-subject reject — workload identity is already validated at
	// the cert layer via WorkloadGate.
	//
	// githttp.Register attaches /git/repo/{id}/, /git/repo/{id}, and /git/
	// to a sub-mux; the sub-mux is wrapped by WorkloadGate + inflight
	// tracker before being mounted on the internal mux so cert-layer auth
	// and shutdown coordination apply uniformly.
	gitSvc := srv.NewGitHTTPService(cfg.HTTPInternalAdvertiseAddr)
	gitMux := http.NewServeMux()
	githttp.Register(gitMux, gitSvc, svcTokGitAuthMiddleware(cfg.Domain, srv.IssuerVerifier()), noopMiddleware)

	// Repo API (structured reads) on svctok. The entire-api ingester reads
	// commit metadata through the huma /api/v1 surface here rather than
	// cloning packs off the git mount above — same handler as the public
	// :443 mount (server/http.go:401). Two auth shapes meet here, both
	// behind WorkloadGate:
	//   - entire-api is an internal workload authorized cert-only from this
	//     server's inbound allowlist (docs/auth.md §3.2): its mTLS/SPIFFE
	//     cert is the whole credential, granting a static repo-read class
	//     with no Bearer and no SpiceDB lookup (svcTokRepoReadWorkloads).
	//   - entire-mcp / entire-search / entire-api-gateway present a Bearer
	//     JWT (per-user repo-scoped or account access), run through
	//     the public Bearer/Basic→AuthenticateToken→AcceptRepoAPIAuth chain
	//     minus the service-subject reject.
	// withPeerLeaf stashes the peer leaf so AuthenticateToken can run the
	// RFC 8705 §3 cnf check on the Bearer path; on this mTLS channel a
	// repo-scoped token without cnf is rejected (the strict-cnf flip),
	// while a cnf-less forwarded account access bearer is exempt and
	// authorized live on sub. pool is non-nil here (guarded above), so
	// NewRepoAPIService's ensureRepoStores populates the repourls store.
	repoAPIHandler := repoapi.NewHandler(srv.NewRepoAPIService(cfg.HTTPInternalAdvertiseAddr), svcTokRepoAPIAuthMiddleware(cfg.Domain, srv.IssuerVerifier()), noopMiddleware)

	// http.Server.Shutdown returns when its deadline expires even if
	// handlers are still running. Without this barrier, pgPool.Close (a
	// later defer in serve.go) races those handlers and surfaces
	// "closed pool" as gRPC Internal to the caller.
	var inflight sync.WaitGroup
	internalMux := http.NewServeMux()
	// withPeerLeaf wraps the user-JWT mounts so server/auth's
	// AuthenticateToken can run the RFC 8705 §3 cnf check. The
	// RepoAdmin mount synthesises a servicetoken.Principal from the
	// service:entiredb JWT issued at entire-core's /oauth/token; the
	// wrapper's cnf branch reads the peer leaf off the same ctx.
	repoAdminAuth := newRepoAdminAuth(srv.IssuerVerifier(), raHandler)
	internalMux.Handle(raPath, withPeerLeaf(svcTokRepoAdminMount(cfg.Domain, repoAdminAuth, &inflight)))
	// The worker-admitted procedures peel off the service-wide RepoAdmin
	// mount above onto their own exact-path mounts (ServeMux prefers the
	// longer pattern): the gate additionally admits the mirror-worker, and
	// the auth wrapper accepts the same core bearer chain or the worker
	// cert-only. Widening the shared mount instead would expose
	// Provision/Delete to the worker.
	sdbAuth := newSetDefaultBranchAuth(cfg.Domain, srv.IssuerVerifier(), raHandler)
	for _, procedure := range svcTokWorkerAdmittedRepoAdminProcedures {
		internalMux.Handle(procedure,
			withPeerLeaf(svcTokSetDefaultBranchMount(cfg.Domain, sdbAuth, &inflight)))
	}
	// ListWritePositions (the resync sweep's delta read) peels onto its own
	// exact-path mount too: the workload gate stays entire-core-only (same as
	// the service-wide mount), but the auth wrapper additionally admits the
	// cert-only entire-core shape — the sweep runs as a run-once CronJob with
	// no serving core to mint cnf-bound bearers against, and the handler
	// re-checks the workload off the stamped mTLS auth source.
	lwpAuth := newListWritePositionsAuth(cfg.Domain, srv.IssuerVerifier(), raHandler)
	internalMux.Handle(repoadminv1connect.RepoAdminListWritePositionsProcedure,
		withPeerLeaf(svcTokRepoAdminMount(cfg.Domain, lwpAuth, &inflight)))
	internalMux.Handle(adminPath, withPeerLeaf(svcTokAdminMount(cfg.Domain, adminHandler, &inflight)))
	internalMux.Handle("/et/", withPeerLeaf(svcTokGitMount(cfg.Domain, gitMux, &inflight)))
	internalMux.Handle("/git/", withPeerLeaf(svcTokGitMount(cfg.Domain, gitMux, &inflight)))
	internalMux.Handle("/api/v1/", withPeerLeaf(svcTokRepoAPIMount(cfg.Domain, repoAPIHandler, &inflight)))

	// Stamp the serving node's identity on every response so callers reaching
	// the data plane through this internal listener can tell which node
	// handled the request (mirrors the public :443 mount). The internal
	// advertise host is the readable name here.
	stampNode := httputil.StampNodeMiddleware(srv.NodeID(), cfg.HTTPInternalAdvertiseAddr)

	// Strict handshake mTLS: RepoAdmin.Provision is called only by
	// entire-core with a PCA-signed client cert. Bearer-only attempts
	// fail the handshake before any middleware runs.
	svcTokSrv := &http.Server{
		Addr:              cfg.SvcTokListenAddr,
		Handler:           stampNode(instrumentSvcTokHandler(internalMux)),
		TLSConfig:         tlsConfig,
		ReadHeaderTimeout: 10 * time.Second,
		// The fronting NLB does TCP-only health checks (see
		// infra nlb-svctok.tf) which fail TLS at handshake; drop the
		// resulting per-probe noise.
		ErrorLog: slogutil.HTTPServerErrorLog(),
	}
	errCh := make(chan error, 1)
	go func() {
		// Empty cert+key paths fall back to svcTokSrv.TLSConfig in both cases.
		var serveErr error
		if svcTokLn != nil {
			slogutil.Info(ctx, "service-token listener starting",
				slog.String("addr", svcTokLn.Addr().String()),
				slog.String("cert_source", files.source),
				slog.Bool("socket_activated", true))
			serveErr = svcTokSrv.ServeTLS(svcTokLn, "", "")
		} else {
			slogutil.Info(ctx, "service-token listener starting",
				slog.String("addr", cfg.SvcTokListenAddr),
				slog.String("cert_source", files.source),
				slog.Bool("socket_activated", false))
			serveErr = svcTokSrv.ListenAndServeTLS("", "")
		}
		if serveErr != nil && !errors.Is(serveErr, http.ErrServerClosed) {
			slogutil.Error(ctx, "service-token listener exited", slog.Any("error", serveErr))
			select {
			case errCh <- fmt.Errorf("service-token listener: %w", serveErr):
			case <-ctx.Done():
			}
		}
	}()

	return errCh, func() {
		// Graceful drain — bounded by the timeout. After this returns,
		// in-flight handlers may still be running if the deadline expired.
		shutdownHTTPServer(svcTokSrv, 5*time.Second, "service-token listener shutdown error")
		// Force-close any connections Shutdown didn't drain so the handler
		// goroutines observe ctx cancellation and unwind, then wait for
		// them. Returning here without waiting would let pgPool.Close fire
		// in serve.go while a handler is mid-pgx.Acquire, surfacing
		// "closed pool" as Internal instead of a transient code.
		_ = svcTokSrv.Close()
		inflight.Wait()
	}, nil
}

// wireTrustPublisher populates the atomic trust-publication fields
// (PublishTrust, GetTrustReceipt) when this node has a signing RSL publish
// writer. A node without a signer (pw nil) leaves TrustPublisher nil and
// PublishTrust answers Unimplemented. Split out of the listener wiring so the
// "signer configured -> publisher wired" invariant is unit-testable without
// standing up the full service-token listener. pw is guarded before assignment
// so a nil concrete writer never becomes a non-nil (typed-nil) interface.
func wireTrustPublisher(svc *adminapi.RepoAdminService, pw *rslstore.RSLWriter, pool *pgxpool.Pool) {
	if pw == nil {
		return
	}
	svc.TrustPublisher = pw
	svc.TrustRestorer = pw
	svc.TrustReceipts = adminapi.NewPgTrustReceiptStore(pool)
	svc.TrustPool = pool
}

// svcTokAdminWorkloads is the allowlist of mTLS workloads admitted on the
// :8281 admin mount. entire-core remains the original caller for the
// console's cluster-inspection RPCs (per the comment above the mount).
// entire-backup joins for the three backup RPCs (ListAllRepos,
// DirtyReposSince, StreamRepoRefDigests) so the k8s CronJob path can reach them
// over internal DNS without going through the public ALB on :443 — this
// closes the gRPC-over-Cloudflare reachability hole that blocks the
// apex-DNS path until infra #387 lands.
//
// The in-handler `requireBackupAdminAccess` guard (server/adminapi/service.go)
// independently checks that the Bearer JWT is a TokenBackupAccess and
// rejects entire-core's TokenOpsAccess on the three backup RPCs; the gate
// here only narrows acceptance at the cert layer.
//
// entire-mcp joins to reach the read forensics RPCs from the hosted MCP
// surface. Admitting the workload here is a cert-layer narrowing only: the
// admin RPCs still require a cnf-bound ops-access JWT, so the leaf alone
// grants nothing.
var svcTokAdminWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireCore,
	servicetoken.WorkloadEntireBackup,
	servicetoken.WorkloadEntireMCP,
}

// svcTokGitWorkloads is the allowlist for the /et/ and /git/ mounts on
// :8281. Tighter than svcTokAdminWorkloads on purpose — see the
// comment above the internalMux.Handle("/et/", ...) call site.
//
// WorkloadEntireDB is admitted so on-node DISS callers (repair queue,
// catchup scanner, StoreRepoProvider-backfill) can fetch from peers on
// this mount instead of the public apex (ADR 20260518). Their outbound
// mTLS bundle carries a positive SPIFFE URI SAN (ENT-599) —
// callerFromMTLS resolves it to WorkloadEntireDB via the normal SPIFFE
// path, same as any other in-cluster workload. No Bearer is presented
// or required: internalWorkloadFromCert below synthesises an internal
// workload principal from the cert alone (the JWT-issuance path that
// used to gate this mount was retired).
//
// WorkloadMirrorWorker is the cluster-internal GitHub-mirror sync workload.
// Like entiredb peer-fetch it is authorized cert-only — no Bearer — but from
// the svcTokWriteMirrorWorkloads allowlist below, which additionally grants
// push (to mirror-class repos).
//
// WorkloadPeregrine is authorized cert-only from svcTokReadAnyRepoWorkloads
// below (read-any-repo class).
//
// WorkloadEntireAPI is admitted for entire-api's git-meta receive-pack writes
// to refs/meta/entire/* (ENT-1106). WorkloadGate records its mTLS identity
// (servicetoken.CallerFromContext); receive-pack's namespaceWriters policy is
// what authorizes the write. See ADR 20260603-reserved-refs.md.
var svcTokGitWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireBackup,
	servicetoken.WorkloadEntireDB,
	servicetoken.WorkloadMirrorWorker,
	servicetoken.WorkloadPeregrine,
	servicetoken.WorkloadEntireAPI,
}

// svcTokWriteMirrorWorkloads is this server's inbound allowlist for the static
// write-mirror permission class (docs/auth.md §3.2): internal workloads whose
// mTLS/SPIFFE certificate is the whole credential for pushing to mirror-class
// repos. A caller here needs no Bearer token and no SpiceDB grant — the
// allowlist entry is the authority. certOnlyGitPrincipal synthesises a
// reqctx.KindInternalWorkload principal with WriteMirror set (pull
// cluster-wide, push allowed; receive-pack rejects the push unless the target
// repo is mirror-class) for a no-Bearer request from one of these workloads.
//
// mirror-worker republishes what it just fetched from the GitHub upstream; as
// an internal workload it holds no svc_* row, mints no token, and needs no
// per-repo writer grant. Membership is a subset of svcTokGitWorkloads — a
// workload must clear the cert gate before it can be authorized cert-only.
var svcTokWriteMirrorWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadMirrorWorker,
}

// svcTokReadAnyRepoWorkloads is this server's inbound allowlist for the static
// read-any-repo permission class (docs/auth.md §3.2): the mTLS certificate
// alone authorizes cluster-wide pull, no Bearer and no SpiceDB grant.
// peregrine clones/fetches every repo for its search indexes and, as an
// internal workload, holds no svc_* row. Subset of svcTokGitWorkloads.
var svcTokReadAnyRepoWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadPeregrine,
}

// svcTokRepoAPIWorkloads is the cert-layer allowlist (WorkloadGate) for the
// /api/v1/ huma repo-API mount on :8281 — which workloads may reach the mount
// at all. Tighter on purpose: adding a workload here exposes the structured
// repo-read surface to it, so it's a deliberate, reviewable one-liner. Pinned
// by TestSvcTokRepoAPIMountAllowedWorkloads. How each admitted workload then
// authorizes is decided in svcTokRepoAPIAuthMiddleware:
//
//   - entire-api and entire-search are authorized cert-only from
//     svcTokRepoReadWorkloads when they send no Bearer (docs/auth.md §3.2) —
//     no SpiceDB. The cert-only principal remains pull-only; CreateCommit has
//     a separate exact-workload capability gate in repoapi. entire-search
//     also forwards a per-user Bearer for its ordinary reads, which takes the
//     token path below.
//   - entire-mcp presents a Bearer JWT (per-user repo-scoped or account
//     access), so SpiceDB repo#pull is the real gate and the leaf alone
//     grants nothing.
//   - entire-api-gateway is entire-api's public reverse proxy. It always
//     forwards the caller's bearer, so it authorizes exactly like entire-mcp:
//     per-user, live against SpiceDB. It is a separate leaf from entire-api
//     so repoapi can tell a proxied user write from entire-api's own trail
//     merge; only the latter may bypass server-side-merge-only (COR-1916).
//     Keep it out of svcTokRepoReadWorkloads: a proxied request must never
//     be authorized cert-only.
//   - agent-insights is absent on purpose: it reads with installation tokens
//     on the public listener, so its SPIFFE leaf (its NATS identity) must not
//     reopen a cert-only bypass it no longer needs (ENT-2805).
var svcTokRepoAPIWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireAPI,
	servicetoken.WorkloadEntireAPIGateway,
	servicetoken.WorkloadEntireMCP,
	servicetoken.WorkloadEntireSearch,
}

// svcTokRepoReadWorkloads is this server's inbound allowlist for the static
// repo-read permission class (docs/auth.md §3.2): internal workloads whose
// mTLS/SPIFFE certificate is the whole credential for reading the structured
// repo API. A caller here needs no Bearer token and no SpiceDB grant — the
// allowlist entry is the authority. svcTokRepoAPIAuthMiddleware synthesises a
// reqctx.KindInternalWorkload principal (pull cluster-wide, ordinary push
// rejected) for a no-Bearer request from one of these workloads. repoapi's
// CreateCommit capability is checked separately against the exact entire-api
// SPIFFE caller and does not widen this principal.
//
// entire-api (the activity ingester) reads commits, refs, files and trees to
// attribute activity; as an internal workload it holds no svc_* row and mints
// no token. entire-search (semantic search indexer) needs cert-only access to
// /repos/resolve for bulk ULID resolution during backfill — the sa_session
// token it mints via client_credentials is a login JWT, which AcceptRepoAPIAuth
// rejects (chicken-and-egg: repo-scoped tokens need the ULID that /repos/resolve
// returns). Membership is a subset of svcTokRepoAPIWorkloads — a workload must
// clear the cert gate before it can be authorized cert-only.
var svcTokRepoReadWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireAPI,
	servicetoken.WorkloadEntireSearch,
}

// svcTokAdminMount returns the handler chain mounted at adminPath on the
// strict-mTLS :8281 listener: inflight tracker → workload gate → admin
// handler. Extracted as a named helper so the workload allowlist is
// testable in isolation (see svctok_listener_test.go) without standing
// up the full listener.
func svcTokAdminMount(trustDomain string, adminHandler http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, svcTokAdminWorkloads...)(adminHandler))
}

// svcTokRepoAdminMount returns the handler chain for the RepoAdmin mount
// on the strict-mTLS :8281 listener: inflight tracker → workload gate →
// JWT auth wrapper. Only entire-core may reach RepoAdmin.
//
// The WorkloadGate narrows the inbound cert to the entire-core workload
// at the cert layer so an entire-core-issued service:entiredb token
// presented over a different in-trust workload's client cert is
// rejected before JWT verification runs. Extracted as a named helper
// so the allowlist is pinned by a test (see svctok_listener_test.go)
// and can't be dropped silently.
func svcTokRepoAdminMount(trustDomain string, repoAdmin http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, servicetoken.WorkloadEntireCore)(repoAdmin))
}

// svcTokWorkerAdmittedRepoAdminProcedures is the exhaustive list of RepoAdmin
// procedures that get their own exact-path mount admitting the mirror-worker.
// Everything NOT listed here stays on the service-wide RepoAdmin mount, which
// is entire-core-only at the cert layer — so Provision and Delete are
// unreachable by the worker by construction rather than by review.
//
// This is a list rather than two inline Handle calls so the membership is
// pinned by a test: dropping an entry silently demotes that procedure to the
// core-only mount (the worker starts getting 401s — fail-closed, but silent),
// and adding one silently widens the worker's reach. Both directions are
// reviewable events. Pinned by
// TestSvcTokWorkerAdmittedRepoAdminProcedures.
var svcTokWorkerAdmittedRepoAdminProcedures = []string{
	// The worker follows a mirror source's default-branch rename cert-only;
	// the handler narrows it further to mirror-class repos.
	repoadminv1connect.RepoAdminSetDefaultBranchProcedure,
	// The worker snapshots a source primary's write position before fetching
	// (ADR 20260818-native-mirror-resync-sweep). Read-only, and no
	// repo-class narrowing — see the handler.
	repoadminv1connect.RepoAdminGetWritePositionProcedure,
}

// svcTokSetDefaultBranchWorkloads is the cert-layer allowlist for the
// worker-admitted RepoAdmin exact-path mounts
// (svcTokWorkerAdmittedRepoAdminProcedures). entire-core keeps its bearer-JWT
// path (same chain as the service-wide RepoAdmin mount); mirror-worker is
// admitted cert-only —
// for SetDefaultBranch to follow a mirror source's default-branch rename
// (the handler further narrows it to mirror-class repos), and for
// GetWritePosition to snapshot a source primary's write position before
// fetching (read-only; no repo-class narrowing, see the handler). The auth
// wrapper narrows the bearer-less shape to exactly this workload. Pinned by
// TestSvcTokSetDefaultBranchMountAllowedWorkloads.
var svcTokSetDefaultBranchWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireCore,
	servicetoken.WorkloadMirrorWorker,
}

// svcTokSetDefaultBranchMount returns the handler chain for each
// worker-admitted RepoAdmin exact-path mount on the strict-mTLS :8281
// listener: inflight tracker → workload gate → two-shape auth wrapper.
// Extracted as a named helper so the allowlist is pinned by a test, matching
// the other mounts. The mount is procedure-agnostic — which procedures get it
// is svcTokWorkerAdmittedRepoAdminProcedures, pinned separately.
func svcTokSetDefaultBranchMount(trustDomain string, sdb http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, svcTokSetDefaultBranchWorkloads...)(sdb))
}

// svcTokGitMount returns the handler chain for /git/ on the strict-mTLS
// :8281 listener. Tighter workload allowlist than svcTokAdminMount on
// purpose: entire-backup needs it for cluster-wide cloning, entire-db
// nodes need it for peer-to-peer DISS repair/catchup fetches. entire-
// core has no business driving git smart-HTTP here — its reasons for
// being on this listener are the Connect admin RPCs. Narrowing the
// gate at the cert layer means a future workload that ends up on
// svctok for some unrelated reason can't quietly gain repo read/write
// just by being admitted at the admin path.
func svcTokGitMount(trustDomain string, gitHandler http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, svcTokGitWorkloads...)(gitHandler))
}

// svcTokRepoAPIMount returns the handler chain for the /api/v1/ huma repo-API
// mount on the strict-mTLS :8281 listener: inflight tracker → workload gate →
// repo-API handler. Narrowed to svcTokRepoAPIWorkloads at the
// cert layer, so a workload admitted on the git or admin path can't read the
// structured API just by being in-trust. Extracted as a named helper so the
// allowlist is pinned by a test (see svctok_listener_test.go).
func svcTokRepoAPIMount(trustDomain string, repoAPIHandler http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, svcTokRepoAPIWorkloads...)(repoAPIHandler))
}

// svcTokGitAuthMiddleware builds the HTTP middleware that gates git
// smart-HTTP routes mounted on the svctok :8281 listener. Mirrors the
// public :443 git-auth chain (server/http.go:226's httpAuthMiddleware
// with auth.AcceptGitAuth) MINUS the jwtHasServiceSubject reject —
// service-identity tokens are exactly the expected shape on this
// surface (the "split-listener policy" documented at server/http.go:259
// says service callers belong on the internal mTLS listener). Workload
// identity is enforced one layer up by svctokserver.WorkloadGate, so
// this middleware focuses on Bearer JWT verification + the
// AcceptGitAuth kind policy.
//
// Cert-only exception: requests with no Authorization header from a workload
// this server authorizes cert-only (docs/auth.md §3.2) skip JWT verification
// entirely — the cert handshake is the whole authority and the middleware
// synthesises an internal workload principal via certOnlyGitPrincipal:
//
//   - WorkloadEntireDB — DISS catchup/repair peer fetches (PermitsGit pull
//     cluster-wide, push rejected). No STS round-trip to mint a per-fetch JWT.
//   - svcTokReadAnyRepoWorkloads (peregrine) — read-any-repo class (pull
//     cluster-wide, push rejected), identical shape to WorkloadEntireDB above.
//   - svcTokWriteMirrorWorkloads (mirror-worker) — mirror-sync pushes
//     (write-mirror class: pull cluster-wide, push to mirror-class repos).
//
// Other workloads on this listener (entire-backup) continue to require a
// Bearer JWT.
func svcTokGitAuthMiddleware(trustDomain string, verifier *auth.IssuerVerifier) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := r.Context()

			authHeader := r.Header.Get("Authorization")
			if authHeader == "" {
				if certOnly, ok := certOnlyGitPrincipal(r, trustDomain); ok {
					// The bearer path stamps the principal on the span inside
					// AuthenticateToken. This path has no token, so stamp it
					// here, or mirror-sync and DISS traffic read as anonymous
					// in every per-kind or per-handle view of git spans.
					trace.SpanFromContext(ctx).SetAttributes(auth.PrincipalAttributes(certOnly)...)
					ctx = reqctx.SetPrincipal(ctx, certOnly)
					ctx = reqctx.SetAuthSource(ctx, reqctx.AuthSourceMTLS)
					next.ServeHTTP(w, r.WithContext(ctx))
					return
				}
				w.Header().Set("WWW-Authenticate", `Basic realm="Entire Git Server"`)
				w.WriteHeader(http.StatusUnauthorized)
				_, _ = w.Write([]byte("Missing Authorization header")) //nolint:errcheck // best-effort error response
				return
			}

			// git over HTTP sends the JWT as the Basic-Auth password.
			token, ok := auth.BearerOrBasicToken(r)
			if !ok {
				w.WriteHeader(http.StatusUnauthorized)
				_, _ = w.Write([]byte("Invalid Authorization header format")) //nolint:errcheck // best-effort error response
				return
			}

			principal, _, err := auth.AuthenticateToken(ctx, verifier, token)
			if err != nil {
				slogutil.Debug(ctx, "svctok git auth failed", slog.Any("error", err))
				w.WriteHeader(http.StatusUnauthorized)
				_, _ = w.Write([]byte("Invalid or expired token")) //nolint:errcheck // best-effort error response
				return
			}

			if !auth.AcceptGitAuth(principal.Kind) {
				slogutil.Warn(ctx, "svctok git token kind not permitted",
					slog.String("kind", string(principal.Kind)),
					slog.String("path", r.URL.Path))
				w.WriteHeader(http.StatusForbidden)
				_, _ = w.Write([]byte("Token not valid for this endpoint")) //nolint:errcheck // best-effort error response
				return
			}

			ctx = reqctx.SetPrincipal(ctx, principal)
			ctx = reqctx.SetRawToken(ctx, token)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// svcTokRepoAPIAuthMiddleware gates the huma repo-API routes mounted on the
// svctok :8281 listener. Mirrors the public :443 repo-API chain
// (server/http.go's httpRepoAuthMiddleware → AcceptRepoAPIAuth) MINUS the
// jwtHasServiceSubject reject — service-identity tokens are the expected
// shape here (workload identity is enforced one layer up by WorkloadGate).
// Errors render as problem+json via the supplied huma.API for parity with the
// public mount. AuthenticateToken runs the RFC 8705 §3 cnf check against the
// peer leaf stashed by withPeerLeaf, binding a cnf-carrying token to the cert;
// on this mTLS channel a confidential-client/service token (repo-scoped,
// service:entiredb) with no cnf is rejected (the strict-cnf flip), so cert
// binding and WorkloadGate both gate that Bearer path. A forwarded account
// access bearer (including the OBO shape) is cnf-less by design and exempt
// from that check (docs/auth.md §3.1) — see AuthenticateToken.
//
// Cert-only branch: a request from a svcTokRepoReadWorkloads workload with no
// Authorization header skips token verification entirely. The cert is the
// whole credential (docs/auth.md §3.2): the middleware synthesises a
// reqctx.KindInternalWorkload principal (pull cluster-wide, push rejected) from
// the mTLS leaf, with no Bearer and no SpiceDB lookup. A user-originated read
// instead arrives with a forwarded account access bearer (cnf-less, the
// entire-api content read-through shape), so it takes the Bearer
// path below and is authorized live on sub against SpiceDB. Other admitted
// workloads (entire-mcp, entire-search) also present a Bearer.
func svcTokRepoAPIAuthMiddleware(trustDomain string, verifier *auth.IssuerVerifier) repoapi.AuthMiddleware {
	return func(api huma.API, next http.Handler) http.Handler {
		writeErr := func(w http.ResponseWriter, r *http.Request, status int, msg string) {
			_ = huma.WriteErr(api, humago.NewContext(nil, r, w), status, msg) //nolint:errcheck // best-effort auth error response
		}
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := r.Context()
			if r.Header.Get("Authorization") == "" {
				if repoRead, ok := internalWorkloadFromCert(r, trustDomain, svcTokRepoReadWorkloads...); ok {
					ctx = reqctx.SetPrincipal(ctx, repoRead)
					ctx = reqctx.SetAuthSource(ctx, reqctx.AuthSourceMTLS)
					next.ServeHTTP(w, r.WithContext(ctx))
					return
				}
				writeErr(w, r, http.StatusUnauthorized, "Missing Authorization header")
				return
			}
			token, ok := auth.BearerOrBasicToken(r)
			if !ok {
				writeErr(w, r, http.StatusUnauthorized, "Invalid Authorization header format")
				return
			}
			principal, _, err := auth.AuthenticateToken(ctx, verifier, token)
			if err != nil {
				slogutil.Debug(ctx, "svctok repo-api auth failed", slog.Any("error", err))
				writeErr(w, r, http.StatusUnauthorized, "Invalid or expired token")
				return
			}
			if !auth.AcceptRepoAPIAuth(principal.Kind) {
				slogutil.Warn(ctx, "svctok repo-api token kind not permitted",
					slog.String("kind", string(principal.Kind)),
					slog.String("path", r.URL.Path))
				writeErr(w, r, http.StatusForbidden, "Token not valid for this endpoint")
				return
			}
			ctx = reqctx.SetPrincipal(ctx, principal)
			ctx = reqctx.SetRawToken(ctx, token)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// certOnlyGitPrincipal synthesises the cert-only principal for the git mounts.
// Three allowlists meet here (docs/auth.md §3.2): entiredb peers and
// svcTokReadAnyRepoWorkloads (peregrine) get the read-only class unchanged,
// and svcTokWriteMirrorWorkloads additionally get WriteMirror set, which lets
// PermitsGit authorize push (receive-pack narrows it to mirror-class repos).
// The caller is resolved once — unlike internalWorkloadFromCert's per-allowlist
// check, checking three allowlists against one resolved caller avoids
// re-parsing the peer cert (and re-logging callerFromMTLS's rejection warning)
// once per allowlist.
//
// svcTokWriteMirrorWorkloads is checked before svcTokReadAnyRepoWorkloads so a
// workload accidentally listed in both gets the more privileged grant rather
// than being silently downgraded to read-only by switch-case order; today the
// two allowlists are disjoint, so this ordering is not load-bearing yet.
func certOnlyGitPrincipal(r *http.Request, trustDomain string) (reqctx.Principal, bool) {
	caller, ok := svctokserver.CallerFromMTLS(r, trustDomain)
	if !ok {
		return reqctx.Principal{}, false
	}
	workload, known := servicetoken.WorkloadFromSAN(caller.Name)
	if !known {
		return reqctx.Principal{}, false
	}
	p := reqctx.Principal{Handle: string(workload), Kind: reqctx.KindInternalWorkload}
	switch {
	case slices.Contains(svcTokWriteMirrorWorkloads, workload):
		p.WriteMirror = true
		return p, true
	case workload == servicetoken.WorkloadEntireDB, slices.Contains(svcTokReadAnyRepoWorkloads, workload):
		return p, true
	default:
		return reqctx.Principal{}, false
	}
}

// internalWorkloadFromCert synthesises a cert-only internal workload principal
// when the inbound peer cert resolves to one of the allowed workloads. Returns
// ok=false for any other shape — no peer cert, wrong trust domain, or a
// workload not on the caller's allowlist. The cert chain is already validated
// by the TLS handshake and the workload narrowed by svctokserver.WorkloadGate
// one layer up; passing the per-surface allowlist here turns that identity into
// a static permission class with no Bearer and no SpiceDB lookup (docs/auth.md
// §3.2). The principal carries no account: an internal workload is not a
// SpiceDB account, and the peer's SPIFFE identity (recorded by WorkloadGate) is
// the audit subject. Handle names the workload so request logs attribute it.
// CallerFromMTLS requires a positive SPIFFE claim, so entiredb is classified
// from the workload URI SAN its EC2 cert carries.
func internalWorkloadFromCert(r *http.Request, trustDomain string, allowed ...servicetoken.Workload) (reqctx.Principal, bool) {
	caller, ok := svctokserver.CallerFromMTLS(r, trustDomain)
	if !ok {
		return reqctx.Principal{}, false
	}
	workload, known := servicetoken.WorkloadFromSAN(caller.Name)
	if !known || !slices.Contains(allowed, workload) {
		return reqctx.Principal{}, false
	}
	return reqctx.Principal{
		Handle: string(workload),
		Kind:   reqctx.KindInternalWorkload,
	}, true
}

// noopMiddleware is the identity middleware. Used for the userRateLimit
// slot of githttp.Register on the svctok mount — workload-mTLS callers
// are trusted in-VPC service identities (cert-gated) and don't need the
// per-user rate-limiting the public :443 listener applies.
func noopMiddleware(next http.Handler) http.Handler { return next }

// withPeerLeaf stashes the inbound mTLS leaf cert on the request ctx so
// server/auth's AuthenticateToken can run the RFC 8705 §3 cnf check

// serveAuthenticatedGit is the shared tail of handleRepo and
// handleRepoByULIDAuth: capability check via resolveRepoLoader, then
// dispatch to the matching git smart-HTTP handler. repoSlug is the
// audience-style URL slug for this route (the path under /git/ that
// the route resolved); passed through to PermitsGit so the comparison
// stays in slug terms rather than ULID terms.
func (s *Service) serveAuthenticatedGit(w http.ResponseWriter, r *http.Request, repoID repositories.ID, repoSlug string) {
	ctx := r.Context()

	// Restore-mode flip: a backup-restore JWT carries RestoreMode=true,
	// signalling that the receive-pack flow is replaying refs from a
	// backup bundle and the recording decorator should NOT re-emit RSL/
	// NATS entries for them. Replaces the legacy X-Entire-Api-Auth-triggered
	// restore mode in handleRepoByID — same effect, JWT-claim-driven instead
	// of header-driven. Gated on Kind==TokenBackupAccess so a stray
	// RestoreMode bit on any other kind (e.g. a future claimsFromJWT
	// drift) cannot quietly suppress recording.
	if p, ok := reqctx.GetPrincipal(ctx); ok && isRestorePrincipal(p) {
		ctx = refstore.ContextWithRestoreMode(ctx)
		r = r.WithContext(ctx)
	}

	loader, err := s.resolveRepoLoader(ctx, repoID, repoSlug, gitutil.SmartHTTPOp(r))
	if err != nil {
		if hErr, ok := errors.AsType[*httpError](err); ok {
			// Render through http.Error so the enumeration-guard 404 from
			// resolveRepoLoader is byte-identical (status, Content-Type,
			// nosniff, trailing newline) to handleRepo's unknown-slug 404.
			// Any divergence between the two 404s would itself be an oracle.
			msg := hErr.message
			if msg == "" {
				msg = http.StatusText(hErr.status)
			}
			http.Error(w, msg, hErr.status)
		} else {
			slogutil.Error(ctx, "Unexpected error serving git request", slog.Any("error", err))
			http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		}
		return
	}
	defer func() { _ = loader.Storage().Close() }()

	if isInfoRefsDiscovery(r) {
		// git prints the body of a failed ref discovery but not the body of a
		// failed receive-pack POST, so the freeze is refused here first to
		// show the user why. The POST check below stays authoritative.
		if r.URL.Query().Get("service") == transport.ReceivePackService {
			principal, _ := reqctx.GetPrincipal(ctx)
			if !isMirrorWorker(principal) {
				repoRow, _, err := s.fetchRepoRow(ctx, repoID)
				if err != nil {
					slogutil.Error(ctx, "repo state lookup failed", slog.String("repo_id", repoID.String()), slog.Any("error", err))
					http.Error(w, "repo state lookup unavailable, retry later", http.StatusServiceUnavailable)
					return
				}
				if refuseFrozenWrite(ctx, w, principal, repoRow, repoID) {
					return
				}
			}
		}
		// Mount-aware addr pool — public mount uses each provider's public
		// HTTPAddr; svctok mount uses HTTPInternalAddr (ADR 20260518). When
		// internal-addr is configured but no peer has gossiped one yet
		// (mid-rollout), HTTPInternalAddrs returns empty and the discovery
		// helper returns false → falls through to the local handler with
		// DissStore-backed object fetch.
		var addrs []string
		if s.UseInternalAddr {
			addrs = loader.Storage().HTTPInternalAddrs()
		} else {
			addrs = loader.Storage().HTTPAddrs()
		}
		// Three-tier ordering, all GET /info/refs:
		//   1. HandleInfoRefsDiscovery — sets X-Entire-Replicas and 307s
		//      to a hosting replica when this node doesn't host the
		//      repo (or always for ALB-routed traffic). Must run first
		//      so v2 clients still get the replica redirect.
		//   2. serveV2InfoRefs — emits the v2 capability advertisement
		//      when the client sent `Git-Protocol: version=2` AND a
		//      V2Registry is configured. Must run BEFORE HandleInfoRefs
		//      because that handler returns true for every
		//      service=git-upload-pack request and would otherwise
		//      consume the v2 client's request as v0/v1.
		//   3. HandleInfoRefs — v0/v1 advertisement (the default). We
		//      override go-git's AdvertiseRefs here because upstream
		//      omits the object-format capability on receive-pack,
		//      which makes real git clients abort SHA256 pushes with
		//      "the receiving end does not support this repository's
		//      hash algorithm".
		if s.HandleInfoRefsDiscovery(w, r, addrs) {
			if adminapi.IsShuttingDown(s.Shutdown) {
				emitStepdownRedirected(r, "infoRefs")
			}
			return
		}
		// Declined while draining means no replica was available to take the
		// client, and advertising refs here would promise a pack this node
		// will not serve.
		if adminapi.IsShuttingDown(s.Shutdown) {
			assert.Reachable("infoRefs: rejected during shutdown with 503", nil)
			emitStepdownRejected(r, "infoRefs")
			http.Error(w, "node is shutting down", http.StatusServiceUnavailable)
			return
		}
		if s.serveV2InfoRefs(w, r, loader.Storage()) {
			return
		}
		if HandleInfoRefs(w, r, loader.Storage(), HideRefsFrom(s.refPolicyResolver())) {
			return
		}
	}

	if r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/git-receive-pack") {
		// receive-pack consults the repos row for two policy decisions —
		// mirror routing and per-repo push-size override — so a row read
		// must be definitive before we proceed. ErrNotFound is a
		// definitive "not a mirror, no override"; any other error is
		// indeterminate, and we 503 rather than risk silently treating a
		// real mirror as a regular repo (which would store a divergent
		// local-only push) or ignoring an admin's push-size cap.
		repoRow, repoRowFound, err := s.fetchRepoRow(ctx, repoID)
		if err != nil {
			slogutil.Error(ctx, "repo state lookup failed", slog.String("repo_id", repoID.String()), slog.Any("error", err))
			http.Error(w, "repo state lookup unavailable, retry later", http.StatusServiceUnavailable)
			return
		}
		// Stamp the repo's shared repo-group ULID onto the storer so the
		// ref-event sinks carry it onto every emitted RefEvent. The row read
		// above is the push path's single per-repo state load, so this reuses
		// it rather than re-querying at emit time. It must go on the storer,
		// not the request context: resolveRepoLoader already bound the storer's
		// context (above), and the CAS entry points emit on that bound context,
		// not r.Context(). A legacy row can still be empty until the data-plane
		// group backfill has re-driven its placement.
		loader.Storage().SetRepoGroupID(repoRow.RepoGroupID)
		// Mirror-worker resync republishes what it just fetched from
		// upstream, so it bypasses the per-repo / cluster push-size cap
