// settings are the knobs this store's generations are a pure function of.
func (f *Follower) settings() settings.Settings { return f.config }

// AdoptSettings says that this store's settings are meant to differ from the
// last generation's, and lets one compaction publish the change.
//
// Deliberately one compaction and not a mode. The hazard is not an operator
// changing a setting, which is ordinary; it is two clones disagreeing about one
// and taking turns laying the store out each generation, with narrow reads right
// half the time. A single acknowledgement covers the first and keeps reporting
// the second.
//
// A method rather than a field on Settings, because it is not a setting: no
// generation's bytes depend on it, it must not appear in Differs, and it is spent
// after one compaction.
func (s *Store) AdoptSettings() { s.adoptSettings = true }

// writerKey holds this clone's writer identity. Git config is the right home for
// it: local to the clone, never pushed, and it survives a working-tree wipe.
func writerKey(name string) string { return localConfigPrefix + name + ".writer" }

// declaredKey holds the settings this clone created the store with.
//
// Local, like the writer identity above, and for the same reason: it is a fact
// about this clone rather than about the store. It exists because a store's shape
// is recorded in the generations it publishes, and between Prepare and the first
// of those nothing can say what the shape is — which is the window a follower
// cannot get out of on its own, since compaction is the verb that closes it.
//
// Never the authority. Declared prefers a published generation whenever there is
// one, because that is what every clone agreed about; this only answers before
// there is anything to agree about.
func (s *Store) declaredKey() string { return localConfigPrefix + s.name + ".settings" }

// Open prepares a store in an existing repository, minting this clone's writer
// identity on first use.
//
// The identity is per clone and opaque. It must never be derived from an author
// or a machine: two processes that both claimed one identity would reuse
// sequence numbers, and that is undetectable. A fresh clone is a fresh writer.
// The Settings a store is opened with are the ones every clone of it must agree
// about, and each generation records them so that a disagreement says what it is.
func Open(d git.Driver, tp git.Transport, repoDir, name string, config settings.Settings) (*Store, error) {
	config, shape, err := shaped(name, config)
	if err != nil {
		return nil, err
	}
	// A store name becomes a ref path component, so git's rules decide, not ours.
	// A character check passes things git refuses — "..", "a.lock", a leading dot
	// — and the failure would otherwise surface much later, from update-ref, with
	// nothing pointing at the name as the cause. So the layout says what to ask
	// about and git answers.
	probe, err := reflayout.For(name).Probe()
	if err != nil {
		return nil, fmt.Errorf("store: %q is not a usable store name: %w", name, err)
	}
	repo, err := d.Open(repoDir)
	if err != nil {
		return nil, err
	}
	if err := repo.CheckRefFormat(probe); err != nil {
		return nil, fmt.Errorf("store: %q cannot be a store name: %w", name, err)
	}

	writer, err := repo.ConfigGet(writerKey(name))
	if err != nil {
		return nil, err
	}
	if writer == "" {
		if writer, err = stamp.NewWriterID(); err != nil {
			return nil, err
		}
		if err := repo.ConfigSet(writerKey(name), writer); err != nil {
			return nil, err
		}
	}
	if err := stamp.ValidWriterID(writer); err != nil {
		return nil, fmt.Errorf("store: writer identity in git config is unusable: %w", err)
	}
	return wrap(newFollower(repo, name, writer, config, shape), repo, tp), nil
}

// wrap puts the write half around a follower.
//
// One literal, here, for Open and for a test twinning a store. What matters is
// that `reached` is a map, so a literal that forgot it would hand back a Store
// that panics on its first push — and a second literal is exactly how that gets
// forgotten.
func wrap(f *Follower, repo git.Repo, tp git.Transport) *Store {
	return &Store{Follower: f, repo: repo, transport: tp, reached: map[string]bool{}}
}

// Prepare makes a repository into a store this clone can write to, creating the
// repository if it is not one yet.
//
// The sibling of Open, and the only one of the two that configures anything. Open
// attaches to a store and must leave the repository exactly as it found it, so
// that a projector reading a store is not the thing that reconfigures it; this is
// for a caller that has asked us to set one up.
//
// The order is the whole reason this exists rather than being three lines at each
// call site, and every step of it has a reason:
//
//   - The repository first, because there is nothing to configure until there is
//     one. A repository this creates is made crash-safe by the driver's Init;
//     one that already existed is not, which is the gap this closes — git does
//     not fsync loose objects by default, so a crash can keep a ref and lose the
//     object it names, and Check exists to find exactly that. Three callers wrote this
//     sequence out and two of them left the crash-safety line out of it.
//
//   - The remote before the announcement, because announcing fetches from it.
//
//   - The announcement last, because it is the one step that needs the
//     network. It announces this writer against a view of what the store has
//     already folded, so the low-water mark it promises is not below finished
//     work — everything after it is offline. Only when there is a remote: a
//     store nobody shares needs no announcement, and a writer announced earlier
//     than it writes holds the barrier further back than it has to.
//
// Idempotent, so an application may call it every time it starts: the repository
// is created only if absent, an announcement returns early if this writer has
// one, and the crash-safety settings are the same two config writes either way.
//
// A store that is only going to be read wants Open. An announced writer that
// never writes holds the barrier where it stood.
func Prepare(d git.Driver, tp git.Transport, repoDir, name string, config settings.Settings, originURL string) (*Store, error) {
	if _, err := d.Open(repoDir); err != nil {
		if _, err := d.Init(repoDir, git.InitOptions{}); err != nil {
			return nil, err
		}
	}
	s, err := Open(d, tp, repoDir, name, config)
	if err != nil {
		return nil, err
	}
	remote, err := s.remote()
	if err != nil {
		return nil, err
	}
	if remote == "" {
		remote = defaultRemote
	}
	if originURL != "" {
		if err := s.Configure(remote, originURL); err != nil {
			return nil, err
		}
	}
	if err := s.repo.MakeCrashSafe(); err != nil {
		return nil, err
	}
	// What this store was created as, so a tool that follows a store rather than
	// declaring one has something to read before the first generation records it.
	if err := s.repo.ConfigSet(s.declaredKey(),
		hex.EncodeToString(wire.EncodeSettings(config))); err != nil {
		return nil, err
	}
	if originURL == "" {
		return s, nil
	}
	if err := s.Announce(remote); err != nil {
		return nil, err
	}
	return s, nil
}

// defaultRemote is the name Prepare wires a URL under when the store has no
// remote yet; once it has one, renamed or not, Prepare keeps it. A caller that
// wants another name has Open, Configure and Announce, which is what Prepare is
// composed of.
const defaultRemote = "origin"

// Writer returns this clone's writer identity.
func (s *Store) Writer() string { return s.writer }

// Load derives state: the newest generation, then every op still held by every
// log.
//
// The ops are folded over the generation without filtering by boundary. That is
// safe and it is why compaction needs no bookkeeping about which ops it consumed:
// the fold is idempotent, and a generation already holds the winner for
// everything below its boundary, so re-folding those ops changes nothing. It also
// means an op that arrives late, below a boundary already published, is folded
// correctly rather than silently skipped — it simply loses on stamp, which is the
// right answer. What makes reads cheap is pruning the segments, not filtering
// them.
func (f *Follower) Load() (*record.State, []record.Conflict, error) {
	return f.loadNarrowed(f.shape.Everything())
}

// LoadTypes folds only the named types.
//

