10	)
11	
12	// Since is where a read of a store stopped, in the store's own terms: the commit
13	// each of its refs named, and the erasures in force. It is what lets a reader
14	// that kept nothing of the repository read on from there, holding only what was
15	// written after it (docs/adr/0025).
16	//
17	// It sits beside project.Cursor rather than inside it. A cursor is how far a
18	// read model has consumed the store, and means the same over any transport; a
19	// Since is where in the repository that consumption was read from, and is git's.
20	//
21	// The erasures are carried because they are the one answer a read cannot give
22	// from the new entries alone. A batch restates every erasure in force, and the
23	// set is drawn from the newest generation and every entry in the tail — most of
24	// which a reader that kept nothing no longer holds. Between two reads the set
25	// only grows by what the new entries carry: it shrinks by discharge, and
26	// discharge happens at compaction and prune, which publish a generation or
27	// rotate a log, which is a whole read.
28	type Since struct {
29		// Tips maps the refs a feed reads — see Tips — by the names they are
30		// published under, to the commits they named. Nil when nothing has been
31		// read, which makes the next read whole.
32		Tips map[string]string
33		// Erased is the set the last batch restated.
34		Erased erasure.Set
35	}
36	
37	// ErrNotIncremental is FeedSince finding that the repository does not hold what
38	// reading on needs: an entry it should hold is missing, or a log does not reach
39	// back to where the last read stopped. The answer is a whole read, from a
40	// repository fetched for one.
41	var ErrNotIncremental = errors.New("store: cannot read on from where the last read stopped")
42	
43	// Fetch is what a reader holding nothing but a Since must fetch to read on.
44	type Fetch struct {
45		// Incremental is whether the read can go on from the Since. When it
46		// cannot, Wants is every tip.
47		Incremental bool
48		// Wants are the refs whose commits must be fetched, by published name.
49		Wants map[string]string
50		// Haves are commits the remote may assume are held. They are not, which is
51		// the point: the remote sends what is newer than them, and a read on stops
52		// at them.
53		Haves []string
54	}
55	
56	// Tips names, from a listing of a remote's refs, the ones a Since records: the
57	// store's generations and each writer's newest log. Those are all a feed reads.
58	// Announcements and evictions it reads only by name, and an older rotation is
59	// one a prune is still withdrawing, which a survey passes over too.
60	//
61	// Exported for the reader that compares a listing against the Since it holds,
62	// so that "nothing moved" means what FetchFor and FeedSince mean by it.
63	func Tips(name string, listed map[string]string) map[string]string {
64		type newest struct {
65			n        uint64
66			ref, oid string
67		}
68		tips := map[string]string{}
69		logs := map[string]newest{}
70		for ref, oid := range listed {
71			r := reflayout.Parse(ref)
72			if r.Store != name || r.Remote != "" {
73				continue
74			}
75			switch r.Kind {
76			case reflayout.Gen:
77				tips[ref] = oid
78			case reflayout.LogRotation:
79				if cur, seen := logs[r.Writer]; !seen || r.Rotation > cur.n {
80					logs[r.Writer] = newest{r.Rotation, ref, oid}
81				}
82			}
83		}
84		for _, l := range logs {
85			tips[l.ref] = l.oid
86		}
87		return tips
88	}
89	
90	// tips is Tips over what a survey found.
91	func (sv *survey) tips() map[string]string {
92		tips := make(map[string]string, len(sv.gens)+len(sv.logs))
93		for n, oid := range sv.gens {
94			tips[sv.refs.Gen(n)] = oid
95		}
96		for w, at := range sv.logs {
97			tips[sv.logOf(w).ref()] = at.tip
98		}
99		return tips
100	}
101	
102	// FetchFor decides, from what a remote advertises for a store, what a reader
103	// that last stopped at since has to fetch. FeedSince makes the same decision
104	// from the refs it is handed, by the same function, so a fetch and the read
105	// after it cannot disagree about whether the read goes on.
106	func FetchFor(name string, since Since, advertised map[string]string) Fetch {
107		tips := Tips(name, advertised)
108		if !incremental(since, tips) {
109			return Fetch{Wants: tips}
110		}
111		plan := Fetch{Incremental: true, Wants: map[string]string{}}
112		for ref, oid := range tips {
113			// A generation that is still a tip is unchanged, and is not read.
114			if was := since.Tips[ref]; was != oid && reflayout.Parse(ref).Kind == reflayout.LogRotation {
115				plan.Wants[ref] = oid
116				if was != "" {
117					plan.Haves = append(plan.Haves, was)
118				}
119			}
120		}
121		return plan
122	}
123	
124	// incremental is whether every change between since and now is a log growing
125	// or a writer's first log appearing. Anything else changes what the last read
126	// was drawn from: a generation published, a log rotated by a prune, a log
127	// deleted by retirement, a generation by retention. Each of those is what
128	// discharges an erasure or reseeds a projection, and each is read whole.
129	//
130	// A rotation needs no rule of its own: the rotation it replaced is no longer
131	// the writer's newest, so it is missing from now.
132	func incremental(since Since, now map[string]string) bool {
133		if since.Tips == nil {
134			return false
135		}
136		for ref := range since.Tips {
137			if _, ok := now[ref]; !ok {
138				return false
139			}
140		}
141		for ref, oid := range now {
142			if reflayout.Parse(ref).Kind == reflayout.Gen && since.Tips[ref] != oid {
143				return false
144			}
145		}
146		return true
147	}
148	
149	// FeedSince is Feed for a reader that holds only what was written after since,
150	// and returns where this read stopped for the next one.
151	//
152	// When the store has changed in a way FetchFor reads whole, so does this, and
153	// it then needs the repository a whole fetch leaves. Otherwise it is Feed over
154	// a survey that reads each log back to where since stood and no further, and
155	// starts the erasures from since's set, so it never asks for an object the
156	// fetch did not bring. A log that does not reach back is ErrNotIncremental,
157	// never a guess.
158	func (f *Follower) FeedSince(c project.Cursor, since Since) (project.Batch, Since, error) {
159		sv, err := f.survey()
160		if err != nil {
161			return project.Batch{}, Since{}, err
162		}
163		tips := sv.tips()
164		if incremental(since, tips) {
165			// A generation the cursor has not consumed needs a seed, which needs
166			// the generation, which an incremental fetch does not bring.
167			if latest := sv.latest(); latest != c.Generation {
168				return project.Batch{}, Since{}, fmt.Errorf("%w: the cursor is at generation %d and the store at %d",
169					ErrNotIncremental, c.Generation, latest)
170			}
171			sv.since = &since
172		}
173		batch, err := f.feed(sv, c)
174		if err != nil {
175			return project.Batch{}, Since{}, err
176		}
177		return batch, Since{Tips: tips, Erased: batch.Erased}, nil
178	}
