// store's generations and each writer's newest log. Those are all a feed reads.
// Announcements and evictions it reads only by name, and an older rotation is
// one a prune is still withdrawing, which a survey passes over too.
//
// Exported for the reader that compares a listing against the Since it holds,
// so that "nothing moved" means what FetchFor and FeedSince mean by it.
func Tips(name string, listed map[string]string) map[string]string {
	type newest struct {
		n        uint64
		ref, oid string
	}
	tips := map[string]string{}
	logs := map[string]newest{}
	for ref, oid := range listed {
		r := reflayout.Parse(ref)
		if r.Store != name || r.Remote != "" {
			continue
		}
		switch r.Kind {
		case reflayout.Gen:
			tips[ref] = oid
		case reflayout.LogRotation:
			if cur, seen := logs[r.Writer]; !seen || r.Rotation > cur.n {
				logs[r.Writer] = newest{r.Rotation, ref, oid}
			}
		}
	}
	for _, l := range logs {
		tips[l.ref] = l.oid
	}
	return tips
}

// tips is Tips over what a survey found.
func (sv *survey) tips() map[string]string {
	tips := make(map[string]string, len(sv.gens)+len(sv.logs))
	for n, oid := range sv.gens {
		tips[sv.refs.Gen(n)] = oid
	}
	for w, at := range sv.logs {
		tips[sv.logOf(w).ref()] = at.tip
	}
	return tips
}

// FetchFor decides, from what a remote advertises for a store, what a reader
// that last stopped at since has to fetch. FeedSince makes the same decision
// from the refs it is handed, by the same function, so a fetch and the read
// after it cannot disagree about whether the read goes on.
func FetchFor(name string, since Since, advertised map[string]string) Fetch {
	tips := Tips(name, advertised)
	if !incremental(since, tips) {
		return Fetch{Wants: tips}
	}
	plan := Fetch{Incremental: true, Wants: map[string]string{}}
	for ref, oid := range tips {
		// A generation that is still a tip is unchanged, and is not read.
		if was := since.Tips[ref]; was != oid && reflayout.Parse(ref).Kind == reflayout.LogRotation {
			plan.Wants[ref] = oid
			if was != "" {
				plan.Haves = append(plan.Haves, was)
			}
		}
	}
	return plan
}

// incremental is whether every change between since and now is a log growing
// or a writer's first log appearing. Anything else changes what the last read
// was drawn from: a generation published, a log rotated by a prune, a log
// deleted by retirement, a generation by retention. Each of those is what
// discharges an erasure or reseeds a projection, and each is read whole.
//
// A rotation needs no rule of its own: the rotation it replaced is no longer
// the writer's newest, so it is missing from now.
func incremental(since Since, now map[string]string) bool {
	if since.Tips == nil {
		return false
	}
	for ref := range since.Tips {
		if _, ok := now[ref]; !ok {
			return false
		}
	}
	for ref, oid := range now {
		if reflayout.Parse(ref).Kind == reflayout.Gen && since.Tips[ref] != oid {
			return false
		}
	}
	return true
}

// FeedSince is Feed for a reader that holds only what was written after since,
// and returns where this read stopped for the next one.
//
// When the store has changed in a way FetchFor reads whole, so does this, and
// it then needs the repository a whole fetch leaves. Otherwise it is Feed over
// a survey that reads each log back to where since stood and no further, and
// starts the erasures from since's set, so it never asks for an object the
// fetch did not bring. A log that does not reach back is ErrNotIncremental,
// never a guess.
func (f *Follower) FeedSince(c project.Cursor, since Since) (project.Batch, Since, error) {
	sv, err := f.survey()
	if err != nil {
		return project.Batch{}, Since{}, err
	}
	tips := sv.tips()
	if incremental(since, tips) {
		// A generation the cursor has not consumed needs a seed, which needs
		// the generation, which an incremental fetch does not bring.
		if latest := sv.latest(); latest != c.Generation {
			return project.Batch{}, Since{}, fmt.Errorf("%w: the cursor is at generation %d and the store at %d",
				ErrNotIncremental, c.Generation, latest)
		}
		sv.since = &since
	}
	batch, err := f.feed(sv, c)
	if err != nil {
		return project.Batch{}, Since{}, err
	}
	return batch, Since{Tips: tips, Erased: batch.Erased}, nil
}

