    11		"github.com/entirehq/entire-api/internal/stratagit"
    12	)
    13	
    14	// ReadsStrataPlans pages through this cell's records read of the planning
    15	// store's plans and returns how many there are. The read comes from this cell's
    16	// projection, caught up from its strata repository as EnableRecords catches it
    17	// up from entiredb.
    18	func (a cellAPI) ReadsStrataPlans(r *Repo) int {
    19		c := a.c
    20		t := c.w.t
    21		t.Helper()
    22		if c.strataDir == "" {
    23			t.Fatalf("%s has no strata repository to read", c.name)
    24		}
    25		if c.repoDeps.RecordsReader == nil {
    26			dir := c.strataDir
    27			c.repoDeps.RecordsReader = records.New(recordprojection.Reads{Store: c.repoDeps.Store,
    28				Remote: func(context.Context, string) stratagit.Remote { return stratagit.Remote{URL: dir} }})
    29		}
    30		n, token := 0, ""
    31		for {
    32			path := "/api/v0/repos/" + r.In(c) + "/records/planning/collections/plan?pageSize=100"
    33			if token != "" {
    34				path += "&pageToken=" + url.QueryEscape(token)
    35			}
    36			got := c.attempt(http.MethodGet, path, nil)
    37			if got.Status != http.StatusOK {
    38				t.Fatalf("%s: reading plans: HTTP %d: %s", c.name, got.Status, got.Body)
    39			}
    40			var page struct {
    41				Items []json.RawMessage `json:"items"`
    42				Next  string            `json:"nextPageToken"`
    43			}
    44			if err := json.Unmarshal([]byte(got.Body), &page); err != nil {
    45				t.Fatalf("%s: decoding plans: %v", c.name, err)
    46			}
    47			n += len(page.Items)
    48			if page.Next == "" {
    49				return n
    50			}
    51			token = page.Next
    52		}
    53	}
    54	
    55	// StrataGenerations is the oldest and newest generation of the planning store
    56	// in this cell's strata repository, as a fresh clone sees them.
    57	func (c *Cell) StrataGenerations() (oldest, newest uint64) {
    58		c.w.t.Helper()
    59		s, err := stratagit.Remote{URL: c.strataDir}.Open(context.Background(), "planning")
    60		if err != nil {
    61			c.w.t.Fatalf("%s: opening its strata store: %v", c.name, err)
    62		}
    63		report, err := s.Status()
    64		if err != nil {
    65			c.w.t.Fatalf("%s: surveying its strata store: %v", c.name, err)
    66		}
    67		return report.OldestGeneration, report.Generation
    68	}
    69	
    70	// AssertStrataGenerationDropped fails unless generation g is older than every
    71	// generation this cell's strata repository still holds.
    72	func (c *Cell) AssertStrataGenerationDropped(g uint64) {
    73		c.w.t.Helper()
    74		if oldest, newest := c.StrataGenerations(); oldest <= g {
    75			c.w.t.Fatalf("%s: generation %d is still held (%d..%d)", c.name, g, oldest, newest)
    76		}
    77	}
		a.c.w.t.Fatalf("%s: decode created project Trail: %v (%s)", a.c.name, err, attempt.Body)
