func (c *Cell) AssertStrataPlanLanded() {
	c.w.t.Helper()
	s, err := stratagit.Remote{URL: c.strataDir}.Open(context.Background(), "planning")
	if err != nil {
		c.w.t.Fatalf("%s: opening its strata store: %v", c.name, err)
	}
	plans, err := recordapi.New(recstore.OpenStore(s, recstore.SchemaRef{Name: "planning"}, "", true)).
		ListRecords("plan", recordapi.ListOptions{})
	if err != nil {
		c.w.t.Fatalf("%s: listing plans: %v", c.name, err)
	}
	for _, p := range plans {
		if p.Fields["title"] == c.name {
			return
		}
	}
	c.w.t.Fatalf("%s: no plan titled %q in its strata store", c.name, c.name)
}

// WritesStrataEdits POSTs a strata edit into this cell, against a local bare
// repository standing in for entiredb with the planning store created.
func (a cellAPI) WritesStrataEdits(r *Repo) WriteAttempt {
	a.c.w.t.Helper()
	a.c.ensureStrataStore()
	return a.c.attempt(http.MethodPost, "/api/v0/repos/"+r.In(a.c)+"/strata/planning/edits",
		map[string]any{"writes": []map[string]any{{"type": "plan", "fields": map[string]any{"title": a.c.name}}}})
}

func (c *Cell) ensureStrataStore() {
	c.w.t.Helper()
	if c.repoDeps.StrataRepoURL != nil {
		return
	}
	dir := c.useStrataRepo()
	if err := (stratawrite.Remote{URL: dir}).Create(context.Background(), stratawritetest.Planning(), ""); err != nil {
		c.w.t.Fatalf("%s: creating the strata store: %v", c.name, err)
	}
}

